import java.util.regex.Pattern;

public class main {
    // 缓存编解码模块: 键白名单, 仅字母数字下划线连字符, 长度1-64
    private static final Pattern SAFE_KEY = Pattern.compile("^[A-Za-z0-9_\\-]{1,64}$");

    // 入口1: 常规缓存查询(主数据流, 先解码后白名单校验)
    public static String handleLookup(String cacheId) {
        String decoded = helper.decodePayload(cacheId);
        if (decoded == null || !SAFE_KEY.matcher(decoded).matches()) {
            return "ERR_INVALID_KEY";
        }
        return helper.fetchCacheRow(decoded);
    }

    // 入口2: 运维批量失效(仅内部调用, 只做长度检查)
    public static String handlePurge(String tagExpr) {
        if (tagExpr == null || tagExpr.isEmpty() || tagExpr.length() > 128) {
            return "ERR_BAD_TAG";
        }
        String expr = helper.urlDecode(tagExpr);
        return helper.fetchCacheRow(expr);
    }

    // 入口3: 缓存回放(候选流, 走预编译)
    public static String handleReplay(String payload) {
        String val = helper.urlDecode(payload);
        return helper.fetchCacheRowPrepared(val);
    }

    public static void main(String[] args) {
        String op = args.length > 0 ? args[0] : "lookup";
        String arg = args.length > 1 ? args[1] : "";
        if (op.equals("lookup")) {
            System.out.println(handleLookup(arg));
        } else if (op.equals("purge")) {
            System.out.println(handlePurge(arg));
        } else {
            System.out.println(handleReplay(arg));
        }
    }
}
