import java.net.URLDecoder;
import java.sql.*;

public class helper {
    // 共享 sink: 缓存行查询, 键直接拼接 SQL
    static String fetchCacheRow(String key) {
        try (Connection c = DriverManager.getConnection(System.getenv("CACHE_DB_URL"))) {
            Statement st = c.createStatement();
            String sql = "SELECT payload FROM cache_entries WHERE cache_key='" + key + "'";
            ResultSet rs = st.executeQuery(sql);
            return rs.next() ? rs.getString(1) : "MISS";
        } catch (SQLException e) { return "DBERR"; }
    }

    // 安全对照: 预编译参数化查询
    static String fetchCacheRowPrepared(String key) {
        try (Connection c = DriverManager.getConnection(System.getenv("CACHE_DB_URL"))) {
            PreparedStatement ps = c.prepareStatement("SELECT payload FROM cache_entries WHERE cache_key=?");
            ps.setString(1, key);
            ResultSet rs = ps.executeQuery();
            return rs.next() ? rs.getString(1) : "MISS";
        } catch (SQLException e) { return "DBERR"; }
    }

    // 两段式解码: URL 解码 + Base64
    static String decodePayload(String raw) {
        try {
            String once = URLDecoder.decode(raw, "UTF-8");
            return new String(java.util.Base64.getDecoder().decode(once));
        } catch (Exception e) { return raw; }
    }

    static String urlDecode(String raw) {
        try { return URLDecoder.decode(raw, "UTF-8"); }
        catch (Exception e) { return raw; }
    }
}
