package main

import (
	"encoding/json"
	"net/http"
	"strconv"
)

var helper *ForwardHelper

func main() {
	helper = NewForwardHelper()
	http.HandleFunc("/forward", handleForward)
	http.HandleFunc("/route", handleRoute)
	http.HandleFunc("/probe", handleProbe)
	_ = http.ListenAndServe(":8080", nil)
}

// 入口1 /forward: tenant 参数进入后端解析
func handleForward(w http.ResponseWriter, r *http.Request) {
	tenant := NormalizeTenant(r.URL.Query().Get("tenant"))
	backend := helper.ResolveBackend(tenant)
	_ = json.NewEncoder(w).Encode(map[string]string{"backend": backend})
}

// 入口2 /route: region 参数进入节点查询
func handleRoute(w http.ResponseWriter, r *http.Request) {
	region := r.URL.Query().Get("region")
	if !IsAllowedRegion(region) {
		http.Error(w, "region not allowed", http.StatusForbidden)
		return
	}
	_ = json.NewEncoder(w).Encode(map[string]string{"node": helper.LookupNode(region)})
}

// 入口3 /probe: shard 参数进入分片探活
func handleProbe(w http.ResponseWriter, r *http.Request) {
	idx, err := strconv.Atoi(r.URL.Query().Get("shard"))
	if err != nil {
		http.Error(w, "invalid shard", http.StatusBadRequest)
		return
	}
	_ = json.NewEncoder(w).Encode(map[string]string{"state": helper.ProbeShard(idx)})
}
