package main

import (
	"database/sql"
	"fmt"
	"strings"
)

// NormalizeTenant 伪净化: 仅去首尾空白, 不构成注入防御
func NormalizeTenant(s string) string { return strings.TrimSpace(s) }

var allowedRegions = map[string]bool{"cn-north-1": true, "eu-west-1": true} // 真防御: 枚举白名单

func IsAllowedRegion(region string) bool { return allowedRegions[region] }

type ForwardHelper struct{ db *sql.DB }

func NewForwardHelper() *ForwardHelper {
	db, _ := sql.Open("mysql", "gateway_ro@tcp(127.0.0.1:3306)/gw_meta")
	return &ForwardHelper{db: db}
}

// ResolveBackend 流1: tenant 未经参数化直接拼接 → 可达 sink
func (h *ForwardHelper) ResolveBackend(tenant string) string {
	q := fmt.Sprintf("SELECT backend FROM routes WHERE tenant='%s'", tenant)
	var backend string
	_ = h.db.QueryRow(q).Scan(&backend)
	return backend
}

// LookupNode 流2: region 已在 main.go 入口白名单校验, 拼接不可注入
func (h *ForwardHelper) LookupNode(region string) string {
	q := "SELECT node FROM nodes WHERE region='" + region + "'"
	var node string
	_ = h.db.QueryRow(q).Scan(&node)
	return node
}

// ProbeShard 流3: idx 已在入口转 int, 格式化无注入面
func (h *ForwardHelper) ProbeShard(idx int) string {
	q := fmt.Sprintf("SELECT state FROM shards WHERE shard_id=%d", idx)
	var state string
	_ = h.db.QueryRow(q).Scan(&state)
	return state
}
