import java.util.Map;
import java.util.regex.Pattern;

public class main {
    private static final Pattern SAFE_NAME = Pattern.compile("^[a-z0-9_-]{1,32}$");
    private static final Helper helper = new Helper();

    // 入口1: action=render, 按白名单渲染邮件模板
    public String handleRender(String tplName) {
        if (tplName == null || !SAFE_NAME.matcher(tplName).matches()) {
            return "invalid template name";
        }
        return helper.renderTemplate("/var/mailtpl/" + tplName + ".html");
    }

    // 入口2: action=export, 将模板导出为 PDF 附件
    public String handleExport(String tplName, String outName) {
        if (tplName == null || !SAFE_NAME.matcher(tplName).matches()) return "bad tpl";
        if (outName == null || !SAFE_NAME.matcher(outName).matches()) return "bad out";
        return helper.exportPdf(tplName, outName);
    }

    // 入口3: action=preview, 按主题生成模板预览图
    public String handlePreview(String theme, String tplName) {
        String t = (theme == null) ? "default" : theme.replace('\n', ' ').trim();
        String tpl = (tplName == null) ? "welcome" : tplName;
        return helper.renderPreview(t, tpl);
    }

    public String dispatch(String action, Map<String, String> params) {
        if ("render".equals(action)) return handleRender(params.get("tpl"));
        if ("export".equals(action)) return handleExport(params.get("tpl"), params.get("out"));
        if ("preview".equals(action)) return handlePreview(params.get("theme"), params.get("tpl"));
        return "unknown action";
    }
}
