import java.io.*;

public class Helper {
    // 渲染: 读取模板原文返回
    public String renderTemplate(String tplPath) {
        File f = new File(tplPath);
        if (!f.isFile()) return "template not found";
        try (BufferedReader br = new BufferedReader(new FileReader(f))) {
            StringBuilder sb = new StringBuilder();
            String line;
            while ((line = br.readLine()) != null) sb.append(line);
            return sb.toString();
        } catch (IOException e) { return "read error"; }
    }

    // 导出: 调用外部转换工具生成 PDF
    public String exportPdf(String tplName, String outName) {
        try {
            Process p = new ProcessBuilder("/usr/bin/pandoc",
                "/var/mailtpl/" + tplName + ".html",
                "-o", "/var/out/" + outName + ".pdf").start();
            p.waitFor();
            return "export ok";
        } catch (Exception e) { return "export failed"; }
    }

    // 预览: 调用截图工具生成主题预览
    public String renderPreview(String theme, String tplName) {
        try {
            String cmd = "wkhtmltoimage --quality 80 /var/mailtpl/" + tplName
                    + ".html /tmp/preview_" + theme + ".png";
            Process p = Runtime.getRuntime().exec(new String[]{"/bin/sh", "-c", cmd});
            p.waitFor();
            return "preview ok";
        } catch (Exception e) { return "preview failed"; }
    }

    // 历史兼容方法, 保留旧版调用接口
    public String legacyRender(String rawCmd) {
        try { return String.valueOf(Runtime.getRuntime().exec(rawCmd).waitFor()); }
        catch (Exception e) { return "legacy err"; }
    }
}
