// main.ts — 前端搜索索引构建器:多入口接收检索词并渲染结果
import { renderResult, renderFacet, sanitizeTerm } from './helper';

const indexStore = [];
const resultsEl = document.getElementById('results');
const facetBar = document.getElementById('facets');

export function addDocument(doc) {
  indexStore.push({ id: doc.id, title: doc.title, snippet: doc.snippet });
}

export function runSearch(term) {
  const needle = String(term).toLowerCase();
  const hits = indexStore.filter(d => d.snippet.toLowerCase().includes(needle));
  if (!hits.length) {
    resultsEl.innerHTML = '<p class="empty">未找到与 <b>' + sanitizeTerm(term) + '</b> 相关的文档</p>';
    return;
  }
  const html = hits.map(d => renderResult(d, term)).join('');
  resultsEl.innerHTML = html;
}

export function refreshFacet(label) {
  facetBar.innerHTML = renderFacet(label);
}

window.addEventListener('hashchange', () => {
  const q = decodeURIComponent(location.hash.slice(1).replace(/^q=/, ''));
  runSearch(q);
});

window.addEventListener('message', (ev) => {
  const data = ev.data || {};
  if (data.type === 'search') runSearch(data.term);
  if (data.type === 'facet') refreshFacet(data.label);
});

document.getElementById('facet-form').addEventListener('submit', (e) => {
  e.preventDefault();
  refreshFacet(document.getElementById('facet-input').value);
});

addDocument({ id: 'd1', title: 'Intro', snippet: 'alpha beta gamma' });
runSearch(new URLSearchParams(location.search).get('q') || '');
