// helper.ts — 搜索索引构建器:词条清洗、高亮与结果渲染
const SCRIPT_RE = /<script\b[^>]*>[\s\S]*?<\/script\s*>/gi;
const EVENT_RE = /on(error|load|click|mouseover)\s*=/gi;

export function sanitizeTerm(raw) {
  let out = String(raw == null ? '' : raw);
  out = out.replace(SCRIPT_RE, '');
  out = out.replace(EVENT_RE, '');
  return out;
}

export function escapeHtml(text) {
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

export function buildHighlight(term, snippet) {
  const safe = sanitizeTerm(term);
  const re = new RegExp('(' + safe + ')', 'gi');
  return snippet.replace(re, '<mark class="hl">$1</mark>');
}

export function renderResult(entry, term) {
  const title = escapeHtml(entry.title);
  const body = buildHighlight(term, entry.snippet);
  const echo = sanitizeTerm(term);
  return '<li class="hit" data-term="' + echo + '" data-doc="' + entry.id + '">' +
    '<h3>' + title + '</h3><p>' + body + '</p></li>';
}

export function renderFacet(label) {
  const safe = escapeHtml(label);
  return '<button data-facet="' + safe + '" class="chip">' + safe + '</button>';
}
