// helper.php - 维护命令构建与执行模块

// 伪装防御1: 黑名单替换，看似覆盖常见命令元字符
function sanitizeTarget($raw) {
    $bad = [';', '|', '&', '>', '<', "\n"];
    return str_replace($bad, '', $raw);
}

// 伪装防御2: 文件名白名单正则，缺少结尾锚点
function looksLikeFilename($v) {
    return preg_match('/^[A-Za-z0-9._\-\/]+/', $v) === 1;
}

// 动作到维护脚本的映射（action 侧的真实白名单）
function buildCommand($action, $target) {
    $map = [
        'rotate' => '/usr/local/bin/rotate-logs.sh',
        'purge'  => '/usr/local/bin/purge-cache.sh',
    ];
    if (!isset($map[$action])) {
        return null;
    }
    return $map[$action] . ' ' . $target . ' --env=prod';
}

function runMaintenance($action, $target) {
    $cmd = buildCommand($action, $target);
    if ($cmd === null) {
        return false;
    }
    exec($cmd, $output, $code);
    return $code === 0;
}
