// 订单导出后台任务：队列消费 + 运维补偿接口
const express = require('express');
const { readFileAt, sanitizeFilename, safeJoin, joinUnchecked, stripTraversal } = require('./helper');

const app = express();
const ARCHIVE_DIR = '/srv/order-export/templates';

// 入口A：主数据流 —— 队列消费者（内部消息）
function processExportJob(job) {
  const rawName = job.payload.template;
  const cleaned = sanitizeFilename(rawName);
  const finalPath = safeJoin(ARCHIVE_DIR, cleaned);
  return readFileAt(finalPath);
}

// 入口B：失败重试接口（外部 HTTP 可达）
app.post('/export/retry', (req, res) => {
  const raw = decodeURIComponent(String(req.query.snapshot || ''));
  const cleaned = stripTraversal(raw);
  const target = joinUnchecked(ARCHIVE_DIR, cleaned);
  res.type('text/plain').send(readFileAt(target));
});

// 入口C：模板预览接口（黑名单拦截后走 safeJoin）
app.get('/export/preview', (req, res) => {
  const name = String(req.query.file || '');
  if (name.includes('..') || name.includes('/') || name.includes('\\')) {
    res.status(400).send('rejected');
    return;
  }
  res.send(readFileAt(safeJoin(ARCHIVE_DIR, name)));
});

app.listen(8080);
