// 订单导出辅助模块：路径净化与文件读取
const path = require('path');
const fs = require('fs');

// 净化器1：basename 剥离目录分量（强防御）
function sanitizeFilename(name) {
  return path.basename(name);
}

// 净化器2：单趟正则剔除 ../（弱：..././ 可重组出 ../）
function stripTraversal(input) {
  return input.replace(/\.\.\//g, '');
}

// 拼接A：resolve + 前缀校验（防御性）
function safeJoin(baseDir, userInput) {
  const resolved = path.resolve(baseDir, userInput);
  const baseWithSep = path.resolve(baseDir) + path.sep;
  if (!resolved.startsWith(baseWithSep)) {
    throw new Error('illegal path rejected');
  }
  return resolved;
}

// 拼接B：仅 path.join 不做校验（与 safeJoin 形似，实为陷阱）
function joinUnchecked(baseDir, relative) {
  return path.join(baseDir, relative);
}

// 统一 sink：读取磁盘文件
function readFileAt(filePath) {
  return fs.readFileSync(filePath, 'utf8');
}

module.exports = { sanitizeFilename, stripTraversal, safeJoin, joinUnchecked, readFileAt };
