<?php
// main.php - 数据同步工作线程入口（多入口分发）
declare(strict_types=1);

require_once __DIR__ . '/helper.php';

const SYNC_ROOT = '/var/lib/syncworker';

function handleSyncRequest(array $req): string {
    // 入口1: 主数据流 - 任务清单读取
    if (isset($req['job_id'])) {
        $jobId = sanitizeJobId((string)$req['job_id']);
        if ($jobId === null) {
            return 'ERR: invalid job_id';
        }
        return loadManifest(SYNC_ROOT . '/jobs', $jobId . '/manifest.json');
    }

    // 入口2: 第二入口 - 断点续传游标（未校验直通）
    if (isset($req['resume_from'])) {
        return resumeSync(SYNC_ROOT, (string)$req['resume_from']);
    }

    // 入口3: 快照读取（realpath 前缀防御）
    if (isset($req['snapshot'])) {
        $real = realpath(SYNC_ROOT . '/' . (string)$req['snapshot']);
        if ($real === false || strpos($real, SYNC_ROOT . DIRECTORY_SEPARATOR) !== 0) {
            return 'ERR: snapshot outside root';
        }
        return loadManifest(SYNC_ROOT, substr($real, strlen(SYNC_ROOT) + 1));
    }
    return 'ERR: no operation';
}

$payload = $_GET ?: $_POST;
echo handleSyncRequest($payload);
