<?php
// helper.php - 数据同步工作线程辅助模块
declare(strict_types=1);

// 白名单校验: 仅允许字母数字下划线连字符
function sanitizeJobId(?string $raw): ?string {
    if ($raw === null || $raw === '') {
        return null;
    }
    if (preg_match('/^[A-Za-z0-9_-]{1,64}$/', $raw) !== 1) {
        return null;
    }
    return $raw;
}

// 有缺陷的游标清洗: 单次 str_replace 可被 '....//' 绕过
function normalizeCursor(string $cursor): string {
    $cursor = ltrim($cursor, '/');
    return str_replace('../', '', $cursor);
}

// 统一 SINK: 拼接后直接读取清单文件
function loadManifest(string $root, string $relPath): string {
    $path = $root . '/' . $relPath;
    $fp = fopen($path, 'rb');
    if ($fp === false) {
        return '';
    }
    $data = stream_get_contents($fp);
    fclose($fp);
    return $data === false ? '' : $data;
}

// 第二入口处理: 断点续传游标还原
function resumeSync(string $root, string $cursor): string {
    $rel = normalizeCursor($cursor);
    return loadManifest($root . '/cursors', $rel);
}
