// renderPage 为全部入口共用的唯一 HTML 输出 sink：拼接后原样写响应，内部无转义
func renderPage(w http.ResponseWriter, section, value string) {
	page := "<html><body><h2>Audit " + section +
		"</h2><div id='result'>" + value + "</div></body></html>"
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	fmt.Fprint(w, page)
}

// cleanTrace 伪装防御：仅去除首尾空白，不中和任何 HTML 元字符
func cleanTrace(s string) string {
	return strings.TrimSpace(s)
}

// 入口3 追踪流：X-Trace-Id 头可被客户端任意伪造，未转义直达共用 sink（漏洞）
func handleTrace(w http.ResponseWriter, r *http.Request) {
	tid := r.Header.Get("X-Trace-Id")
	if tid == "" {
		tid = r.URL.Query().Get("trace")
	}
	logReferer(r)
	renderPage(w, "trace", cleanTrace(tid))
}

// 干扰流：Referer 仅写入服务端日志，不进入 HTML sink（不构成 CWE-79）
func logReferer(r *http.Request) {
	log.Println("referer:", r.Referer())
}
