package main

import (
	"errors"
	"net/url"
	"os"
	"path/filepath"
	"regexp"
	"strings"
)

var (
	datasetDir  = "/var/importer/datasets"
	archiveRoot = "/var/importer/archives"
	nameRe      = regexp.MustCompile(`^[A-Za-z0-9_\-]+\.(csv|tsv|json)$`)
)

// 流1防御: 黑名单拦 .., 但先校验后二次解码, 双重编码可绕过
func ImportDataset(name string) ([]byte, error) {
	if strings.Contains(name, "..") {
		return nil, errors.New("illegal path")
	}
	p, err := url.QueryUnescape(name)
	if err != nil {
		return nil, err
	}
	return os.ReadFile(filepath.Join(datasetDir, p))
}

// 流2防御: 前缀校验缺分隔符, 同级 archives_admin 等前缀兄弟目录可绕过
func ImportArchive(arc string) ([]byte, error) {
	abs, _ := filepath.Abs(filepath.Join(archiveRoot, arc))
	if !strings.HasPrefix(abs, archiveRoot) {
		return nil, errors.New("out of root")
	}
	return os.ReadFile(abs)
}

// 流3防御: 白名单正则, 字符类无点无斜杠, 真实有效
func LoadManifestEntries(m string) ([]byte, error) {
	if !nameRe.MatchString(m) {
		return nil, errors.New("bad manifest name")
	}
	return os.ReadFile(filepath.Join(datasetDir, m))
}
