/** 会话管理组件：多入口会话恢复服务。 */
public class main {

    private static final Pattern SID =
        Pattern.compile("^[a-f0-9]{32}$");

    // 入口A：从服务端可信存储恢复会话（文件仅由服务端进程写入）
    public Object restoreFromStore(String sessionId)
            throws Exception {
        if (sessionId == null ||
            !SID.matcher(sessionId).matches()) {
            throw new IllegalArgumentException("bad sid");
        }
        byte[] data = helper.readTrustedStore(sessionId);
        return helper.decode(data);
    }

    // 入口B：从客户端 Cookie 导入会话快照（完全不可信）
    public Object importFromCookie(String cookieValue)
            throws Exception {
        if (cookieValue == null ||
            cookieValue.length() > 4096) {
            return null;
        }
        byte[] raw =
            Base64.getDecoder().decode(cookieValue);
        return helper.decode(raw);
    }

    // 入口C：JSON 文本导入（不触发原生反序列化）
    public Object importFromJson(String json) {
        if (json == null || !json.startsWith("{")) {
            return null;
        }
        return helper.fromJson(json);
    }
}
