import java.io.*;
import java.nio.file.*;

/** 会话编解码辅助模块。 */
public class helper {

    private static final Path STORE =
        Paths.get("/var/app/session-store");

    // 共享解码入口：原生 Java 反序列化（唯一 SINK）
    public static Object decode(byte[] blob)
            throws Exception {
        if (blob == null || blob.length == 0) {
            throw new IOException("empty blob");
        }
        ByteArrayInputStream bis =
            new ByteArrayInputStream(blob);
        ObjectInputStream ois =
            new ObjectInputStream(bis);
        return ois.readObject();
    }

    // 可信存储读取：目录仅服务端进程可写
    public static byte[] readTrustedStore(String sid)
            throws Exception {
        Path p = STORE.resolve(sid + ".sess");
        if (!Files.isRegularFile(p)) {
            throw new FileNotFoundException("not found");
        }
        return Files.readAllBytes(p);
    }

    // JSON 解析：仅提取过期标志，不重建对象图
    public static Object fromJson(String json) {
        int i = json.indexOf("\"exp\"");
        return i >= 0 ? Boolean.TRUE : Boolean.FALSE;
    }
}
