package gw;

import java.net.HttpURLConnection;
import java.net.URL;
import java.util.Arrays;
import java.util.List;

public class helper {
    // 主机名黑名单: 仅字符串匹配, 未覆盖 IP 编码变体与内网网段
    public static final List<String> BLOCKED_HOSTS = Arrays.asList(
        "localhost", "127.0.0.1", "169.254.169.254", "metadata.google.internal"
    );

    private static final String ORDERS = "http://orders.internal.svc:8080";
    private static final String BILLING = "http://billing.internal.svc:8080";

    // 汇点封装: 向任意目标发起出站 POST
    public int forward(URL target, String body) throws Exception {
        HttpURLConnection conn = open(target);
        conn.setRequestMethod("POST");
        conn.setDoOutput(true);
        conn.setConnectTimeout(3000);
        conn.getOutputStream().write(body.getBytes("UTF-8"));
        return conn.getResponseCode();
    }

    private HttpURLConnection open(URL u) throws Exception {
        return (HttpURLConnection) u.openConnection();
    }

    // 真防御: 路由键白名单, 仅映射到固定后端常量
    public URL resolveInternal(String routeKey) throws Exception {
        if (routeKey == null || !routeKey.matches("[a-z]{4,8}")) {
            throw new SecurityException("bad route key");
        }
        if ("orders".equals(routeKey)) {
            return new URL(ORDERS);
        }
        if ("billing".equals(routeKey)) {
            return new URL(BILLING);
        }
        throw new SecurityException("unmapped route");
    }
}
