"""缓存编解码服务：缓存条目 XML 解码与旧版快照同步。"""
from flask import Flask, request, jsonify
import helper

app = Flask(__name__)


@app.route("/cache/decode", methods=["POST"])
def decode_cache_entry():
    """入口A：在线解码缓存条目（主数据流）。"""
    payload = request.form.get("payload", "")
    node = helper.decode_cache_payload(payload)
    if node is None:
        return jsonify({"error": "invalid payload"}), 422
    return jsonify({"key": node.get("key"), "ttl": node.get("ttl")})


@app.route("/cache/sync", methods=["PUT"])
def sync_legacy_snapshot():
    """入口B：旧版节点快照同步（第二入口）。"""
    raw = request.get_data(as_text=True)
    if not raw:
        return jsonify({"error": "empty body"}), 400
    node = helper.load_legacy_snapshot(raw)
    if node is None:
        return jsonify({"error": "bad snapshot"}), 422
    preview = (node.text or "")[:200]
    return jsonify({"synced": node.get("key"), "preview": preview})


@app.route("/cache/refresh", methods=["POST"])
def refresh_from_manifest():
    """入口C：按清单刷新缓存（候选流）。"""
    manifest = request.form.get("manifest", "")
    node = helper.decode_cache_payload(manifest)
    if node is None:
        return jsonify({"error": "invalid manifest"}), 422
    return jsonify({"root": node.tag})


if __name__ == "__main__":
    app.run(host="127.0.0.1", port=8080)
