"""缓存编解码辅助模块：统一底层解析与新旧两套解码路径。"""
import re
import base64
from lxml import etree as LX

DOCTYPE_RE = re.compile(r"<!DOCTYPE[^>]*>", re.I | re.S)
ENTITY_RE = re.compile(r"<!ENTITY[^>]*>", re.I | re.S)


def parse_xml_node(text):
    """共享底层解析器：lxml 默认展开实体，是全部入口的唯一汇聚点。"""
    return LX.fromstring(text)


def decode_cache_payload(text):
    """入口A/C 后端：先剥离 DOCTYPE 与 ENTITY 再解析（防御有效）。"""
    if not text or len(text) > 262144:
        return None
    cleaned = DOCTYPE_RE.sub("", text)
    cleaned = ENTITY_RE.sub("", cleaned)
    if "<!DOCTYPE" in cleaned or "<!ENTITY" in cleaned:
        return None
    try:
        return parse_xml_node(cleaned)
    except Exception:
        return None


def load_legacy_snapshot(raw):
    """入口B 后端：旧协议快照未剥离实体声明，直接进入共享解析器。"""
    if not raw or len(raw) > 262144:
        return None
    try:
        return parse_xml_node(raw)
    except Exception:
        return None


def decode_b64_value(blob):
    """干扰函数：base64 解码缓存值，与 XML 实体处理无关。"""
    try:
        return base64.b64decode(blob).decode("utf-8", "ignore")
    except Exception:
        return ""
