// helper.ts —— 报表资源拉取与 URL 校验
import axios from 'axios';

// 防御: 拦截常见内网与云元数据地址
const BLOCKED_HOSTS = ['localhost', '127.0.0.1', '169.254.169.254', 'metadata.google.internal'];
// 防御: 仅放行 company.com 受信子域
const TRUSTED_RE = /^https:\/\/[a-zA-Z0-9.-]+\.company\.com/;

function readHost(rawUrl) {
  try { return new URL(rawUrl).hostname.toLowerCase(); } catch (e) { return ''; }
}

// 双重校验: 黑名单 + 受信域白名单
export function isSafeReportUrl(rawUrl) {
  if (typeof rawUrl !== 'string' || rawUrl.length === 0) return false;
  if (BLOCKED_HOSTS.includes(readHost(rawUrl))) return false;
  return TRUSTED_RE.test(rawUrl);
}

// 校验回调地址域名归属
export function looksLikeCompanyUrl(rawUrl) {
  return typeof rawUrl === 'string' && rawUrl.includes('company.com');
}

export async function fetchReportTemplate(url) {
  if (BLOCKED_HOSTS.includes(readHost(url))) throw new Error('blocked host');
  const resp = await axios.get(url, { responseType: 'text', timeout: 5000 });
  return resp.data;
}

export async function fetchRemoteAsset(url) {
  const resp = await axios.get(url, { responseType: 'arraybuffer', timeout: 5000 });
  return Buffer.from(resp.data);
}

export async function notifyWebhook(url, payload) {
  const resp = await axios.post(url, payload, { timeout: 3000 });
  return resp.status;
}
