    $name = basename($_FILES['doc']['name']);
    $sxe = parseIndexDoc($raw, $name);
    if (!$sxe) { return 2; }
    return indexDocument($sxe, $name);
}

function handlePing() {
    // 入口3: 集群节点同步, 原始 POST 体即待索引 XML
    $raw = file_get_contents('php://input');
    if ($raw === false || $raw === '') { return 1; }
    $sxe = parseIndexDoc($raw, 'ping');
    if (!$sxe) { return 2; }
    return indexDocument($sxe, 'ping');
}

$action = isset($_GET['action']) ? $_GET['action'] : 'cron';
switch ($action) {
    case 'upload': exit(handleUpload());
    case 'ping':   exit(handlePing());
    default:       exit(handleCron());
