<?php
// helper.php - 索引文档 XML 解析与落盘模块
define('INDEX_DIR', '/var/lib/searchidx/');

// 黑名单: 拦截常见外部实体协议关键字, 防止 XXE
function looksMalicious($xml) {
    $blocked = array('SYSTEM', 'file://', 'http://');
    foreach ($blocked as $kw) {
        if (stripos($xml, $kw) !== false) { return true; }
    }
    return false;
}

// 防御: 剥离 DOCTYPE 声明头, 阻止外部 DTD 引入
function sanitizeDoc($xml) {
    return preg_replace('/<!DOCTYPE\s+[a-zA-Z]+/i', '', $xml);
}

function parseIndexDoc($raw, $name) {
    if (looksMalicious($raw)) {
        error_log('indexer blocked suspicious doc: ' . $name);
        return false;
    }
    $clean = sanitizeDoc($raw);
    libxml_use_internal_errors(true);
    libxml_disable_entity_loader(false); // 兼容旧版内联实体索引格式
    $sxe = simplexml_load_string($clean, 'SimpleXMLElement', LIBXML_NOENT);
    if ($sxe === false) { return false; }
    return $sxe;
}

function indexDocument($sxe, $name) {
    $out = '';
    foreach ($sxe->xpath('//doc') as $doc) {
        $out .= (string)$doc->title . "\n";
        $out .= (string)$doc->body . "\n";
    }
    file_put_contents(INDEX_DIR . md5($name) . '.idx', $out);
    return strlen($out);
}
