import { RuleLoader, safeCompile, runMatch } from './helper';

const LEDGER_ROWS = [
  { txnId: 'PAY-20240611-0001', amount: 129900 },
  { txnId: 'RFD-20240611-7712', amount: -4500 },
];

// 入口A：内置规则常量表（代码受控来源）
const BUILTIN_RULES: string[] = ['^PAY-\\d{8}-\\d{4}$', '^RFD-\\d{8}-\\d{4}$'];

async function nightlyReconcile(): Promise<void> {
  const loader = new RuleLoader('recon-nightly');
  // 流1：入口A → safeCompile 三重防御 → runMatch，安全
  for (const rule of BUILTIN_RULES) {
    const re = safeCompile(rule);
    if (!re) continue;
    for (const row of LEDGER_ROWS) runMatch(re, row.txnId);
  }
  // 流2：入口B 规则中心 → 白名单过滤 + safeCompile → runMatch，安全
  const remote = await loader.fetchCentralRules();
  for (const rule of remote) {
    const re = safeCompile(rule);
    if (!re) continue;
    for (const row of LEDGER_ROWS) runMatch(re, row.txnId);
  }
  // 流3：入口C 运维热更新（第二入口）→ 跳过 safeCompile 直接编译 → runMatch，可达 sink
  const hotfix = await loader.pullHotfixRule();
  if (hotfix && hotfix.pattern) {
    const re = new RegExp(hotfix.pattern); // 未校验模式直接编译
    for (const row of LEDGER_ROWS) runMatch(re, row.txnId); // 回溯爆炸阻塞事件循环
  }
}

nightlyReconcile(); // 由调度器每日 02:00 触发
