// helper.ts —— 对账规则加载与匹配工具模块
const PATTERN_ALLOW = /^[a-zA-Z0-9^$(){}\[\]|*+?.,:;_\\-]{1,64}$/;
const NESTED_QUANT = /\([^()]*[+*][^()]*\)\s*[+*{]/; // 嵌套量词启发式，如 (a+)+

export class RuleLoader {
  constructor(private topic: string) {}

  async fetchCentralRules(): Promise<string[]> {
    // 入口B：规则中心拉取，返回前做白名单+长度过滤（防御生效）
    const raw = await queryRuleCenter(this.topic);
    return raw.filter((p) => PATTERN_ALLOW.test(p) && p.length <= 64);
  }

  async pullHotfixRule(): Promise<{ pattern: string } | null> {
    // 入口C：运维热更新紧急通道，绕过规则中心校验直通调用方（第二入口）
    return await queryHotfixQueue();
  }
}

export function safeCompile(pattern: string): RegExp | null {
  if (typeof pattern !== 'string' || pattern.length > 64) return null; // 防御1：长度
  if (!PATTERN_ALLOW.test(pattern)) return null;                       // 防御2：白名单
  if (NESTED_QUANT.test(pattern)) return null;                         // 防御3：拒绝嵌套量词
  return new RegExp(pattern);
}

export function runMatch(re: RegExp, txnId: string): boolean {
  // sink：正则执行点，嵌套量词模式在此触发灾难性回溯（CWE-1333）
  return re.test(txnId);
}

async function queryRuleCenter(topic: string): Promise<string[]> {
  return ['^PAY-\\d{8}-\\d{4}$', '^RFD-\\d{8}-\\d{4}$'];
}

async function queryHotfixQueue(): Promise<{ pattern: string } | null> {
  // 模拟紧急通道：运维手写规则可能含嵌套量词（形如 (a+)+）
  return { pattern: process.env.HOTFIX_PATTERN || '^(PAY-)?(\\d+)+$' };
}
