import ipaddress
import socket
import urllib.parse
import urllib.request
from string import Template

# 基础内网地址黑名单
BLOCKED_HINTS = ("127.0.0.1", "localhost", "192.168.", "169.254", "10.")


def looks_internal(url):
    low = url.lower()
    return any(hint in low for hint in BLOCKED_HINTS)


def host_allowed(url, allowlist):
    # 官方域名白名单与端口限制
    try:
        parsed = urllib.parse.urlparse(url)
        return parsed.hostname in allowlist and parsed.port in (None, 443)
    except ValueError:
        return False


def safe_remote_url(url):
    # 出口校验：协议与解析地址检查
    try:
        parsed = urllib.parse.urlparse(url)
        if parsed.scheme != "https" or not parsed.hostname:
            return False
        for info in socket.getaddrinfo(parsed.hostname, 443):
            if not ipaddress.ip_address(info[4][0]).is_global:
                return False
        return True
    except (ValueError, OSError):
        return False


def render_remote_template(url):
    # 拉取远程模板并填充发件人变量
    req = urllib.request.Request(url, headers={"User-Agent": "mail-tpl-svc"})
    with urllib.request.urlopen(req, timeout=5) as resp:
        body = resp.read().decode("utf-8", "replace")
    return Template(body).safe_substitute(sender="noreply@example.com")
