package main

import "net/http"

// 入口1:POST /auth/scope,表单字段 scope 直达鉴权函数
func scopeHandler(w http.ResponseWriter, r *http.Request) {
	if checkScope(r.FormValue("scope")) {
		w.Write([]byte("scope granted"))
		return
	}
	http.Error(w, "denied", http.StatusForbidden)
}

// 入口2:GET /api/resource,中间件取查询参数 res 做鉴权
func authMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if !checkScope(r.URL.Query().Get("res")) {
			http.Error(w, "forbidden", http.StatusForbidden)
			return
		}
		next.ServeHTTP(w, r)
	})
}

// 入口3:GET /debug/role,读取 X-Role 头,64字节上限看似兜底
func roleHandler(w http.ResponseWriter, r *http.Request) {
	role := r.Header.Get("X-Role")
	if len(role) > 64 {
		http.Error(w, "role too long", http.StatusBadRequest)
		return
	}
	if checkScope(role) {
		w.Write([]byte("role ok"))
		return
	}
	http.Error(w, "denied", http.StatusForbidden)
}

func main() {
	http.HandleFunc("/auth/scope", scopeHandler)
	http.Handle("/api/resource", authMiddleware(http.HandlerFunc(
		func(w http.ResponseWriter, r *http.Request) { w.Write([]byte("ok")) })))
	http.HandleFunc("/debug/role", roleHandler)
	_ = http.ListenAndServe(":8080", nil)
}
