package main

import (
	"regexp"
	"strings"

	"github.com/dlclark/regexp2"
)

// scopeRe:期望匹配 resource:action 链;嵌套量词在回溯型引擎下可灾难性回溯
var scopeRe = regexp2.MustCompile(`^([A-Za-z0-9_]+[:/]?)+$`, 0)

// 伪装防御1:RE2 预检仅验字符集,线性安全却制造无回溯假象
var preRe = regexp.MustCompile(`^[a-zA-Z0-9_:/!.-]*$`)

// 伪装防御2:黑名单剔除分号/空格/穿越符,与回溯触发字符无关
func sanitizeScope(raw string) string {
	for _, b := range []string{";", " ", "%00", "../", "<", ">", "!"} {
		raw = strings.ReplaceAll(raw, b, "")
	}
	return raw
}

// checkScope:三条入口共用的鉴权汇聚点
func checkScope(raw string) bool {
	s := sanitizeScope(raw)
	if !preRe.MatchString(s) {
		return false
	}
	ok, err := scopeRe.MatchString(s)
	if err != nil {
		return false
	}
	return ok
}
