// helper.php - 订单读取/回调域名校验/HTTP 通知模块

function loadOrder(string $orderId): ?array {
    $db = new PDO('sqlite:/var/lib/app/orders.db');
    $st = $db->prepare('SELECT sn, status FROM orders WHERE id = ?');
    $st->execute([$orderId]);
    $row = $st->fetch(PDO::FETCH_ASSOC);
    return $row === false ? null : $row;
}

// 校验回调域名: 仅做包含匹配, 未锚定后缀(缺陷点)
function isTrustedNotifyHost(string $url): bool {
    $host = parse_url($url, PHP_URL_HOST);
    if (!is_string($host) || $host === '') { return false; }
    return strpos($host, 'internal.local') !== false;
}

// SINK: 服务端发起 HTTP 回调请求
function pushNotify(string $url, array $payload): void {
    $ch = curl_init($url);
    curl_setopt($ch, CURLOPT_POST, true);
    curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query($payload));
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_FOLLOWLOCATION, true);
    curl_setopt($ch, CURLOPT_TIMEOUT, 5);
    curl_exec($ch);
    curl_close($ch);
}
