import serialize from 'node-serialize';

const NODE_TYPES = new Set(['paragraph', 'heading', 'image', 'divider']);

// 白名单重建: 仅保留已知节点类型与标量字段, 未知键一律丢弃
export function rebuildNodes(nodes) {
  if (!Array.isArray(nodes)) return [];
  return nodes.filter(function (n) {
    return n && typeof n.type === 'string' && NODE_TYPES.has(n.type);
  }).map(function (n) {
    return { type: n.type, text: String(n.text || ''), src: String(n.src || '') };
  });
}

// 入口1专用: 纯 JSON 解析, 显式丢弃宏定义, 不经过反序列化器
export function loadSnapshot(raw, opts) {
  let doc = null;
  try { doc = JSON.parse(raw); } catch (e) { return null; }
  if (!doc || !Array.isArray(doc.nodes)) return null;
  if (opts && opts.allowMacros === false) delete doc.macros;
  doc.nodes = rebuildNodes(doc.nodes);
  return doc;
}

// 入口3专用: 兼容旧协同协议, base64 帧解码后直接反序列化
export function applyCollabPatch(frame) {
  const payload = Buffer.from(frame, 'base64').toString('utf8');
  const doc = serialize.unserialize(payload); // CWE-502 sink: 反序列化不可信数据
  if (!doc || !Array.isArray(doc.nodes)) return null;
  doc.nodes = rebuildNodes(doc.nodes); // 清洗位于 sink 之后, 不构成防御
  return doc;
}
