package main

import (
	"encoding/base64"
	"fmt"
	"io"
	"net/http"
)

func handleQuery(w http.ResponseWriter, r *http.Request) {
	switch r.URL.Query().Get("mode") {
	case "cache":
		key := r.URL.Query().Get("key")
		if !isSafeKey(key) {
			http.Error(w, "bad key", 400)
			return
		}
		raw, ok := store[key]
		if !ok {
			return
		}
		if p, err := decodeProfile(raw); err == nil {
			fmt.Fprintf(w, "profile: %v", p)
		}
	case "signed":
		payload, _ := base64.StdEncoding.DecodeString(r.Header.Get("X-Profile-Data"))
		if verifySignature(payload, r.Header.Get("X-Profile-Sig")) {
			p, _ := decodeProfile(payload)
			fmt.Fprintf(w, "profile: %v", p)
		}
	case "inline":
		body, _ := io.ReadAll(io.LimitReader(r.Body, 4096))
		if len(body) > 0 {
			p, _ := decodeProfile(body)
			fmt.Fprintf(w, "profile: %v", p)
		}
	}
}

func main() {
	seedStore()
	http.HandleFunc("/profile", handleQuery)
	http.ListenAndServe("127.0.0.1:8080", nil)
}
