package main

import (
	"bytes"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/base64"
	"encoding/gob"
	"os"
	"strings"
)

type Profile struct {
	Name  string
	Email string
}

var store = map[string][]byte{}

func decodeProfile(data []byte) (*Profile, error) {
	var p Profile
	err := gob.NewDecoder(bytes.NewReader(data)).Decode(&p)
	return &p, err
}

func verifySignature(payload []byte, sig string) bool {
	key := []byte(os.Getenv("PROFILE_MAC_KEY"))
	if len(key) == 0 {
		return false
	}
	mac := hmac.New(sha256.New, key)
	mac.Write(payload)
	want := base64.StdEncoding.EncodeToString(mac.Sum(nil))
	return hmac.Equal([]byte(want), []byte(sig))
}

func isSafeKey(k string) bool {
	return len(k) > 0 && len(k) < 64 && !strings.ContainsAny(k, ":|{}$")
}

func seedStore() {
	var b bytes.Buffer
	gob.NewEncoder(&b).Encode(Profile{Name: "demo", Email: "demo@example.com"})
	store["demo"] = b.Bytes()
}
