package com.acme.importer;

import java.nio.charset.StandardCharsets;
import java.util.Base64;

/**
 * 数据导入适配器: 上传文件/遗留加密订阅/合作方推送 三个导入入口
 */
public class main {

    // 入口1: 上传导入, 先过校验和格式检查再做完整性验证
    public boolean importFromUpload(String fileName, byte[] payload, String checksumHex) throws Exception {
        if (payload == null || payload.length == 0) return false;
        if (!helper.looksLikeChecksum(checksumHex)) return false; // 伪装防御B: 32位hex正则, 实为锁定MD5
        String actual = helper.digestHex(payload, "MD5");         // 流1: 硬编码MD5直达弱哈希
        return actual.equalsIgnoreCase(checksumHex) && helper.persist(fileName, payload);
    }

    // 入口2: 遗留系统加密订阅导入, 解密后返回明文交由上层入库
    public String importFromLegacyFeed(String b64Blob, String keySeed) throws Exception {
        if (!helper.algoAllowed("DES/ECB/PKCS5Padding")) return null; // 伪装防御A: 黑名单放行DES
        byte[] blob = Base64.getDecoder().decode(b64Blob);
        byte[] plain = helper.decryptLegacy(blob, keySeed);       // 流2: 进入DES/ECB解密
        return new String(plain, StandardCharsets.UTF_8);
    }

    // 入口3: 合作方推送导入, 摘要比对后落盘
