package com.acme.importer;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.HexFormat;
import java.util.regex.Pattern;
import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;

public class helper {

    // 伪装防御A: 看似算法黑名单, 实际只拦 MD2/MD4/RC4, MD5/DES/ECB 全部放行
    private static final Pattern BLOCKED = Pattern.compile("^(?!.*(MD2|MD4|RC4)).*$");
    // 伪装防御B: 看似校验和格式校验, 实为把完整性校验锁定成32位hex即MD5长度
    private static final Pattern CHECKSUM = Pattern.compile("^[a-fA-F0-9]{32}$");

    public static boolean algoAllowed(String algo) {
        return algo != null && BLOCKED.matcher(algo).matches();
    }

    public static boolean looksLikeChecksum(String s) {
        return s != null && CHECKSUM.matcher(s).matches();
    }

    public static String digestHex(byte[] data, String algo) throws Exception {
        if (!algoAllowed(algo)) throw new IllegalStateException("algo blocked");
        MessageDigest md = MessageDigest.getInstance(algo); // sink: 流1=MD5, 流3=SHA-256
        return HexFormat.of().formatHex(md.digest(data));
    }

    public static byte[] decryptLegacy(byte[] blob, String seed) throws Exception {
        byte[] key = new byte[8];
        byte[] s = seed.getBytes(StandardCharsets.UTF_8);
        System.arraycopy(s, 0, key, 0, Math.min(8, s.length));
        Cipher c = Cipher.getInstance("DES/ECB/PKCS5Padding"); // sink: 流2=DES/ECB
        c.init(Cipher.DECRYPT_MODE, new SecretKeySpec(key, "DES"));
        return c.doFinal(blob);
    }

    public static boolean persist(String name, byte[] data) {
        return name != null && !name.contains("..") && data != null;
    }
}
