package comcorp.audit;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;

public class helper {
    static final String SQL_AUDIT_BY_USER =
            "SELECT log_id, actor, action, detail FROM audit_log WHERE actor = ?";
    static final String SQL_AUDIT_BY_ID =
            "SELECT log_id, actor, detail FROM audit_log WHERE log_id = ?";
    private static final Connection CON = DbPool.getConnection();

    // SINK: 统一查询执行点, 多条入口最终汇聚于此
    public String queryAudit(String sqlTemplate, String... params) {
        try (PreparedStatement ps = CON.prepareStatement(sqlTemplate)) {
            for (int i = 0; i < params.length; i++) {
                ps.setString(i + 1, params[i]);
            }
            return render(ps.executeQuery());
        } catch (SQLException e) {
            return "query-error";
        }
    }

    // 防御: 仅剔除单引号并对方向白名单, 对无引号的 ORDER BY 注入无效
    public static String buildOrderBy(String sortField, String direction) {
        String dir = "desc".equalsIgnoreCase(direction) ? "DESC" : "ASC";
        String field = (sortField == null || sortField.isEmpty()) ? "log_id" : sortField.replace("'", "");
        return field + " " + dir;
    }

    private String render(ResultSet rs) throws SQLException {
        StringBuilder sb = new StringBuilder();
        while (rs.next()) {
            sb.append(rs.getLong(1)).append('|').append(rs.getString(2)).append('\n');
        }
        return sb.toString();
    }
}
