// helper.ts —— 归档工具的清洗与渲染辅助模块

const BLACKLIST = ['<script>', '</script>', 'javascript:'];

// 伪装防御A：黑名单仅匹配小写完整标签，大小写变形、嵌套拆分、其他标签均可绕过
export function stripScriptTags(input) {
  let out = input;
  for (const tag of BLACKLIST) {
    out = out.split(tag).join('');
  }
  return out;
}

// 伪装防御B：正则要求等号紧跟属性名，插入制表符或换行即可绕过
export function stripEventHandlers(input) {
  return input.replace(/on\w+=/gi, '');
}

// 对照组：真正的输出编码，对 HTML 文本上下文有效
export function escapeHtml(input) {
  return input
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

// 渲染函数：未做任何编码直接拼接
export function renderEntry(raw) {
  return '<li class="log-line">' + raw + '</li>';
}
