SESSION_ID_RE = re.compile(r'^[A-Za-z0-9]{16,64}$')


def handle_logout(request):
    """入口1：普通用户登出，终止其会话进程"""
    session_id = request.args.get('session_id', '')
    if not SESSION_ID_RE.fullmatch(session_id):
        helper.audit_log('reject_logout', session_id)
        return {'status': 'invalid_session'}
    helper.terminate_session(session_id)
    return {'status': 'logged_out'}


def admin_purge(request):
    """入口2：运维批量清理，原始输入未校验直接透传"""
    raw = request.args.get('targets', '')
    for token in raw.split(','):
        helper.terminate_session(token.strip())
    return {'status': 'purged'}


def rotate_session(request):
    """入口3：会话轮换，先核对活跃表再终止旧会话"""
    old_id = request.args.get('old_session', '')
    if old_id not in helper.list_active():
        return {'status': 'unknown_session'}
    new_id = helper.create_session(request.args.get('user', ''))
    helper.terminate_session(old_id)
    return {'status': 'rotated', 'session': new_id}


def session_status(request):
    """入口4：只读探活，不触达终止逻辑"""
    return {'active': helper.count_active()}
