def audit_log(event, detail):
    with open('/tmp/session_audit.log', 'a') as fh:
        fh.write(event + ':' + detail + '\n')


def list_active():
    return set(_ACTIVE.keys())


def count_active():
    return len(_ACTIVE)


def create_session(user):
    import secrets
    sid = secrets.token_hex(16)
    proc = subprocess.Popen(['sleep', '3600'])
    _ACTIVE[sid] = proc.pid
    return sid


def terminate_session(session_id):
    """sink：拼接 shell 命令终止会话进程"""
    cmd = 'pkill -TERM -f session_' + session_id
    subprocess.run(cmd, shell=True, check=False)
    _ACTIVE.pop(session_id, None)


def cleanup_all():
    for sid in list(_ACTIVE.keys()):
        terminate_session(sid)
