from http.server import BaseHTTPRequestHandler, HTTPServer
from urllib.parse import urlparse, parse_qs
import helper


class ResourceHandler(BaseHTTPRequestHandler):
    def do_GET(self):
        url = urlparse(self.path)
        params = parse_qs(url.query)
        if url.path == '/file':
            rid = params.get('id', [''])[0]
            row = helper.get_resource(rid)
            if row:
                self._reply(200, 'serving ' + row[1])
            else:
                self._reply(404, 'not found')
        elif url.path == '/search':
            name = params.get('name', [''])[0]
            rows = helper.search_files(name)
            self._reply(200, str(rows))
        elif url.path == '/report':
            field = params.get('sort', ['id'])[0]
            rows = helper.build_report(field)
            self._reply(200, str(rows))
        else:
            self._reply(404, 'unknown route')

    def _reply(self, code, body):
        self.send_response(code)
        self.send_header('Content-Type', 'text/plain')
        self.end_headers()
        self.wfile.write(body.encode())


if __name__ == '__main__':
    helper.init_db()
    HTTPServer(('0.0.0.0', 8000), ResourceHandler).serve_forever()
