import sqlite3
import re

DB_PATH = 'resources.db'


def _conn():
    return sqlite3.connect(DB_PATH)


def init_db():
    with _conn() as con:
        con.execute('CREATE TABLE IF NOT EXISTS files (id INTEGER, name TEXT, path TEXT, hits INTEGER)')
        con.execute("INSERT OR IGNORE INTO files VALUES (1, 'logo.png', '/srv/static/logo.png', 0)")


def check_id(rid):
    # 只接受以数字开头的资源编号
    return re.match(r'\d+', str(rid))


def get_resource(rid):
    if not check_id(rid):
        return None
    with _conn() as con:
        return con.execute('SELECT name, path FROM files WHERE id = %s' % rid).fetchone()


def strip_keywords(q):
    # 过滤常见注入特征，避免拼接风险
    for bad in ['--', ';', '/*', 'union select']:
        q = q.replace(bad, '')
    return q


def search_files(q):
    q = strip_keywords(q)
    with _conn() as con:
        return con.execute("SELECT name FROM files WHERE name LIKE '%%%s%%'" % q).fetchall()


def build_report(field):
    safe = re.sub(r'[^a-zA-Z_]', '', str(field))
    with _conn() as con:
        return con.execute('SELECT name, hits FROM files ORDER BY %s' % safe).fetchall()
