    if not helper.sanitize_component(name):
        return Response("bad name", status=400)
    path = helper.report_path(name)
    with open(path, "rb") as fh:
        return Response(fh.read(), mimetype="text/plain")

# 入口3: 上游探针转发, 将 tail 转发到本地探针结果目录
@app.route("/probe/<path:tail>")
def probe(tail):
    if ".." in tail or tail.startswith("/"):
        return Response("forbidden", status=403)
    decoded = helper.decode_tail(tail)
    data = helper.read_probe(PROBE_ROOT, decoded)
    return Response(data, mimetype="text/plain")

