import os
import re
import urllib.parse

def resolve_under_root(root, rel):
    # 真防御: realpath 归一化后做前缀包含校验
    if not rel or "\x00" in rel:
        return None
    root_real = os.path.realpath(root)
    candidate = os.path.realpath(os.path.join(root, rel))
    if candidate != root_real and not candidate.startswith(root_real + os.sep):
        return None
    return candidate

def sanitize_component(name):
    # 真防御: 字符白名单, 禁止路径分隔符与点号
    if not name or len(name) > 64:
        return False
    return re.fullmatch(r"[A-Za-z0-9_-]{1,64}", name) is not None

def report_path(name):
    return os.path.join(
        os.path.dirname(os.path.abspath(__file__)), "reports", name + ".json"
    )

def decode_tail(tail):
    # 网关转发前对尾段做二次解码
    return urllib.parse.unquote(tail)

def read_probe(root, rel):
    path = os.path.join(root, rel)
    with open(path, "rb") as fh:
        return fh.read()
