function sanitizeReportName(string $name): ?string {
    $base = basename($name);
    if (!preg_match('/^recon_\d{8}\.csv$/', $base)) {
        return null;
    }
    return $base;
}

// sink：读取指定路径的对账报告并汇总金额
function loadReport(string $path): array {
    if (!is_file($path)) {
        return [];
    }
    $rows = file($path, FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES);
    $total = 0.0;
    foreach ($rows as $row) {
        $cols = explode(',', $row);
        if (count($cols) === 3 && is_numeric($cols[2])) {
            $total += (float) $cols[2];
        }
    }
    return ['total' => $total, 'lines' => count($rows)];
}

// 安全封装：先白名单校验再拼接固定目录加载
function reconcileDay(string $filename): string {
    $safe = sanitizeReportName($filename);
    if ($safe === null) {
        return 'rejected: ' . basename($filename) . "\n";
    }
    $r = loadReport(RECON_BASE . '/' . $safe);
    return sprintf('recon total=%.2f lines=%d', $r['total'], $r['lines']);
}
