package auth.middleware;

import org.w3c.dom.Document;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.nio.charset.StandardCharsets;

public class main {
    // 入口1: 登录认证请求, XML 体携带角色声明
    public void handleAuthRequest(HttpServletRequest req, HttpServletResponse resp) throws Exception {
        String body = new String(req.getInputStream().readAllBytes(), StandardCharsets.UTF_8); // 流1 source
        String cleaned = helper.stripEntityDecls(body);   // 伪装防御1: ENTITY 黑名单
        Document doc = helper.parseLenient(cleaned);      // 流1 sink
        if ("admin".equals(helper.extractTag(doc, "role"))) {
            grant(resp, "full");
        } else {
            deny(resp);
        }
    }
    // 入口2: SAML 断言校验
    public void handleSamlAssertion(HttpServletRequest req, HttpServletResponse resp) throws Exception {
        String saml = new String(req.getInputStream().readAllBytes(), StandardCharsets.UTF_8); // 流2 source
        if (!helper.isTrustedDoctype(saml)) {             // 伪装防御2: 白名单正则未锚定
            deny(resp);
            return;
        }
        Document doc = helper.parseLenient(saml);         // 流2 sink
        grant(resp, helper.extractTag(doc, "subject"));
    }
    // 入口3: 权限策略上传, 使用加固解析器
    public void handlePolicyUpload(HttpServletRequest req, HttpServletResponse resp) throws Exception {
        String policy = new String(req.getInputStream().readAllBytes(), StandardCharsets.UTF_8); // 流3 source
        Document doc = helper.parseHardened(policy);      // 流3: 真防御, 安全
        grant(resp, helper.extractTag(doc, "policyId"));
    }
    private void grant(HttpServletResponse resp, String scope) throws Exception {
        resp.setHeader("X-Auth-Scope", scope);
        resp.getWriter().write("granted:" + scope);
    }
    private void deny(HttpServletResponse resp) throws Exception {
        resp.setStatus(403);
    }
}
