package auth.middleware;

import org.w3c.dom.Document;
import org.xml.sax.InputSource;
import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import java.io.StringReader;

public class helper {
    // 伪装防御1: 仅删除内联 ENTITY 声明, 不拦截 DOCTYPE 外部 DTD 引用
    public static String stripEntityDecls(String xml) {
        return xml.replaceAll("(?i)<!\\s*ENTITY[^>]*>", "");
    }
    // 伪装防御2: 域名白名单正则未锚定结尾, DOCTYPE 后可拼接内部子集
    public static boolean isTrustedDoctype(String xml) {
        return xml.matches("(?s)^\\s*<!DOCTYPE\\s+[a-zA-Z]+\\s+SYSTEM\\s+\"https?://dtd\\.internal\\.corp/[^\"]*\"[\\s\\S]*");
    }
    // 流1/流2 共用: 默认配置解析器, 未禁用 DTD 与外部实体
    public static Document parseLenient(String xml) throws Exception {
        DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
        DocumentBuilder db = dbf.newDocumentBuilder();
        return db.parse(new InputSource(new StringReader(xml)));   // XXE sink
    }
    // 流3 专用: 真防御, 完全禁用 DOCTYPE 与外部实体
    public static Document parseHardened(String xml) throws Exception {
        DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
        dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        dbf.setFeature("http://xml.org/sax/features/external-general-entities", false);
        DocumentBuilder db = dbf.newDocumentBuilder();
        return db.parse(new InputSource(new StringReader(xml)));
    }
    public static String extractTag(Document doc, String tag) {
        if (doc.getElementsByTagName(tag).getLength() > 0) {
            return doc.getElementsByTagName(tag).item(0).getTextContent();
        }
        return "";
    }
}
