// helper.php — 富文本净化与页面渲染辅助模块

class RichText
{
    // 公告清洗结果静态缓存（渲染时 notice 段以此为准）
    public static string $noticeBox = '';

    // 流A防御：白名单标签 + 剥离全部属性（无属性即无事件与 href 向量，真实防御）
    public static function purifyRichText(string $html): string
    {
        $kept = strip_tags($html, '<p><b><i><em><strong><ul><ol><li><blockquote>');
        return preg_replace('/<([a-z][a-z0-9]*)[^>]*>/i', '<$1>', $kept);
    }

    // 流B防御：HTML 实体转义，单双引号均编码（真实防御）
    public static function escapeHtml(string $raw): string
    {
        return htmlspecialchars($raw, ENT_QUOTES | ENT_HTML5, 'UTF-8');
    }

    // 流C：黑名单清洗，仅删除 script 标签字面量（弱防御，img/svg 事件属性可穿透）
    public static function cleanHeading(string $title): string
    {
        $once = str_ireplace('<script>', '', $title);
        $twice = str_ireplace('</script>', '', $once);
        self::$noticeBox = $twice;
        return $twice;
    }

    // 渲染汇总：sink 所在；转义仅作用于键名 $id，$html 原样拼接
    public static function renderPage(array $sections): void
    {
        echo '<!DOCTYPE html><html><body>';
        foreach ($sections as $id => $html) {
            if ($id === 'notice') {
                $html = self::$noticeBox;
            }
            echo '<section id="' . htmlspecialchars($id, ENT_QUOTES) . '">' . $html . '</section>';
        }
        echo '</body></html>';
    }
}
