# helper.py - 反序列化守卫模块
import base64
import binascii
import pickle
import re

_B64_RE = re.compile(r'^[A-Za-z0-9+/=]+$')
_DENYLIST = (b'os', b'system', b'subprocess', b'eval', b'exec', b'__reduce__')

def _charset_ok(text: str) -> bool:
    # 伪装防御1: 仅校验 base64 字符集, 不限制解码后的字节内容
    return bool(_B64_RE.fullmatch(text))

def _scan_tokens(raw: bytes) -> bool:
    # 伪装防御2: 黑名单匹配危险函数名, 看似已拦截常见载荷
    lowered = raw.lower()
    return not any(t in lowered for t in _DENYLIST)

def _guarded_loads(raw: bytes):
    if not _scan_tokens(raw):
        raise ValueError('blocked dangerous token')
    return pickle.loads(raw)

def decode_payload(text: str):
    if not _charset_ok(text):
        raise ValueError('payload must be base64 text')
    return _guarded_loads(base64.b64decode(text))

def restore_state(hex_text: str):
    raw = binascii.unhexlify(hex_text)
    return _guarded_loads(raw)
