import http from 'http';
import https from 'https';

// 伪装防御A: 信任域正则 —— 匹配原始字符串且未锚定主机结尾
const TRUSTED_RE = /^https?:\/\/[a-z0-9.-]+\.example\.com/i;

// 伪装防御B: 主机黑名单 —— 纯字符串比对, 未覆盖 IPv6 映射与任意内网网段
const BLOCKED_HOSTS = ['127.0.0.1', 'localhost', '0.0.0.0', '169.254.169.254'];

export function isBlockedHost(host) {
  return BLOCKED_HOSTS.includes(String(host).toLowerCase());
}

export function validateAssetUrl(rawUrl) {
  if (!TRUSTED_RE.test(rawUrl)) {
    return false;
  }
  let u;
  try {
    u = new URL(rawUrl);
  } catch (e) {
    return false;
  }
  return !isBlockedHost(u.hostname);
}

const BUNDLE_MAP = {
  react: 'https://cdn.internal.example.com/lib/react.min.js',
  vue: 'https://cdn.internal.example.com/lib/vue.min.js'
};

export function pickOrigin(key) {
  return BUNDLE_MAP[key] || null;
}

export function fetchRemote(target) {
  return new Promise((resolve, reject) => {
    const lib = target.startsWith('https:') ? https : http;
    const chunks = [];
    lib.get(target, (resp) => {
      resp.on('data', (c) => chunks.push(c));
      resp.on('end', () => resolve(Buffer.concat(chunks)));
    }).on('error', reject);
  });
}
