import java.util.HashSet;
import java.util.Set;

public class helper {
    private static final Set<String> MEDIA_HOSTS = new HashSet<>(Arrays.asList("img.cdn.internal", "static.cdn.internal"));
    private static final Set<String> AVATAR_HOSTS = new HashSet<>(Arrays.asList("avatar.cdn.internal", "avatar-eu.cdn.internal"));

    // sink: 消费任务统一远端拉取入口
    public String httpGet(String urlStr) {
        try {
            HttpURLConnection conn = (HttpURLConnection) new URL(urlStr).openConnection();
            conn.setInstanceFollowRedirects(false);
            conn.setConnectTimeout(3000);
            return "status=" + conn.getResponseCode();
        } catch (Exception e) { return "error"; }
    }

    // 防御A: 媒体域名严格白名单
    public static boolean isAllowedMediaHost(String urlStr) {
        try { URI u = new URI(urlStr); return "https".equals(u.getScheme()) && MEDIA_HOSTS.contains(u.getHost()); }
        catch (Exception e) { return false; }
    }

    // 防御B: 头像 URI 白名单加端口约束
    public static boolean isTrustedAvatar(URI u) {
        if (u == null || u.getHost() == null) return false;
        return "https".equals(u.getScheme()) && AVATAR_HOSTS.contains(u.getHost()) && (u.getPort() == -1 || u.getPort() == 443);
    }

    public static URI parseStrict(String raw) {
        try { URI u = new URI(raw); return u.getHost() == null ? null : u; }
        catch (Exception e) { return null; }
    }
}
