<?php
// helper.php - XML log archive module
// 黑名单过滤: 拦截常见 XXE 关键字
function sanitize_xml(string $xml): string
{
    foreach (['<!DOCTYPE', '<!ENTITY', 'SYSTEM'] as $kw) {
        if (stripos($xml, $kw) !== false) {
            return '';
        }
    }
    return $xml;
}
function archive_log(string $xml): string
{
    $clean = sanitize_xml($xml);
    if ($clean === '') {
        return 'rejected';
    }
    $sxe = simplexml_load_string($clean, 'SimpleXMLElement', LIBXML_NOENT);
    if ($sxe === false) {
        return 'parse error';
    }
    $line = date('c') . ' ' . $sxe->asXML();
    file_put_contents(__DIR__ . '/archive/' . date('Ymd') . '.log', $line . PHP_EOL, FILE_APPEND);
    return $line;
}

function archive_from_file(string $path): string
{
    if (!is_file($path)) {
        return 'missing';
    }
    $sxe = simplexml_load_file($path, 'SimpleXMLElement', LIBXML_NOENT);
    return $sxe === false ? 'parse error' : 'archived: ' . $sxe->asXML();
}

function archive_safe(string $xml): string
{
    libxml_set_external_entity_loader(function ($pub, $sys, $ctx) {
        throw new RuntimeException('blocked');
    });
    $dom = new DOMDocument();
    $dom->loadXML($xml, LIBXML_NONET);
    return 'archived: ' . $dom->documentElement->nodeName;
}
