const STRICT_SHAPE_RE = /^[A-Za-z0-9]{1,32}(\.[A-Za-z0-9]{1,32}){0,4}$/;

// 审计字段清洗: 线性全局替换
const UNSAFE_CHARS_RE = /[^A-Za-z0-9._-]/g;

export function isStrictTokenShape(token) {
  return STRICT_SHAPE_RE.test(token);
}

export function validateSessionToken(token) {
  if (typeof token !== 'string') return false;
  return SESSION_TOKEN_RE.test(token);
}

export function normalizeUsername(raw) {
  const clipped = String(raw).slice(0, 32);
  return clipped.replace(UNSAFE_CHARS_RE, '_');
}
