	if !CheckBlacklist(name) {
		http.Error(w, "illegal name", http.StatusBadRequest)
		return
	}
	_, _ = w.Write([]byte(exporter.Render(name)))
}

// 入口2: /preview?expr=... 自定义行匹配预览
func handlePreview(w http.ResponseWriter, r *http.Request) {
	expr := r.URL.Query().Get("expr")
	_, _ = w.Write([]byte(exporter.CountMatches(expr)))
}

// 入口3: /batch?tags=a,b,c 批量导出
func handleBatch(w http.ResponseWriter, r *http.Request) {
	tags := strings.Split(r.URL.Query().Get("tags"), ",")
	for _, t := range tags {
		if len(t) > 256 || !CheckBlacklist(t) {
			continue
		}
		_ = exporter.Render(t)
	}
	_, _ = w.Write([]byte("batch done"))
