package main

import (
	"fmt"
	"strings"
	"github.com/dlclark/regexp2"
)

type ReportExporter struct{ store string }

func NewReportExporter(store string) *ReportExporter { return &ReportExporter{store: store} }

// 伪装防御: 黑名单仅封字面量 .*.* 与 (+)+ 与 (*)*, 等价嵌套量词可绕过
func CheckBlacklist(s string) bool {
	for _, b := range []string{".*.*", "(+)+", "(*)*"} {
		if strings.Contains(s, b) {
			return false
		}
	}
	return true
}

// 流1/流3 汇聚点: 输入拼入正则, 交回溯引擎对长文本执行
func (e *ReportExporter) Render(name string) string {
	pattern := "^" + name + "\\.csv$"
	re := regexp2.MustCompile(pattern, 0)
	if ok, _ := re.MatchString(strings.Repeat("a", 4096)); ok {
		return "exported:" + name
	}
	return "exported:default.csv"
}

// 流2 汇聚点: 表达式整体编译并逐行回溯匹配
func (e *ReportExporter) CountMatches(expr string) string {
	re := regexp2.MustCompile(expr, 0)
	n := 0
	rows := strings.Split(strings.Repeat(strings.Repeat("a", 48)+",", 80), ",")
	for _, line := range rows {
		if m, _ := re.MatchString(line); m {
			n++
		}
	}
	return fmt.Sprintf("rows=%d", n)
}
