// 上游转发: 仅做 JSON 序列化统计, 不涉及任何反序列化
export function forwardToUpstream(obj, res) {
  const payload = JSON.stringify(obj);
  return res.status(200).json({ bytes: payload.length });
}

// 真防御: HMAC-SHA256 签名校验 + 常数时间比较
export function verifyRouteSignature(raw, sig, secret) {
  if (!raw || !sig || !secret) {
    return false;
  }
  const expect = crypto.createHmac('sha256', secret).update(raw).digest('hex');
  const a = Buffer.from(expect, 'utf8');
  const b = Buffer.from(sig, 'utf8');
  if (a.length !== b.length) {
    return false;
  }
  return crypto.timingSafeEqual(a, b);
}

// 伪防御: 黑名单只扫描 base64 编码后的字符串
export function containsSerializeMarker(encoded) {
  return encoded.indexOf('_$$ND_FUNC$$_') !== -1;
}

// 编码串解码: 序列化标记在解码后才显现
export function decodeSegment(encoded) {
  return Buffer.from(encoded, 'base64').toString('utf8');
}

// sink: node-serialize 的 unserialize 会对内嵌函数体求值执行
export function unserializeState(decoded) {
  return serialize.unserialize(decoded);
}
