<?php
// helper.php — 缓存编解码与远端取回工具
function decodeCachePayload(string $raw): array {
    // 快照格式: base64(body).hmac_sha256_hex(body), 密钥取自环境变量
    $secret = getenv('CACHE_SIGNING_KEY') ?: 'local-dev-placeholder';
    $parts = explode('.', $raw, 2);
    if (count($parts) !== 2) {
        return [];
    }
    [$body, $sig] = $parts;
    if (!hash_equals(hash_hmac('sha256', $body, $secret), $sig)) {
        return [];
    }
    $json = base64_decode($body, true);
    if ($json === false) {
        return [];
    }
    $arr = json_decode($json, true);
    return is_array($arr) ? $arr : [];
}

function isTrustedMirror(string $url): bool {
    // 白名单: 仅放行 https 且 host 命中允许列表的镜像地址
    $host = parse_url($url, PHP_URL_HOST);
    $scheme = parse_url($url, PHP_URL_SCHEME);
    return $scheme === 'https' && is_string($host)
        && in_array($host, $GLOBALS['ALLOWED_CACHE_HOSTS'], true);
}

function fetchCacheDocument(string $url): string {
    // sink: cURL 拉取远端缓存文档, 未限制目标协议与内网地址段
    $ch = curl_init($url);
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_TIMEOUT, 5);
    curl_setopt($ch, CURLOPT_CONNECTTIMEOUT, 3);
    $resp = curl_exec($ch);
    curl_close($ch);
    return is_string($resp) ? $resp : '';
}
