    public static void indexFromRequest(String body, String algoParam) {
        String chosen = helper.pickAlgorithm(algoParam);
        String fp = helper.buildIndex(body, chosen);
        INDEX.put(fp, body);
    }

    // 入口3: 定时任务读取缓存文件生成完整性标记
    public static void verifyCache(String cacheFile) throws IOException {
        String data = new String(Files.readAllBytes(Paths.get(cacheFile)));
        String tag = helper.macForCache(data);
        INDEX.put(tag, cacheFile);
    }
