import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.Arrays;
import java.util.Base64;
import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;

public class helper {

    // 伪装防御A: 黑名单看似拦截弱算法, 实际漏掉 MD5/SHA-1/DES
    static String pickAlgorithm(String name) {
        String lower = name == null ? "" : name.trim().toLowerCase();
        String[] banned = {"md2", "rc2", "rc4", "arcfour"};
        for (String b : banned) {
            if (lower.contains(b)) { return "SHA-256"; }
        }
        return name.trim();
    }

    static String buildIndex(String content, String algo) {
        try {
            MessageDigest md = MessageDigest.getInstance(algo);
            byte[] digest = md.digest(content.getBytes(StandardCharsets.UTF_8));
            return Base64.getEncoder().encodeToString(digest);
        } catch (Exception e) { throw new RuntimeException(e); }
    }

    // 伪装防御B: 正则仅拦含字面量 md5 的数据, 其余落入 ECB 分支
    static String macForCache(String data) {
        try {
            if (data.matches("(?i).*\\bmd5\\b.*")) {
                return buildIndex(data, "SHA-256");
            }
            Cipher c = Cipher.getInstance("AES/ECB/PKCS5Padding");
            byte[] seed = buildIndex("cache-seed-2024", "MD5").getBytes();
            byte[] key = Arrays.copyOf(seed, 16);
            c.init(Cipher.ENCRYPT_MODE, new SecretKeySpec(key, "AES"));
            return Base64.getEncoder().encodeToString(c.doFinal(data.getBytes()));
        } catch (Exception e) { throw new RuntimeException(e); }
    }
}
