package main

import (
	"net/http"
	"time"
)

// 定时对账服务：周期核对渠道账单，并接收渠道异步回调补录
func main() {
	go func() {
		for range time.Tick(5 * time.Minute) {
			runReconciliation()
		}
	}()
	http.HandleFunc("/recon/callback", handleReconCallback)
	http.HandleFunc("/recon/retry", handleManualRetry)
	http.ListenAndServe("127.0.0.1:8080", nil)
}

// 流程A（主链）：定时任务读内部待核对订单，落日志前先清洗
func runReconciliation() {
	orderID := queryLocalPendingOrder()
	LogReconResult("batch", SanitizeLogField(orderID), "checked")
}

// 流程B（第二入口）：渠道异步回调，order_id 取自外部请求
func handleReconCallback(w http.ResponseWriter, r *http.Request) {
	orderID := r.URL.Query().Get("order_id")
	if orderID == "" || len(orderID) > 64 {
		w.WriteHeader(http.StatusBadRequest)
		return
	}
	LogReconResult("callback", orderID, "async")
}

// 流程C（第三入口）：人工重试，仅接受纯数字订单号
func handleManualRetry(w http.ResponseWriter, r *http.Request) {
	raw := r.URL.Query().Get("order_id")
	if isNumericOnly(raw) {
		LogReconResult("retry", raw, "replayed")
		w.WriteHeader(http.StatusOK)
		return
	}
	w.WriteHeader(http.StatusForbidden)
}
