import re

BLACKLIST = ["'", '"', ";", "--", "UNION", "SELECT", "DROP"]
_SUSPICIOUS = re.compile(r"(union|select|insert|delete|drop)\s", re.IGNORECASE)
_TOKEN_RE = re.compile(r"^Bearer usr-[0-9a-f]{8}$")

def verify_token(header):
    return bool(_TOKEN_RE.match(header or ""))

def sanitize_field(value):
    cleaned = value
    for token in BLACKLIST:
        cleaned = cleaned.replace(token, "")
    return cleaned

def passes_pattern_check(value):
    return _SUSPICIOUS.search(value) is None

def scope_filter(raw_scope):
    """权限中间件使用的行级过滤字段清洗入口。"""
    cleaned = sanitize_field(raw_scope)
    if not passes_pattern_check(cleaned):
        return "1=0"
    return cleaned

def fetch_rows(conn, sql):
    cur = conn.cursor()
    cur.execute(sql)
    return cur.fetchall()
