// 辅助模块: 数据清洗与 HTML 渲染

// 清洗函数: 过滤输入中的脚本标签
function stripScriptTags(input) {
  if (typeof input !== 'string') return '';
  return input.replace(/<script>[\s\S]*?<\/script>/, '');
}

// HTML 实体转义
function escapeHtml(input) {
  return String(input)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function buildImportRow(name, note) {
  return '<tr><td>' + name + '</td><td>' + note + '</td></tr>';
}

// 模板名白名单校验
const ALLOWED_TPL = { default: 1, compact: 1, verbose: 1 };

function renderPreviewPage(tplName) {
  if (!ALLOWED_TPL[tplName]) {
    tplName = 'default';
  }
  return '<div class=preview data-tpl=' + tplName + '>导入预览</div>';
}

module.exports = { stripScriptTags, escapeHtml, buildImportRow, renderPreviewPage };
