function listAuditFiles(baseDir, prefix) {
  const safePrefix = path.basename(String(prefix));
  return fs.readdirSync(baseDir)
    .filter((f) => f.startsWith(safePrefix))
    .map((f) => {
      const full = path.join(baseDir, f);
      return { name: f, size: fs.statSync(full).size };
    });
}

module.exports = { readAuditLog, listAuditFiles };
