import os
import sys
import threading
import queue
from helper import run_sync, run_retry, ping_probe, validate_host

task_queue = queue.Queue()

def enqueue_plan(plan_path):
    # 入口一：读取同步计划文件，逐行入队
    with open(plan_path, 'r', encoding='utf-8') as fh:
        for line in fh:
            host = line.strip()
            if host and not host.startswith('#') and validate_host(host):
                task_queue.put(('sync', host))

def enqueue_retry_journal(journal_path):
    # 入口二：回放失败任务的重试日志，运维脚本会向该文件追加记录
    with open(journal_path, 'r', encoding='utf-8') as fh:
        for line in fh:
            spec = line.strip()
            if spec:
                task_queue.put(('retry', spec))

def worker_loop():
    while True:
        kind, payload = task_queue.get()
        if kind == 'sync':
            run_sync(payload)
        elif kind == 'retry':
            run_retry(payload)
        task_queue.task_done()

def main():
    for _ in range(2):
        threading.Thread(target=worker_loop, daemon=True).start()
    enqueue_plan(sys.argv[1])
    if len(sys.argv) > 2:
        enqueue_retry_journal(sys.argv[2])
    target = os.environ.get('SYNC_TARGET', '')  # 入口三：环境变量触发的即时补同步
    if target:
        ping_probe(target)
    task_queue.join()

if __name__ == '__main__': main()
