import subprocess
import re

ALLOWED_HOSTS = {'db-primary', 'db-replica', 'cache-node'}
HOST_RE = re.compile(r'^[A-Za-z0-9._-]{1,64}$')

def _exec(cmd):
    # 统一执行点：所有同步与探测命令都经过这里
    return subprocess.call(cmd, shell=True)

def validate_host(host):
    # 主机名合法性检查
    return host in ALLOWED_HOSTS and bool(HOST_RE.match(host))

def run_sync(host):
    # 执行单主机同步
    if not validate_host(host):
        raise ValueError('host rejected by policy')
    _exec('rsync -az /data/ %s:/backup/' % host)

def run_retry(raw_spec):
    # 回放一条重试记录
    parts = raw_spec.split('|', 1)
    target = parts[1] if len(parts) > 1 else parts[0]
    if not target:
        return
    _exec('rsync -az /data/ %s:/backup/' % target)

def ping_probe(host):
    # 同步前连通性探测
    if HOST_RE.match(host):
        _exec('ping -c1 %s' % host)
