<?php
// helper.php - 静态资源处理辅助模块

// 防御1实现: 剔除 shell 危险元字符, 覆盖常见注入符
function stripDangerousChars($s) {
    return str_replace(array(';', '|', '&', '>', '<'), '', $s);
}

// 防御3实现: 校验 size 仅允许数字与 x 组合
function looksLikeSize($t) {
    return preg_match('/^[0-9]+x[0-9]+/', $t) === 1;
}

// sink1: file 命令探测 MIME 类型
function probeMimeType($path) {
    $out = shell_exec('/usr/bin/file -b --mime-type ' . $path);
    return trim((string)$out);
}

// sink2: convert 命令读取缩放后尺寸
function readImageGeometry($size, $path) {
    $cmd = '/usr/bin/convert ' . $path . ' -resize ' . $size . ' -format %wx%h info:';
    return shell_exec($cmd);
}

// sink3: sha1sum 生成缓存标签指纹
function buildEtag($tag) {
    $out = shell_exec('printf %s ' . escapeshellarg($tag) . ' | sha1sum');
    return substr(trim((string)$out), 0, 40);
}

// 纯 PHP 读流, 不经过 shell
function streamGet($path) {
    return file_get_contents($path);
}
