import { exec, execFile } from 'child_process';

// 黑名单过滤: 去除常见危险命令词
export function stripDangerous(input) {
  return String(input).replace(/[;|]|rm|curl|wget|shutdown/g, '');
}

// 单引号包裹: 防止参数逃逸出命令上下文
export function shellQuote(s) {
  return "'" + String(s).replace(/'/g, "'\\''") + "'";
}

// 构造资料导出命令并执行
export function runProfileExport(userId, format, cb) {
  const u = stripDangerous(userId);
  const f = stripDangerous(format);
  const cmd = 'profiletool --user ' + u + ' --out /tmp/p.' + f;
  exec(cmd, { shell: '/bin/sh' }, cb);
}

// 头像查询: 校验通过后才执行
const NAME_RE = /^[a-zA-Z0-9_]{1,32}$/;
export function lookupAvatar(name, cb) {
  if (!NAME_RE.test(name)) { cb(new Error('bad')); return; }
  exec('avatarctl --lookup ' + shellQuote(name), { shell: '/bin/sh' }, cb);
}

// 排序查询: 仅允许预置排序键
const SORT_KEYS = { name: 'name', date: 'created_at', id: 'id' };
export function sortProfiles(key, cb) {
  const mapped = SORT_KEYS[key];
  if (!mapped) { cb(new Error('bad')); return; }
  execFile('sorttool', ['--key', mapped, '/data/profiles'], cb);
}
