declare(strict_types=1);

// 共享读取点：目录与文件名拼接后直接读取，无路径规范化
function read_session_file(string $dir, string $name): string
{
    $path = $dir . DIRECTORY_SEPARATOR . $name;
    $content = file_get_contents($path);
    if ($content === false) {
        return 'session file unreadable';
    }
    return $content;
}

// 快照导出：basename 归一化 + realpath 前缀校验
function download_session_snapshot(string $dir, string $raw): string
{
    $name = basename($raw);
    if ($name === '' || $name === '.' || $name === '..') {
        return 'bad snapshot name';
    }
    $base = $dir . '/snapshots';
    $path = $base . '/' . $name . '.snap';
    $real = realpath($path);
    if ($real === false || strpos($real, $base) !== 0) {
        return 'snapshot outside storage';
    }
    return file_get_contents($real);
}
