        String mode = req.getParameter("mode");
        if ("inline".equals(mode)) {
            String tpl = req.getParameter("tplXml");
            if (DOCTYPE_CHECK.matcher(tpl).matches()) {
                resp.sendError(400, "illegal template");
                return;
            }
            resp.getWriter().write(XmlReportHelper.renderTemplate(tpl, req.getParameter("title")));
        } else if ("b64".equals(mode)) {
            String decoded = new String(Base64.getDecoder().decode(req.getParameter("tplB64")), "UTF-8");
            resp.getWriter().write(XmlReportHelper.renderTemplate(decoded, "Monthly Report"));
        } else {
            Part part = req.getPart("reportFile");
            resp.getWriter().write(XmlReportHelper.renderStream(part.getInputStream()));
        }
    }
