package com.acme.report.helper;

import java.io.InputStream;
import java.io.StringReader;
import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import org.w3c.dom.Document;
import org.w3c.dom.NodeList;
import org.xml.sax.InputSource;

public final class XmlReportHelper {

    // 入口A/B 共用: 解析模板并渲染 HTML
    public static String renderTemplate(String xml, String title) {
        try {
            DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
            dbf.setXIncludeAware(true);
            dbf.setNamespaceAware(true);
            DocumentBuilder db = dbf.newDocumentBuilder();
            Document doc = db.parse(new InputSource(new StringReader(xml)));
            NodeList rows = doc.getElementsByTagName("row");
            StringBuilder html = new StringBuilder("<h1>").append(title).append("</h1>");
            for (int i = 0; i < rows.getLength(); i++) {
                html.append("<p>").append(rows.item(i).getTextContent()).append("</p>");
            }
            return html.toString();
        } catch (Exception e) {
            return "render error: " + e.getMessage();
        }
    }

    // 入口C: 解析上传的报表文件
    public static String renderStream(InputStream in) {
        try {
            DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
            dbf.setFeature("http://xml.org/sax/features/external-general-entities", false);
            DocumentBuilder db = dbf.newDocumentBuilder();
            Document doc = db.parse(in);
            return doc.getDocumentElement().getTextContent();
        } catch (Exception e) {
            return "parse error: " + e.getMessage();
        }
    }
}
