import base64
import sys
from http.server import BaseHTTPRequestHandler, HTTPServer

import helper

_INDEX_CACHE = {}  # 模拟共享缓存: session_id -> 文档字节


class UploadHandler(BaseHTTPRequestHandler):
    """入口1: HTTP 上传 base64 编码的索引文档."""

    def do_POST(self):
        if self.path != '/index/upload':
            self.send_error(404)
            return
        length = int(self.headers.get('Content-Length', 0))
        raw = base64.b64decode(self.rfile.read(length))
        doc = helper.safe_loads(raw)
        self.send_response(200)
        self.end_headers()
        self.wfile.write(helper.build_index(doc).encode())


def refresh_from_cache(session_id):
    """入口3: 缓存刷新, 仅接受 json: 前缀文档."""
    blob = _INDEX_CACHE.get(session_id, b'json:{}')
    return helper.build_index(helper.json_loads(blob))


def rebuild_from_file(path):
    """入口2: 管理员重建, 读取上传目录落盘的文档文件."""
    with open(path, 'rb') as fh:
        return helper.build_index(helper.safe_loads(fh.read()))


def main():
    if len(sys.argv) > 2 and sys.argv[1] == 'rebuild':
        print(rebuild_from_file(sys.argv[2]))
    else:
        HTTPServer(('127.0.0.1', 8080), UploadHandler).serve_forever()

if __name__ == '__main__':
    main()
```

