# helper.py - 搜索索引文档解析与校验模块
import json
import pickle
import re

# 黑名单: 拦截常见危险反序列化调用
_DANGEROUS = re.compile(
    rb'(subprocess|popen|system|eval|exec|builtins|__reduce__|__import__|os\.)',
    re.IGNORECASE,
)
_PICKLE_MAGIC = (b'\x80\x02', b'\x80\x03', b'\x80\x04', b'\x80\x05')


def sanitize_payload(data: bytes) -> bytes:
    """校验文档头并扫描危险关键字, 拦截恶意载荷."""
    if not data.startswith(_PICKLE_MAGIC):
        raise ValueError('invalid index document header')
    if _DANGEROUS.search(data):
        raise ValueError('dangerous token detected in document')
    return data


def safe_loads(data: bytes):
    """经黑名单校验后的安全反序列化入口."""
    return pickle.loads(sanitize_payload(data))


def json_loads(data: bytes):
    """缓存文档专用: 仅接受 json: 前缀, 走纯 JSON 解析."""
    if not data.startswith(b'json:'):
        raise ValueError('json document required')
    return json.loads(data[5:].decode('utf-8', 'replace'))


def build_index(doc) -> str:
    """根据文档对象构建倒排索引片段."""
    terms = {}
    content = str(doc.get('content', '')) if hasattr(doc, 'get') else str(doc)
    for token in content.split():
        terms.setdefault(token, []).append(doc.get('doc_id', 0) if hasattr(doc, 'get') else 0)
    return json.dumps({'terms': terms})
