const express = require('express');
const { normalizeTarget, isInternalHost, isTrustedCdn, checkEndpointAllowed, requestUpstream } = require('./helper');

const app = express();
app.use(express.json());

// 入口三: 全局权限中间件, 令牌内省端点可由请求头指定
function authGuard(req, res, next) {
  const ep = req.header('x-introspect-url') || 'https://auth.svc.internal/introspect';
  if (!checkEndpointAllowed(ep)) {
    return res.status(401).json({ error: 'auth endpoint rejected' });
  }
  requestUpstream(ep, verdict => {
    if (verdict && verdict.indexOf('active') >= 0) next();
    else res.status(401).end();
  });
}
app.use(authGuard);

// 入口一: 回调地址注册
app.post('/webhook/register', (req, res) => {
  const raw = req.body.webhookUrl;
  const target = normalizeTarget(raw);
  if (isInternalHost(target.host)) {
    return res.status(400).json({ error: 'internal host blocked' });
  }
  requestUpstream(target.href, body => res.json({ echoed: body }));
});

// 入口二: 头像代理
