// helper.ts —— 上游请求与校验工具集
const http = require('http');
const https = require('https');

const INTERNAL_BLACKLIST = [
  'localhost', '127.0.0.1', '0.0.0.0', '169.254.169.254', 'metadata.google.internal'
];

function normalizeTarget(raw) {
  const u = new URL(String(raw));
  return { host: u.hostname, href: u.href };
}

// 黑名单校验: 拦截已知内网主机
function isInternalHost(host) {
  const h = String(host).toLowerCase();
  return INTERNAL_BLACKLIST.indexOf(h) >= 0;
}

// 白名单校验: 仅允许受信 CDN
function isTrustedCdn(raw) {
  return /^https:\/\/[a-z0-9.-]+\.trusted\.cdn/.test(String(raw));
}

// 端点过滤: 拦截本机地址写法
function checkEndpointAllowed(ep) {
  const s = String(ep);
  return s.indexOf('localhost') < 0 && s.indexOf('127.0.0.1') < 0;
}

// 汇点: 服务端发起上游请求, 响应回显给调用方
function requestUpstream(url, cb) {
  const lib = String(url).startsWith('https:') ? https : http;
  const req = lib.get(url, { timeout: 3000 }, resp => {
    let data = '';
    resp.on('data', c => { data += c; });
    resp.on('end', () => cb(data));
  });
  req.on('error', () => cb(null));
}

module.exports = { normalizeTarget, isInternalHost, isTrustedCdn, checkEndpointAllowed, requestUpstream };
