package main

import (
	"io"
	"net/http"
)

var store = NewStore()

func main() {
	http.HandleFunc("/template/import", handleImport)
	http.HandleFunc("/template/sync", handleSync)
	http.HandleFunc("/template/preview", handlePreview)
	http.ListenAndServe(":8080", nil)
}

func handleImport(w http.ResponseWriter, r *http.Request) { // 入口A: 外部模板导入, 请求体未验证直达反序列化
	raw, _ := io.ReadAll(r.Body)
	tpl, err := ImportTemplate(raw)
	if err != nil || tpl.Name == "" { // 校验位于sink之后, 伪防御
		http.Error(w, "import failed", 400)
		return
	}
	store.Save(tpl.Name, tpl)
	w.Write([]byte("ok"))
}

func handleSync(w http.ResponseWriter, r *http.Request) { // 入口B: 节点同步, HMAC验签通过才解码
	raw, _ := io.ReadAll(r.Body)
	tpl, err := SyncTemplate(raw, r.Header.Get("X-Sync-Sig"))
	if err == nil {
		store.Save(tpl.Name, tpl)
		w.Write([]byte("ok"))
		return
	}
	http.Error(w, "sync rejected", 401)
}

func handlePreview(w http.ResponseWriter, r *http.Request) { // 入口C: 预览仅查白名单
	if out, err := PreviewTemplate(store, r.URL.Query().Get("name")); err == nil {
		w.Write([]byte(out))
	} else {
		http.Error(w, "unknown template", 404)
	}
}
