package main

import (
	"bytes"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/gob"
	"errors"
	"os"
)

type Template struct{ Name, Subject, Body string }
type Store struct{ items map[string]*Template }
func NewStore() *Store { return &Store{items: map[string]*Template{}} }
func (s *Store) Save(name string, t *Template) { s.items[name] = t }
// 流A sink: 对未经验证的外部字节直接执行gob反序列化
func ImportTemplate(blob []byte) (*Template, error) {
	t := new(Template)
	if err := gob.NewDecoder(bytes.NewReader(blob)).Decode(t); err != nil {
		return nil, err
	}
	return t, nil
}
// 流B: 服务端密钥HMAC验签失败即拒绝, 验签通过才解码 —— 真防御
func SyncTemplate(raw []byte, sig string) (*Template, error) {
	mac := hmac.New(sha256.New, []byte(os.Getenv("SYNC_HMAC_KEY")))
	mac.Write(raw)
	if !hmac.Equal(mac.Sum(nil), []byte(sig)) {
		return nil, errors.New("bad signature")
	}
	t := new(Template)
	if err := gob.NewDecoder(bytes.NewReader(raw)).Decode(t); err != nil {
		return nil, err
	}
	return t, nil
}
// 流C: 白名单查表, 不反序列化任何外部字节 —— 真防御
func PreviewTemplate(s *Store, name string) (string, error) {
	if (name != "welcome" && name != "invoice") || s.items[name] == nil {
		return "", errors.New("not allowed")
	}
	t := s.items[name]
	return t.Subject + "\n" + t.Body, nil
}
