package com.richtext;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class main {
    private static final Pattern IMG_SRC = Pattern.compile(
        "<img[^>]+src=([^\\s>]+)", Pattern.CASE_INSENSITIVE);

    // 入口1: 富文本发布, 提取远程图片做审核预取
    public String publishArticle(String articleHtml, String tenantId) throws Exception {
        Matcher m = IMG_SRC.matcher(articleHtml);
        StringBuilder out = new StringBuilder();
        while (m.find()) {
            String imgUrl = m.group(1);
            String target = imgUrl.trim();
            byte[] data = helper.fetchForAudit(target, tenantId);   // 流A
            out.append(data.length).append(';');
        }
        return out.toString();
    }

    // 入口2: 用户头像更新
    public boolean updateAvatar(String avatarUrl, long userId) throws Exception {
        if (!helper.isAllowedHost(avatarUrl)) {   // 流B
            return false;
        }
        helper.downloadAvatar(avatarUrl, userId);
        return true;
    }

    // 入口3: 表情包资源同步
    public String syncEmojiPack(String emojiName) throws Exception {
        String url = "https://cdn.example.com/emoji/" + helper.sanitizePath(emojiName);
        return helper.probe(url);   // 流C
    }

    // 运维探活: 固定地址
