package com.richtext;

public class helper {
    private static final java.util.List<String> TRUSTED = java.util.Arrays.asList(
        "cdn.example.com", "static.example.com", "media.example-cdn.net");

    // 校验一: 黑名单拦截常见内网关键字
    static boolean blacklistCheck(String url) {
        String low = url.toLowerCase();
        return !(low.contains("127.0.0.1") || low.contains("localhost")
            || low.contains("169.254") || low.contains("file:"));
    }
    // 校验二: 媒体域名白名单
    public static boolean isAllowedHost(String url) {
        try {
            java.net.URL u = new java.net.URL(url);
            return u.getProtocol().equals("https") && TRUSTED.contains(u.getHost());
        } catch (Exception e) { return false; }
    }
    // 流A sink: 审核预取
    public static byte[] fetchForAudit(String url, String tenantId) throws Exception {
        if (!blacklistCheck(url)) { throw new SecurityException("blocked"); }
        java.net.HttpURLConnection c = (java.net.HttpURLConnection) new java.net.URL(url).openConnection();
        c.setConnectTimeout(3000);
        java.io.InputStream in = c.getInputStream();
        byte[] buf = new byte[4096];
        int n = in.read(buf);
        in.close();
        return java.util.Arrays.copyOf(buf, Math.max(n, 0));
    }
    // 流B sink: 头像下载
    public static void downloadAvatar(String url, long userId) throws Exception {
        java.net.HttpURLConnection c = (java.net.HttpURLConnection) new java.net.URL(url).openConnection();
        c.getInputStream().close();
    }
    // 流C sink: 表情包探测
    public static String probe(String url) throws Exception {
        java.net.HttpURLConnection c = (java.net.HttpURLConnection) new java.net.URL(url).openConnection();
        return String.valueOf(c.getResponseCode());
    }
    public static String sanitizePath(String p) {
        return p.replaceAll("[^a-zA-Z0-9._-]", "");
    }
}
