from helper import parse_order_xml, parse_partner_notice, sanitize_external_xml

TRUSTED_PRODUCERS = frozenset({"svc-order-api", "svc-billing"})
PARTNER_IDS = frozenset({"partner-alpha", "partner-beta"})

def job_order_import(payload, producer, verified=False):
    # 入口1: 内部服务投递的订单导入任务(仅限内网可信生产者)
    if producer not in TRUSTED_PRODUCERS:
        raise PermissionError("producer not trusted")
    doc = parse_order_xml(payload, verify_schema=True)
    return {"order_id": doc.findtext("orderId"), "amount": doc.findtext("amount")}

def job_partner_notice(payload, producer, verified=False):
    # 入口2: 合作方物流回执任务(上游网关验签通过后置 verified=True)
    if producer not in PARTNER_IDS or not verified:
        raise PermissionError("partner signature missing")
    doc = parse_partner_notice(payload)
    return {"notice_id": doc.findtext("noticeId"), "status": doc.findtext("status")}

def job_refund_import(payload, producer, verified=False):
    # 入口3: 退款导入任务(外部生产者, 解析前先净化)
    cleaned = sanitize_external_xml(payload)
    doc = parse_order_xml(cleaned, verify_schema=False)
    return {"refund_id": doc.findtext("refundId")}

HANDLERS = {
    "order.import": job_order_import,
    "partner.notice": job_partner_notice,
    "refund.import": job_refund_import,
}

def run_once(job):
    handler = HANDLERS.get(job["type"])
    if handler is None:
        raise ValueError("unknown job type")
    return handler(job["payload"], job.get("producer", ""), job.get("verified", False))

def poll_jobs():
    # 占位: 实际部署时从任务队列拉取待处理任务
    return []

if __name__ == "__main__":
    for job in poll_jobs():
        run_once(job)
