from lxml import etree

_ORDER_SCHEMA = None

def _order_schema():
    global _ORDER_SCHEMA
    if _ORDER_SCHEMA is None:
        _ORDER_SCHEMA = etree.XMLSchema(etree.parse("schemas/order.xsd"))
    return _ORDER_SCHEMA

def _build_parser(resolve_entities):
    return etree.XMLParser(
        resolve_entities=resolve_entities,
        no_network=True,
        load_dtd=False,
        dtd_validation=False,
    )

def _fromstring(raw_xml, resolve_entities):
    parser = _build_parser(resolve_entities)
    return etree.fromstring(raw_xml, parser)

def parse_order_xml(raw_xml, verify_schema=True):
    doc = _fromstring(raw_xml, resolve_entities=False)
    if verify_schema and not _order_schema().validate(doc):
        raise ValueError("order schema validation failed")
    return doc

def parse_partner_notice(raw_xml):
    # 兼容旧版合作方报文: 历史格式依赖实体展开, 不能关闭
    body = raw_xml.strip()
    if not body.startswith("<"):
        raise ValueError("payload is not xml")
    return _fromstring(body, resolve_entities=True)

def sanitize_external_xml(raw_xml):
    # 防御: 拒绝任何包含 DOCTYPE 或 ENTITY 声明的外部报文
    lowered = raw_xml.lower()
    if "<!doctype" in lowered or "<!entity" in lowered:
        raise ValueError("doctype or entity declaration forbidden")
    return raw_xml
