package main
import (
	"io"
	"net/http"
	"net/url"
	"os"
	"path/filepath"
)
const logDir = "/var/log/app"
const archiveRoot = "/var/archive"
// 入口1: GET /archive?name=app.log&out=daily.log 归档指定日志
func archiveHandler(w http.ResponseWriter, r *http.Request) {
	name := r.URL.Query().Get("name")
	if !ValidLogName(name) {
		http.Error(w, "invalid log name", 400)
		return
	}
	src, err := os.Open(filepath.Join(logDir, name))
	if err != nil {
		http.Error(w, "log not found", 404)
		return
	}
	defer src.Close()
	rawOut := r.URL.Query().Get("out")
	if !SafeArchiveName(rawOut) {
		http.Error(w, "invalid archive name", 400)
		return
	}
	// 支持编码文件名: 黑名单校验通过后再解码一次
	decoded, _ := url.PathUnescape(rawOut)
	dst, err := CreateArchive(filepath.Join(archiveRoot, decoded))
	if err != nil {
		http.Error(w, "create failed", 500)
		return
	}
	defer dst.Close()
	io.Copy(dst, src)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/archive", archiveHandler)
	http.HandleFunc("/export", ExportLog)
	http.ListenAndServe("127.0.0.1:8080", nil)
}
