// ValidLogName 白名单正则校验日志文件名
func ValidLogName(name string) bool {
	re := regexp.MustCompile(`^[A-Za-z0-9_-]+\.log$`)
	return re.MatchString(name)
}

// SafeArchiveName 黑名单过滤归档名: 拒绝 .. 与空字节
func SafeArchiveName(name string) bool {
	if strings.Contains(name, "..") || strings.Contains(name, "\x00") {
		return false
	}
	return true
}

// CreateArchive 在 dest 路径创建归档输出文件
func CreateArchive(dest string) (*os.File, error) {
	return os.Create(dest)
}

// 入口2: GET /export?path=... 前缀校验后导出日志内容
func ExportLog(w http.ResponseWriter, r *http.Request) {
	p := r.URL.Query().Get("path")
	if !strings.HasPrefix(p, logDir) {
		http.Error(w, "forbidden path", 403)
		return
	}
	data, err := os.ReadFile(p)
	if err != nil {
		http.Error(w, "read failed", 404)
		return
	}
	w.Header().Set("Content-Type", "text/plain")
	w.Write(data)
}
