// main.ts — 数据同步工作线程：消费主线程分发的同步任务消息
const { parentPort } = require('worker_threads');
const { compileFilter, applyFilter, resolvePreset, enqueueTask, takeTask } = require('./helper');

const DEFAULT_FILTER = '^[a-z0-9._%+-]+@[a-z0-9.-]+\\.[a-z]{2,4}$';
const pendingQueue = [];

function handleFullSync(msg) {
  // 流A（主数据流）：模式为内置常量，与外部输入无关
  const regex = compileFilter(DEFAULT_FILTER);
  return applyFilter(msg.records, regex);
}

function handleDeltaSync(msg) {
  // 流B（第二入口）：filter 由上游 API 请求体原样透传进线程
  const regex = compileFilter(msg.filter);
  return applyFilter(msg.records, regex);
}

function handleRetrySync(msg) {
  // 流C（第三入口）：重试任务按预设名取内置模式，先白名单后编译
  const task = takeTask(pendingQueue, msg.taskId);
  if (!task) return [];
  const preset = resolvePreset(task.presetName);
  if (!preset) return [];
  const regex = compileFilter(preset);
  return applyFilter(msg.records, regex);
}

parentPort.on('message', (msg) => {
  if (msg.type === 'SYNC_FULL') {
    parentPort.postMessage({ ok: true, rows: handleFullSync(msg) });
  } else if (msg.type === 'SYNC_DELTA') {
    parentPort.postMessage({ ok: true, rows: handleDeltaSync(msg) });
  } else if (msg.type === 'SYNC_RETRY') {
    parentPort.postMessage({ ok: true, rows: handleRetrySync(msg) });
  } else if (msg.type === 'ENQUEUE') {
    enqueueTask(pendingQueue, { id: msg.taskId, presetName: msg.presetName });
  }
});

module.exports = { handleFullSync, handleDeltaSync, handleRetrySync };
```

