// helper.ts — 数据同步线程的过滤编译与任务队列工具
const MAX_PATTERN_LEN = 64;
const PRESET_FILTERS = {
  recent: '^[a-z0-9._%+-]+@[a-z0-9.-]+\\.[a-z]{2,4}$',
  failed: '^ERR_\\d{4}$'
};

function resolvePreset(name) {
  if (typeof name !== 'string') return null;
  return Object.prototype.hasOwnProperty.call(PRESET_FILTERS, name) ? PRESET_FILTERS[name] : null;
}

function compileFilter(rawPattern) {
  // 仅校验类型与长度上限，未限制嵌套量词等回溯敏感结构
  if (typeof rawPattern !== 'string' || rawPattern.length > MAX_PATTERN_LEN) {
    throw new Error('invalid filter pattern');
  }
  return new RegExp(rawPattern);
}

function applyFilter(records, regex) {
  const out = [];
  for (const rec of records) {
    const blob = String(rec.email) + '|' + String(rec.note);
    // 大批量同步记录上逐条执行回溯敏感匹配
    if (regex.test(blob)) out.push(rec);
  }
  return out;
}

function enqueueTask(queue, task) { queue.push(task); }
function takeTask(queue, taskId) {
  return queue.find(t => t.id === taskId) || null;
}

module.exports = { compileFilter, applyFilter, resolvePreset, enqueueTask, takeTask };
```

