func validSID(sid string) bool {
	if len(sid) != 32 {
		return false
	}
	for _, c := range sid {
		hex := (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f')
		if !hex {
			return false
		}
	}
	return true
