// main.ts —— 消息队列消费者, 三个队列入口
const { MessageBroker } = require('./mq-client');
const {
  verifySignature,
  safeParseState,
  parseTaskPayload,
  runWorkerJob
} = require('./helper');

const ALLOWED_ACTIONS = ['email.send', 'sms.send', 'webhook.ping'];
const broker = new MessageBroker(process.env.BROKER_URL || 'amqp://localhost:5672/vhost');

// 入口A: 订单队列 —— HMAC 签名校验 + 防御性解析
broker.consume('orders.queue', async (msg) => {
  const sig = msg.headers['x-signature'];
  if (!verifySignature(msg.body, sig)) {
    return broker.reject(msg, false);
  }
  const state = safeParseState(msg.body);
  return dispatch({ type: 'order', state });
});

// 入口B: 通知队列 —— 白名单动作过滤
broker.consume('notify.queue', async (msg) => {
  const payload = safeParseState(msg.body);
  if (!payload || !ALLOWED_ACTIONS.includes(payload.action)) {
    return broker.reject(msg, false);
  }
  return dispatch({ type: 'notify', action: payload.action });
});

// 入口C: 管理任务队列 —— 原始字节直接对象反序列化
broker.consume('admin.queue', async (msg) => {
  const job = parseTaskPayload(msg.body);
  if (!job || job.origin !== 'internal-scheduler') {
    return broker.reject(msg, false);
  }
  return runWorkerJob(job);
});

function dispatch(task) {
  return broker.publish('worker.tasks', Buffer.from(JSON.stringify(task)));
}
