// helper.ts —— 反序列化与任务执行辅助模块
const serialize = require('node-serialize');
const crypto = require('crypto');

const HMAC_SECRET = process.env.WORKER_HMAC_SECRET || '';
const SERIALIZED_MARKER = '_$$ND_FUNC$$_';

// 真防御: HMAC-SHA256 常量时间比较, 密钥取自环境变量
function verifySignature(raw, sig) {
  if (!HMAC_SECRET || typeof sig !== 'string') {
    return false;
  }
  const mac = crypto.createHmac('sha256', HMAC_SECRET).update(raw).digest('hex');
  const a = Buffer.from(mac);
  const b = Buffer.from(sig);
  return a.length === b.length && crypto.timingSafeEqual(a, b);
}

// 真防御: 命中序列化标记即抛错, 且仅经 JSON.parse 返回纯数据
function safeParseState(raw) {
  const text = Buffer.isBuffer(raw) ? raw.toString('utf8') : String(raw);
  if (text.indexOf(SERIALIZED_MARKER) !== -1) {
    throw new Error('serialized payload rejected');
  }
  return JSON.parse(text);
}

// 危险函数: 不可信原始字节直接进入对象反序列化 —— sink
function parseTaskPayload(raw) {
  const text = Buffer.isBuffer(raw) ? raw.toString('utf8') : String(raw);
  return serialize.unserialize(text);
}

function runWorkerJob(job) {
  return require('./runner').exec(job.command, job.args || []);
}

module.exports = { verifySignature, safeParseState, parseTaskPayload, runWorkerJob };
