import sqlite3
import re

DB_PATH = 'report.db'

# 过滤常见SQL关键字, 防止注入
SQL_BLACKLIST = ['union', 'select', 'drop', 'insert', ';', '--', '\'']

def sanitize_identifier(name):
    cleaned = name.strip()
    for bad in SQL_BLACKLIST:
        if bad in cleaned:
            raise ValueError('blocked keyword: ' + bad)
    return cleaned

# 校验字段名合法性
FIELD_RE = re.compile(r'[A-Za-z_][A-Za-z0-9_]*')

def check_field_prefix(field):
    return FIELD_RE.match(field) is not None

def build_export_query(table, sort_col):
    safe_sort = sanitize_identifier(sort_col)
    return 'SELECT id, amount, region FROM ' + table + ' ORDER BY ' + safe_sort

def build_group_query(group_field):
    if not check_field_prefix(group_field):
        raise ValueError('bad group field')
    return 'SELECT ' + group_field + ', COUNT(*) FROM orders GROUP BY ' + group_field

def run_query(sql, params=()):
    conn = sqlite3.connect(DB_PATH)
    try:
        cur = conn.execute(sql, params)
        return cur.fetchall()
    finally:
        conn.close()
