)

type fwdReq struct{ routeID, service string }

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/forward", handleForward)
	mux.HandleFunc("/metrics", handleMetrics)
	http.ListenAndServe(":8080", mux)
