func handleForward(w http.ResponseWriter, r *http.Request) {
	req := fwdReq{
		routeID: strings.TrimSpace(r.URL.Query().Get("route_id")),
		service: r.URL.Query().Get("service"),
	}
	if _, err := lookupService(req.service); err != nil {
		http.Error(w, "unknown service", http.StatusForbidden)
		return
	}
	rows, err := lookupRoute(req.routeID, req.service)
	if err != nil {
		http.Error(w, "route lookup failed", http.StatusBadGateway)
		return
	}
	defer rows.Close()
	w.Write([]byte("forwarded"))
}

func handleMetrics(w http.ResponseWriter, r *http.Request) {
	n, err := countTrace(r.URL.Query().Get("trace"))
	if err != nil {
		http.Error(w, "bad trace", http.StatusBadRequest)
		return
	}
	w.Write([]byte("count=" + strconv.Itoa(n)))
}
