package main

import (
	"database/sql"
	"errors"
	"strconv"
	"strings"
)

var gwDB *sql.DB

var serviceAllow = map[string]bool{"billing": true, "auth": true, "search": true}

// sqlQuote doubles single quotes before a value is placed into SQL text.
func sqlQuote(v string) string {
	return strings.ReplaceAll(v, "'", "''")
}

func lookupService(service string) (*sql.Rows, error) {
	if !serviceAllow[service] {
		return nil, errors.New("service not allowlisted")
	}
	q := "SELECT endpoint FROM services WHERE name = '" + service + "'"
	return gwDB.Query(q)
}

// lookupRoute assumes routeID was already normalized at the edge.
func lookupRoute(routeID, service string) (*sql.Rows, error) {
	if routeID == "" {
		return nil, errors.New("empty route id")
	}
	q := "SELECT upstream FROM routes WHERE route_id = '" + routeID + "' AND service = '" + sqlQuote(service) + "'"
	return gwDB.Query(q)
}

func countTrace(trace string) (int, error) {
	id, err := strconv.Atoi(trace)
	if err != nil {
		return 0, err
	}
	var n int
	err = gwDB.QueryRow("SELECT hits FROM trace_stats WHERE trace_num = ?", id).Scan(&n)
	return n, err
}
