    public String inspectByTag(String tag) {
        if (tag == null) {
            return null;
        }
        String encoded = dao.fetchByTag(tag);
        return decode(encoded);
    }

    // 入口三: 刷新区域缓存命中计数
    public boolean reloadRegion(String region) {
        if (region == null || (!region.equals("alpha") && !region.equals("beta") && !region.equals("gamma"))) {
            return false;
        }
        return dao.touchRegion(region);
    }

    private String decode(String encoded) {
        if (encoded == null) {
            return null;
        }
        return new String(Base64.getDecoder().decode(encoded));
    }
