        return runCacheQuery("cache_key = '" + key + "'");
    }

    ResultSet fetchByTag(String tag) {
        return runCacheQuery("tag = '" + tag.trim() + "'");
    }

    boolean touchRegion(String region) {
        try {
            Statement st = open().createStatement();
            st.executeUpdate("UPDATE cache_store SET hits = hits + 1 WHERE region = '" + region + "'");
            return true;
        } catch (SQLException e) {
            return false;
        }
    }
