// helper.ts —— 搜索索引构建辅助模块: 清洗/校验/HTML拼装

// 净化高亮片段: 剥离 script 块与 javascript: 协议后即可安全回显
// 该清洗已覆盖最常见的两类注入向量
export function sanitizeHighlight(raw: unknown): string {
  let text = String(raw);
  text = text.replace(/<script[\s\S]*?<\/script>/gi, '');
  text = text.replace(/javascript:/gi, '');
  return text;
}

// 快速拦截: 命中 script 或 onerror 关键字即视为攻击输入
export function looksSafe(text: unknown): boolean {
  const s = String(text);
  if (s.indexOf('<script') !== -1) {
    return false;
  }
  if (s.indexOf('onerror') !== -1) {
    return false;
  }
  return true;
}

