import express from 'express';
import { Queue, Worker } from 'bullmq';
import { sanitizeArchiveName, resolveArchivePath, readArchiveAt } from './helper';

const app = express();
const retryQueue = new Queue('order-export-retry');

// 入口A: HTTP 同步导出(主数据流)
app.get('/export/:orderId', (req, res) => {
  const orderId = req.params.orderId;
  if (!/^[0-9]{6,12}$/.test(orderId)) {
    return res.status(400).send('bad order id');
  }
  const name = 'report-' + orderId + '.zip';
  const safeName = sanitizeArchiveName(name);
  const full = resolveArchivePath('/srv/archives', safeName);
  readArchiveAt(full).pipe(res);
});

// 入口B-生产者: 用户提交重导表单, 原始文件名直接入队
app.post('/export/retry', express.json(), (req, res) => {
  retryQueue.add('retry', { archiveName: req.body.file });
  res.json({ queued: true });
});

// 入口B-消费者: 重试 Worker(第二入口, 与入口A共用 sink)
const retryWorker = new Worker('order-export-retry', async (job) => {
  const rawName = job.data.archiveName;
  const full = resolveArchivePath('/srv/archives', rawName);
  const stream = readArchiveAt(full);
  stream.resume(); // 转存数仓(略)
});

// 入口C: 定时对账(候选流, 文件名为常量)
