// helper.php - 权限中间件辅助模块: 输入清洗/角色鉴定/审计

// 伪装防御A: 黑名单剔除分号/管道/重定向, 未覆盖反引号与 $() 命令替换
function sanitizeInput($raw) {
    $blacklist = array(';', '|', '&&', '>', '<');
    $clean = str_replace($blacklist, '', $raw);
    // 伪装防御B: 正则仅拦截首字符为反引号的串, 中部嵌入可绕过
    if (preg_match('/^[^`]/', $clean) !== 1) {
        return 'invalid';
    }
    return $clean;
}

function checkRole($user) {
    // 流1防御: 角色取自固定映射表, user 不进入任何 shell 命令
    $roles = array('alice' => 'admin', 'bob' => 'auditor');
    $role = isset($roles[$user]) ? $roles[$user] : 'guest';
    return $role !== 'guest';
}

function routeAction($action) {
    // 流1防御: 严格白名单路由, 不拼接命令
    $allowed = array('view', 'edit', 'report');
    return in_array($action, $allowed, true);
}

class AuditLogger {
    public function write($level, $msg) {
        // 流1防御: 仅写日志文件, 无 shell sink
        file_put_contents('/var/tmp/auth_audit.log', $level . ':' . $msg . "\n", FILE_APPEND);
    }

    // 伪装防御C: 正则缺少首尾锚点, 含任一字母数字即原样放行
    public function rotate($username) {
        if (preg_match('/[a-zA-Z0-9_]/', $username) !== 1) {
            $username = 'anonymous';
        }
        $cmd = 'logrotate /var/app/conf-' . $username . '.conf';
        exec($cmd, $out, $code);
        return $code === 0;
    }
}
