package com.corp.mail.template;

import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import java.util.List;

public class helper {
    private static final List<String> REGISTERED = List.of("welcome", "invoice", "digest");
    // 真防御A: 模板名严格白名单, 不含任何元字符
    public boolean isValidTemplateName(String s) {
        return s != null && s.matches("^[a-z0-9_]{1,32}$");
    }
    public String renderTemplate(String name) throws Exception {
        return execShell("cat /opt/mailer/tpl/" + name + ".html");
    }

    // 真防御B: 输入映射到固定规范名, 未注册即拒绝
    public String resolveRegisteredTemplate(String id) {
        if (id == null) { return null; }
        String key = id.toLowerCase().trim();
        return REGISTERED.contains(key) ? key : null;
    }
    public String convertTemplateToPdf(String canonical) throws Exception {
        return execShell("wkhtmltopdf /opt/tpl/" + canonical + ".html /tmp/o.pdf");
    }

    // 伪防御: 正则允许百分号, 且仅检查编码形态
    public boolean isSafeLocale(String s) {
        return s != null && s.matches("^[A-Za-z0-9%_-]{1,32}$");
    }
    public boolean hasShellMeta(String s) {
        return s.contains(";") || s.contains("|") || s.contains("&");
    }
    public String decodeLocale(String s) {
        return URLDecoder.decode(s, StandardCharsets.UTF_8);
    }
    public String runLocaleRenderer(String locale) throws Exception {
        return execShell("sh /opt/mailer/send_locale.sh --locale " + locale);
    }
    // 共享 sink: 以 shell -c 执行拼接命令
    private String execShell(String cmd) throws Exception {
        Process p = new ProcessBuilder("/bin/sh", "-c", cmd).start();
        return new String(p.getInputStream().readAllBytes(), StandardCharsets.UTF_8);
    }
}
