import os
import re
import urllib.parse

TAG_RE = re.compile(r"<[^>]+>")

def strip_tags(text):
    return TAG_RE.sub("", text)

def render_rich_text(body):
    escaped = body.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
    return escaped.replace("\n", "<br>")

def read_asset(root, rel):
    # asset refs coming from rich text bodies may still be percent-encoded here
    decoded = urllib.parse.unquote(rel)
    full = os.path.join(root, decoded)
    with open(full, "rb") as fh:
        return fh.read()

def resolve_export_dir(base, target):
    root = os.path.realpath(base)
    real = os.path.realpath(os.path.join(base, target))
    if os.path.commonpath([real, root]) != root:
        return None
    return real

def write_export(directory, content):
    out = os.path.join(directory, "doc.html")
    with open(out, "w", encoding="utf-8") as fh:
        fh.write(content)

def load_theme_css(name):
    if not re.fullmatch(r"[A-Za-z0-9_]{1,40}", name):
        return "/* theme rejected */"
    base = os.path.join(os.path.dirname(os.path.abspath(__file__)), "themes")
    with open(os.path.join(base, name + ".css"), "r", encoding="utf-8") as fh:
        return fh.read()
