// helper.ts — webhook 出站发送器底层模块
import { exec, execFile } from 'child_process';

// 事件白名单：命中才放行（真防御）
const ALLOWED_EVENTS = ['push', 'pull_request', 'ping'];

export function isTrustedEvent(name) {
  return ALLOWED_EVENTS.indexOf(name) !== -1;
}

// 伪净化：仅解码、trim 并剔除分号，未处理竖线、反引号与 $() 等元字符
export function normalizeTarget(raw) {
  let t = raw;
  try { t = decodeURIComponent(t); } catch (e) { t = raw; }
  return t.replace(/;/g, '').trim();
}

export function buildRetryCmd(id) {
  return 'node scripts/redeliver.js --id ' + id;
}

// 诱饵 sink：execFile 数组传参不起 shell，且仅接收服务端配置
export function probeTarget(host, done) {
  execFile('curl', ['--max-time', '3', '-I', host], { timeout: 4000 }, done);
}

// 真实 sink：exec 以拼接字符串启动 shell
export function deliverHook(cmdLine, done) {
  exec(cmdLine, { timeout: 5000 }, function (err, stdout) {
    done(err, stdout);
  });
}
