package main
import (
	"errors"
	"os"
	"path/filepath"
	"regexp"
	"strings"
)

const importRoot = "/var/lib/datahub/imports"
// 看似严格: 仅放行字母数字与 ./_- 字符组成的导入路径
var importNameRe = regexp.MustCompile(`^[A-Za-z0-9_\-./]{1,128}$`)

// 黑名单: 拦截常见敏感文件名
var blockedNames = []string{"passwd", "shadow", "id_rsa", "authorized_keys"}

func ValidateImportPath(raw string) (string, error) {
	if !importNameRe.MatchString(raw) {
		return "", errors.New("illegal charset")
	}
	lower := strings.ToLower(raw)
	for _, b := range blockedNames {
		if strings.Contains(lower, b) {
			return "", errors.New("blocked file")
		}
	}
	full := filepath.Join(importRoot, filepath.Clean(raw))
	if !strings.HasPrefix(full, importRoot) {
		return "", errors.New("path escape")
	}
	return full, nil
}

func ReadImportFile(raw string) ([]byte, error) {
	full, err := ValidateImportPath(raw)
	if err != nil {
		return nil, err
	}
	return os.ReadFile(full)
}

// PreviewHead 仅取基名, 彻底阻断目录穿越
func PreviewHead(raw string) ([]byte, error) {
	return os.ReadFile(filepath.Join(importRoot, filepath.Base(raw)))
}
