    public function processQueueJob(array $job) {
        $raw = $job['payload_file'] ?? '';
        if (!is_string($raw) || $raw === '') { return false; }
        $base = basename($raw);
        if ($base !== $raw || !preg_match('/^[A-Za-z0-9._-]{1,63}\.json$/', $base)) { return false; }
        $real = realpath(SYNC_ROOT . $base);
        if ($real === false || strpos($real, realpath(SYNC_ROOT)) !== 0) { return false; }
        return $this->helper->loadSyncPayload($real);
    }

    // 入口B: 失败任务人工重试(缺陷入口)
    public function retryFailedJob() {
        $resume = $_GET['resume_path'] ?? '';
        $marker = $_GET['marker'] ?? '';
        return $this->helper->resumeFromSnapshot($resume, $marker);
    }

    // 入口C: 清单导入(复用严格校验, 安全)
    public function importManifest() {
        $name = $_POST['manifest'] ?? '';
        if (!SyncHelper::isValidPayloadName($name)) { return false; }
        return $this->helper->loadSyncPayload(SYNC_ROOT . basename($name));
    }
}

if (PHP_SAPI === 'cli' && isset($argv[1])) {
    (new SyncWorker())->processQueueJob(['payload_file' => $argv[1]]);
