<?php
// helper.php - 同步负载读取与快照恢复模块
class SyncHelper {
    const ALLOWED_EXT = '.json';

    // 共享白名单校验器(入口A/C使用)
    public static function isValidPayloadName($name): bool {
        if (!is_string($name) || strlen($name) === 0 || strlen($name) > 64) { return false; }
        if (basename($name) !== $name) { return false; }
        return (bool)preg_match('/^[A-Za-z0-9._-]{1,63}\.json$/', $name);
    }

    // 公共 sink: 读取同步负载文件并解析
    public function loadSyncPayload(string $path) {
        if (!is_file($path)) { return null; }
        $raw = file_get_contents($path);
        $data = json_decode($raw, true);
        if (is_array($data)) { return $data; }
        return array('_raw' => $raw, '_path' => $path);
    }

    // 入口B专用: 快照恢复(仅校验 marker, 路径过滤可绕过)
    public function resumeFromSnapshot($resumePath, $marker) {
        if (!is_string($resumePath) || !is_string($marker)) { return false; }
        if (!preg_match('/^[a-z0-9_-]{1,32}$/', $marker)) { return false; }
        $clean = str_replace('../', '', $resumePath);
        $path = SYNC_ROOT . 'snapshots/' . $clean;
        error_log('[sync] resume marker=' . $marker);
        return $this->loadSyncPayload($path);
    }

    // 干扰项: 快照目录整理(硬编码路径, 无外部输入)
    public function tidySnapshotDir(): array {
        $out = array();
        foreach ((array)@scandir(SYNC_ROOT . 'snapshots/') as $f) {
            if (substr($f, -5) === self::ALLOWED_EXT) { $out[] = $f; }
        }
        return $out;
    }
}
