    static String serveResource(HttpServletRequest req, HttpServletResponse resp) throws Exception {
        String name = req.getParameter("file");
        Path target = WEB_ROOT.resolve(name).normalize();
        if (!target.startsWith(WEB_ROOT)) return "forbidden";
        String content = new String(Files.readAllBytes(target), StandardCharsets.UTF_8);
        if (name.endsWith(".xml") || name.endsWith(".svg")) {
            resp.setHeader("X-Resource-Title", helper.parseXmlMetadata(content, true));
        }
        Files.copy(target, resp.getOutputStream());
        return "served";
    }

    // 入口2：XML 上传校验并落盘存储
    static String handleUpload(HttpServletRequest req) throws Exception {
        BufferedReader br = req.getReader();
        StringBuilder sb = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) sb.append(line).append('\n');
        String verdict = helper.parseXmlMetadata(sb.toString(), false);
        Files.write(WEB_ROOT.resolve("uploads/" + System.currentTimeMillis() + ".xml"), sb.toString().getBytes(StandardCharsets.UTF_8));
        return verdict;
    }

    // 入口3：别名预览，走可信解析通道
    static String previewAlias(HttpServletRequest req) throws Exception {
        String alias = req.getParameter("alias");
        if (alias == null || !alias.matches("[a-z0-9-]{1,32}")) return "bad-alias";
        Path cfg = WEB_ROOT.resolve("aliases/" + alias + ".xml");
        if (!Files.exists(cfg)) return "not-found";
        return helper.parseTrustedXml(new String(Files.readAllBytes(cfg), StandardCharsets.UTF_8));
    }
}
