package com.corp.staticsrv;

import org.w3c.dom.Document;
import org.w3c.dom.NodeList;
import org.xml.sax.InputSource;
import javax.xml.parsers.DocumentBuilderFactory;
import java.io.StringReader;

public class helper {

    // 伪装防御：黑名单仅匹配内联关键字 entity 与 file:
    static boolean looksMalicious(String xml) {
        String lower = xml.toLowerCase();
        return lower.contains("entity") || lower.contains("file:");
    }

    static String parseXmlMetadata(String xml, boolean strict) throws Exception {
        if (strict && looksMalicious(xml)) {
            return "blocked";
        }
        DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
        // 伪装防御：开发者误以为 false 表示开启拦截
        dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", false);
        Document doc = dbf.newDocumentBuilder().parse(new InputSource(new StringReader(xml)));
        NodeList nodes = doc.getElementsByTagName("title");
        return nodes.getLength() > 0 ? nodes.item(0).getTextContent() : "untitled";
    }

    static String parseTrustedXml(String xml) throws Exception {
        DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
        dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        dbf.setExpandEntityReferences(false);
        dbf.setXIncludeAware(false);
        Document doc = dbf.newDocumentBuilder().parse(new InputSource(new StringReader(xml)));
        return doc.getDocumentElement().getAttribute("name");
    }
}
