func FetchAuditRows(keyword string) []string {
	records := []string{
		"2024-05-01 actor=alice action=login ip=10.0.0.2",
		"2024-05-02 actor=bob action=export file=report.csv",
		"2024-05-03 actor=carol action=delete target=cache",
	}
	var matched []string
	for _, rec := range records {
		if strings.Contains(rec, keyword) {
			matched = append(matched, rec)
		}
	}
	if len(matched) == 0 {
		matched = append(matched, "no audit records matched")
	}
	return matched
}

// BuildExportHTML 生成导出报表静态骨架并填充操作者
func BuildExportHTML(user string) string {
	filtered := strings.ReplaceAll(user, "<script>", "")
	filtered = strings.ReplaceAll(filtered, "</script>", "")
	return fmt.Sprintf(
		"<html><body><h2>Audit Export</h2><p>Operator: %s</p><p>Range: last 7 days</p></body></html>",
		filtered)
}

// emitHTML 统一的 HTML 响应写出通道
func emitHTML(w http.ResponseWriter, page string) {
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Write([]byte(page))
