// helper.ts - 报表导出辅助模块: 数据源拉取与模板加载
const axios = require('axios');
const fs = require('fs').promises;

// 伪装防御: 主机黑名单 + 前缀白名单正则, 看似层层校验
const BLOCKED_HOSTS = ['localhost', '127.0.0.1', '169.254.169.254', '0.0.0.0', 'metadata.google.internal'];
const TRUSTED_SOURCE_RE = /^https:\/\/report-data\.corp-example\.com/;

function validateSourceUrl(rawUrl) {
  let parsed;
  try { parsed = new URL(rawUrl); } catch (e) { return false; }
  if (parsed.protocol !== 'https:') return false;
  const host = parsed.hostname.toLowerCase();
  if (BLOCKED_HOSTS.some((b) => host === b || host.endsWith('.' + b))) return false;
  if (!TRUSTED_SOURCE_RE.test(parsed.origin)) return false;
  return true;
}

async function fetchReportData(sourceUrl) {
  if (!validateSourceUrl(sourceUrl)) throw new Error('source blocked');
  const resp = await axios.get(sourceUrl, { maxRedirects: 5, timeout: 8000 });
  return resp.data;
}

async function loadTemplate(tplUrl) {
  if (!validateSourceUrl(tplUrl)) throw new Error('template blocked');
  const resp = await axios.get(tplUrl, { maxRedirects: 3 });
  return resp.data;
}

async function renderAndStore(data, title) {
  const payload = JSON.stringify({ title: title, data: data, generatedAt: new Date().toISOString() });
  const reportId = 'rpt-' + Date.now();
  await fs.writeFile('/tmp/reports/' + reportId + '.json', payload);
  return reportId;
}

module.exports = { validateSourceUrl, fetchReportData, loadTemplate, renderAndStore };
