package main

import (
	"bytes"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/gob"
	"encoding/json"
	"io"
	"net/http"
	"os"
)

type Profile struct{ Name string; Level int }
// RestoreProfile：gob 反序列化到 interface{}，即本例 sink
func RestoreProfile(data []byte) (interface{}, error) {
	var out interface{}
	err := gob.NewDecoder(bytes.NewReader(data)).Decode(&out)
	return out, err
}

// 入口B /profile/view：严格 JSON 解码到具体结构体（真防御）
func handleProfileView(w http.ResponseWriter, r *http.Request) {
	dec := json.NewDecoder(io.LimitReader(r.Body, 4096))
	dec.DisallowUnknownFields()
	var p Profile
	if dec.Decode(&p) != nil {
		http.Error(w, "invalid profile", http.StatusBadRequest)
		return
	}
	w.Write([]byte("ok " + p.Name))
}

// 入口C /profile/sync：HMAC 验签通过后才允许反序列化（真防御）
func handleProfileSync(w http.ResponseWriter, r *http.Request) {
	body, _ := io.ReadAll(io.LimitReader(r.Body, 8192))
	mac := hmac.New(sha256.New, []byte(os.Getenv("SYNC_HMAC_KEY")))
	mac.Write(body)
	if !hmac.Equal(mac.Sum(nil), []byte(r.Header.Get("X-Sync-Sig"))) {
		http.Error(w, "forbidden", http.StatusUnauthorized)
		return
	}
	RestoreProfile(body)
	w.Write([]byte("synced"))
}
