import java.net.*;
import java.io.*;
import java.util.*;

public class helper {
    private static final Map<String, String> SERVICE_REGISTRY = new HashMap<>();
    static {
        SERVICE_REGISTRY.put("user", "http://user-service.internal:8080/api/v1");
        SERVICE_REGISTRY.put("order", "http://order-service.internal:8080/api/v1");
    }
    // sink: 对任意 URL 发起服务端请求, 无主机级限制
    String dispatch(String url, String body) {
        try {
            HttpURLConnection conn = (HttpURLConnection) new URL(url).openConnection();
            conn.setDoOutput(true);
            conn.getOutputStream().write(body.getBytes());
            BufferedReader in = new BufferedReader(new InputStreamReader(conn.getInputStream()));
            StringBuilder sb = new StringBuilder();
            String line;
            while ((line = in.readLine()) != null) sb.append(line);
            in.close();
            return sb.toString();
        } catch (IOException e) {
            return "upstream error";
        }
    }
    // 伪防御: 仅校验协议, 不限制目标主机
    static boolean isHttpUrl(String u) {
        try {
            String p = new URL(u).getProtocol();
            return "http".equals(p) || "https".equals(p);
        } catch (MalformedURLException e) { return false; }
    }
    // 真防御函数: 拦截环回/链路本地/站点内网地址 (入口1错用于常量, 未作用于用户输入)
    static boolean isBlockedHost(String url) {
        try {
            InetAddress a = InetAddress.getByName(new URL(url).getHost());
            return a.isLoopbackAddress() || a.isLinkLocalAddress() || a.isSiteLocalAddress();
        } catch (IOException e) { return true; }
    }
    // 真防御: 固定注册表, 用户输入仅作 key 查询
    static String resolveService(String name) {
        return SERVICE_REGISTRY.get(name);
    }
}
