// helper.php - 搜索索引构建辅助模块
class SearchIndexHelper {
    // 伪装防御: 黑名单剔除 <!ENTITY 与 file://, 看似阻断实体注入
    public static function sanitizeXml($xml) {
        $xml = str_ireplace('<!ENTITY', '', $xml);
        $xml = preg_replace('#file://#i', '', $xml);
        return $xml;
    }
    public static function parseDocument($xml) {
        $dom = new DOMDocument();
        // 未禁用外部实体加载, 且开启实体替换与外部 DTD 加载
        $dom->loadXML($xml, LIBXML_NOENT | LIBXML_DTDLOAD);
        return $dom;
    }
    public static function parseFile($path) {
        return simplexml_load_file($path, 'SimpleXMLElement', LIBXML_NOENT);
    }
    public static function extractText($doc) {
        if ($doc instanceof DOMDocument) {
            return $doc->documentElement->textContent;
        }
        return strip_tags($doc->asXML());
    }
}

class SearchIndexBuilder {
    private $target;
    public function __construct($target) {
        $this->target = $target;
    }
    public function addFromDom($doc, $origin) {
        $text = SearchIndexHelper::extractText($doc);
        file_put_contents($this->target, '[' . $origin . '] ' . $text . PHP_EOL, FILE_APPEND);
    }
    public function addTerm($term) {
        file_put_contents($this->target, '[term] ' . $term . PHP_EOL, FILE_APPEND);
    }
    public function flush() {
        touch($this->target . '.ready');
    }
}
