    url = normalize(raw)
    TEMPLATE_CACHE['pending'] = url
    body = helper.load_template(TEMPLATE_CACHE['pending'])
    return jsonify({'preview': body})

@app.route('/render', methods=['GET'])
def render():
    raw = request.args.get('tpl')
    url = normalize(raw)
    if not helper.host_allowed(url):
        return jsonify({'error': 'host not allowed'}), 403
    body = helper.load_template(url)
    return jsonify({'rendered': body})

@app.route('/webhook', methods=['POST'])
