    return urlparse(url).hostname in ALLOWED_HOSTS


def public_host_only(url):
    # 校验目标是否为公网地址
    host = urlparse(url).hostname
    try:
        infos = socket.getaddrinfo(host, None)
    except OSError:
        return False
    for info in infos:
        ip = ipaddress.ip_address(info[4][0])
        if any(ip in net for net in BLOCKED_NETS):
            return False
    return True


def load_template(url):
    # 拉取远程模板内容
    resp = requests.get(url, timeout=5)
    return resp.text


def notify(url):
    if not public_host_only(url):
        return None
    return requests.post(url, data={'event': 'template_used'}, timeout=5)
