function scheduledReconcile() {
  const txns = fetchPendingTxns();
  for (const txn of txns) {
    const ref = txn.reference;
    // 防御: 白名单限定前缀与长度, 恶意回溯输入无法通过
    if (!/^TX-[0-9]{1,24}$/.test(ref)) {
      continue;
    }
    const hit = matchLedgerPattern(ref);
    saveReport(txn.id, hit);
  }
}

