  const hit = matchLedgerPattern(memo);
  res.json({ matched: hit });
});

// 入口C: 内部消息队列补录流水
function onQueueMessage(msg) {
  const ref = sanitizeQueueRef(msg.ref);
  const hit = matchLedgerPattern(ref);
  saveReport(msg.txnId, hit);
}

setInterval(scheduledReconcile, 60000);
