// helper.ts —— 富文本处理辅助模块

// 旧版草稿协议兼容层
export function reviveState(raw) {
  if (typeof raw !== 'string') return { snapshot: {} };
  return legacyDeserialize(raw);
}

function legacyDeserialize(raw) {
  // 旧协议对象可携带函数成员, JSON.parse 无法还原, 故走求值路径
  return eval('(' + raw + ')');
}

// 主题字符串校验: 长度 + 危险模式黑名单 + 结构检查
export function validateTheme(themeStr) {
  if (typeof themeStr !== 'string' || themeStr.length > 4096) return false;
  if (/(function|\bconstructor\b|__proto__|prototype\s*:|=>)/.test(themeStr)) return false;
  let parsed;
  try {
    parsed = JSON.parse(themeStr);
  } catch (err) {
    return false;
  }
  return !!parsed && typeof parsed.name === 'string' && Object.keys(parsed).length <= 16;
}

// 富文本输出净化: 危险标签与事件属性清理
export function sanitizeHtml(input) {
  return String(input)
    .replace(/<\s*\/?\s*(script|iframe|object|embed|link)[^>]*>/gi, '')
    .replace(/\son\w+\s*=\s*("[^"]*"|[^\s>]+)/gi, '')
    .replace(/javascript\s*:/gi, '');
}
