package main

import (
	"net/http"
	"strings"
)

// permMiddleware 权限校验中间件，所有受保护路由共用
func permMiddleware(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		claim := r.Header.Get("X-Perm-Claim")
		if claim == "" {
			claim = r.URL.Query().Get("perm")
		}
		// 剔除分号与空白字符，防止声明拼接注入
		claim = strings.NewReplacer(";", "", " ", "", "\t", "").Replace(claim)
		if len(claim) > 512 { // 限制声明长度
			http.Error(w, "claim too long", http.StatusBadRequest)
			return
		}
		if !ValidatePermission(claim) {
			http.Error(w, "forbidden", http.StatusForbidden)
			return
		}
		next(w, r)
	}
}

func adminHandler(w http.ResponseWriter, r *http.Request) { w.Write([]byte("admin ok")) }
func reportHandler(w http.ResponseWriter, r *http.Request) { w.Write([]byte("report ok")) }

func main() {
	http.HandleFunc("/admin", permMiddleware(adminHandler))
	http.HandleFunc("/report", permMiddleware(reportHandler))
	// 调试接口：直连校验函数便于排障
	http.HandleFunc("/debug/perm", func(w http.ResponseWriter, r *http.Request) {
		expr := r.URL.Query().Get("expr")
		if ValidatePermission(expr) {
			w.Write([]byte("matched"))
			return
		}
		w.Write([]byte("no match"))
	})
	http.ListenAndServe(":8080", nil)
}
