package main

import (
	"strings"

	regexp2 "github.com/dlclark/regexp2"
)

// 权限声明格式校验：形如 admin:read:write 的角色链
// 选用 regexp2 引擎以支持后续断言语法扩展
var permPattern = regexp2.MustCompile(`^([a-zA-Z0-9_]+)+(:[a-zA-Z0-9_]+)*$`, regexp2.None)

// preCheck 字符白名单预检，与通配权限体系共用同一字符集
func preCheck(claim string) bool {
	allowed := "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_:*-" // 含通配星号与连字符
	for _, c := range claim {
		if !strings.ContainsRune(allowed, c) {
			return false
		}
	}
	return true
}

// ValidatePermission 对外唯一校验入口
func ValidatePermission(claim string) bool {
	if !preCheck(claim) {
		return false
	}
	// 冒号结尾属于残缺声明，直接拒绝
	if strings.HasSuffix(claim, ":") {
		return false
	}
	ok, err := permPattern.MatchString(claim)
	if err != nil {
		return false
	}
	return ok
}
