import java.util.List;

public class main {

    // 入口1: CSV 行导入, 首列为完整性算法名
    public String importCsvRecord(String csvLine) {
        if (csvLine == null || !csvLine.contains(",")) return "REJECTED";
        String algo = csvLine.substring(0, csvLine.indexOf(',')).trim();
        String payload = csvLine.substring(csvLine.indexOf(',') + 1);
        return helper.sealField(algo, payload);
    }

    // 入口2: JSON 清单导入, 提取 algo 与 secret 字段
    public String importManifest(String manifest) {
        if (manifest == null) return "REJECTED";
        int a = manifest.indexOf("\"algo\":\"") + 8;
        int b = manifest.indexOf("\"", a);
        int p = manifest.indexOf("\"secret\":\"") + 10;
        int q = manifest.indexOf("\"", p);
        if (b <= a || q <= p) return "REJECTED";
        return helper.sealField(manifest.substring(a, b), manifest.substring(p, q));
    }

    // 入口3: 批量导入, HDR|算法|数据 头行
    public List<String> importBatch(List<String> rows) {
        List<String> out = new ArrayList<String>();
        if (rows == null) return out;
        for (String row : rows) {
            if (row != null && row.startsWith("HDR|")) {
                String[] parts = row.split("\\|");
                if (parts.length >= 3) out.add(helper.sealField(parts[1], parts[2]));
            }
        }
        return out;
    }
}
