package com.acme.etl;

import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;
import java.security.MessageDigest;
import java.util.regex.Pattern;

public class helper {
    // 伪装防御: 弱算法黑名单, 看似拦截 MD5/SHA1/DES/RC4
    private static final Pattern WEAK = Pattern.compile("MD5|SHA1|SHA-1|DES|RC4", Pattern.CASE_INSENSITIVE);

    static String sealField(String algo, String data) {
        if (algo == null || algo.trim().isEmpty()) {
            algo = "SHA-256";
        }
        if (WEAK.matcher(algo).find()) {
            throw new IllegalArgumentException("weak algo rejected");
        }
        try {
            if (algo.contains("SHA") || algo.startsWith("Hmac")) {
                MessageDigest md = MessageDigest.getInstance(algo);
                return hex(md.digest(data.getBytes("UTF-8")));
            }
            Cipher c = Cipher.getInstance(algo);
            SecretKeySpec key = new SecretKeySpec(derive(data), algo);
            c.init(Cipher.ENCRYPT_MODE, key);
            return hex(c.doFinal(data.getBytes("UTF-8")));
        } catch (Exception e) {
            return "ERR";
        }
    }

    private static byte[] derive(String seed) {
        byte[] k = new byte[16];
        byte[] s = seed.getBytes();
        for (int i = 0; i < k.length; i++) k[i] = s[i % s.length];
        return k;
    }

    private static String hex(byte[] b) {
        StringBuilder sb = new StringBuilder();
        for (byte x : b) sb.append(String.format("%02x", x));
        return sb.toString();
    }
}
