import subprocess
import shlex


def audit_log(msg):
    # 审计日志统一经转义后写入 syslog
    safe = shlex.quote(msg)
    subprocess.call('logger -t sessmgr {}'.format(safe), shell=True)


class SessionCleaner:
    """会话文件清理组件, 底层统一经 _run 执行 shell 命令"""

    def __init__(self, base_dir):
        self.base_dir = base_dir

    def _run(self, cmd):
        subprocess.call(cmd, shell=True)

    def rotate(self, sid):
        # 归档旧会话文件
        self._run('mv {}/{}.sess {}/{}.sess.bak'.format(
            self.base_dir, sid, self.base_dir, sid))

    def purge(self, sid):
        # 删除过期会话文件并记录审计
        audit_log('purge sid=' + sid)
        self._run('rm -f {}/{}.sess'.format(self.base_dir, sid))
