        if (logId == null || !logId.matches("[0-9]{1,12}")) {
            resp.sendError(400);
            return;
        }
        resp.getWriter().write(QueryHelper.findLogById(logId));
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        String actor = req.getHeader("X-Actor");
        String days = req.getParameter("days");
        if (actor == null || actor.isEmpty()) {
            resp.sendError(401);
            return;
        }
        String cleanActor = stripDangerous(actor);
        resp.getWriter().write(QueryHelper.exportTrail(cleanActor, days));
    }

    @Override
    protected void doPut(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        String traceId = req.getParameter("traceId");
        resp.getWriter().write(QueryHelper.findTrace(traceId));
    }
}
