package com.corp.audit;

import java.sql.*;

final class QueryHelper {

    private static Connection conn() throws SQLException {
        return DriverManager.getConnection(System.getenv("AUDIT_DB_URL"),
                System.getenv("AUDIT_DB_USER"), System.getenv("AUDIT_DB_PASS"));
    }

    static String findLogById(String logId) {
        String sql = "SELECT payload FROM audit_log WHERE id = " + logId;
        return runQuery(sql);
    }

    static String exportTrail(String actor, String days) {
        String sql = "SELECT op,detail FROM audit_log WHERE actor = '" + actor
                + "' AND retries < " + days + " ORDER BY id DESC";
        return runQuery(sql);
    }

    static String findTrace(String traceId) {
        try (PreparedStatement ps = conn().prepareStatement(
                "SELECT detail FROM audit_log WHERE trace_id = ?")) {
            ps.setString(1, traceId);
            ResultSet rs = ps.executeQuery();
            return rs.next() ? rs.getString(1) : "";
        } catch (SQLException e) {
            return "";
        }
    }

    private static String runQuery(String sql) {
        try (Statement st = conn().createStatement();
                ResultSet rs = st.executeQuery(sql)) {
            return rs.next() ? rs.getString(1) : "";
        } catch (SQLException e) {
            return "";
        }
    }
}
