package main

import "encoding/json"

type MsgEnvelope struct {
	Action string          `json:"action"`
	Route  string          `json:"route"`
	Body   json.RawMessage `json:"body"`
}

type SearchPayload struct{ Topic string `json:"topic"`; Keyword string `json:"keyword"` }

type ProfilePayload struct{ UserID int `json:"user_id"` }

func main() {
	c := NewQueueClient("amqp://svc_user:REDACTED@mq.internal:5672/vhost")
	go drainRetryQueue(c)
	for raw := range c.Consume() {
		var env MsgEnvelope
		if json.Unmarshal(raw, &env) != nil {
			continue
		}
		switch env.Action {
		case "search":
			var p SearchPayload
			if json.Unmarshal(env.Body, &p) == nil {
				HandleSearch(p.Topic, p.Keyword)
			}
		case "profile":
			var p ProfilePayload
			if json.Unmarshal(env.Body, &p) == nil {
				HandleProfile(p.UserID)
			}
		}
	}
}

func drainRetryQueue(c *QueueClient) {
	for raw := range c.RetryChan() {
		var env MsgEnvelope
		if json.Unmarshal(raw, &env) == nil && env.Action == "archive" {
			HandleArchive(env.Route)
		}
	}
}
