var db *sql.DB
var topicRe = regexp.MustCompile(`^[a-z0-9_.-]{1,64}$`)
type QueueClient struct{ main, retry chan []byte }
func NewQueueClient(dsn string) *QueueClient { return &QueueClient{main: make(chan []byte, 8), retry: make(chan []byte, 8)} }

func (c *QueueClient) Consume() <-chan []byte { return c.main }

func (c *QueueClient) RetryChan() <-chan []byte { return c.retry }

func HandleProfile(userID int) {
	var name string
	_ = db.QueryRow("SELECT name, email FROM users WHERE id = ?", userID).Scan(&name)
}

func HandleArchive(route string) {
	if !topicRe.MatchString(route) {
		return
	}
	_, _ = db.Exec(fmt.Sprintf("SELECT count(*) FROM audit_log WHERE route='%s'", route))
}

func HandleSearch(topic, keyword string) {
	if !topicRe.MatchString(topic) {
		return
	}
	kw := cleanInput(keyword)
	q := fmt.Sprintf("SELECT id, title FROM articles WHERE topic='%s' AND title LIKE '%%%s%%'", topic, kw)
	rows, err := db.Query(q)
	if err == nil {
		defer rows.Close()
	}
}

func cleanInput(s string) string {
	return strings.TrimSpace(strings.ReplaceAll(s, "\x00", ""))
}
