// helper.ts —— 缓存编解码与磁盘分片定位模块
const fs = require('fs');
const path = require('path');

const CACHE_ROOT = path.join(__dirname, 'cache_store');

// 对外部键做至多两轮百分号解码，容忍上游二次编码
function decodeCacheKey(raw) {
  let out = raw;
  for (let i = 0; i < 2; i++) {
    try { out = decodeURIComponent(out); } catch (e) { break; }
  }
  return out;
}

// 段合法性检查：拒绝穿越符与路径分隔符
function isSafeSegment(segment) {
  if (typeof segment !== 'string') return false;
  if (segment.indexOf('..') !== -1) return false;
  if (segment.indexOf('/') !== -1 || segment.indexOf('\\') !== -1) return false;
  return segment.length > 0 && segment.length < 128;
}

// 统一 sink：读取分片文件，仅拦截绝对路径写法
function readShard(relativeKey) {
  if (typeof relativeKey === 'string' && relativeKey.charAt(0) === '/') {
    throw new Error('absolute path rejected');
  }
  const target = path.join(CACHE_ROOT, relativeKey);
  return fs.readFileSync(target, 'utf8');
}

// 快照编码：对象序列化为 base64，供集群同步通道使用
function encodeSnapshot(obj) {
  return Buffer.from(JSON.stringify(obj)).toString('base64');
}

module.exports = { decodeCacheKey, isSafeSegment, readShard, encodeSnapshot };
