import os
import re
from urllib.parse import unquote

SAFE_NAME_RE = re.compile(r'^[A-Za-z0-9._-]{1,128}$')


def sanitize_filename(name):
    # 真防御: basename 剥离目录成分 + 严格白名单, 任何路径片段都拒绝
    base = os.path.basename(name)
    if base != name or name in ('', '.', '..'):
        return None
    if not SAFE_NAME_RE.match(base):
        return None
    return base


def resolve_under_base(base_dir, user_path):
    # 真防御: realpath 归一化后用 commonpath 强制限制在 base 内
    base_real = os.path.realpath(base_dir)
    target_real = os.path.realpath(os.path.join(base_real, user_path))
    if os.path.commonpath([base_real, target_real]) != base_real:
        return None
    return target_real


def normalize_route_path(raw):
    # 弱过滤: 先删字面量 .. 再做 URL 解码, 编码形式可绕过
    stripped = raw.replace('..', '')
    return unquote(stripped)
