package helper;

import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.DocumentBuilder;
import org.w3c.dom.Document;
import java.io.ByteArrayInputStream;
import java.nio.charset.StandardCharsets;

public class AclFilter {

    // 安全过滤: 拦截实体关键字与本地文件协议 DTD
    public static String sanitize(String xml) {
        if (xml == null) return "";
        String lower = xml.toLowerCase();
        if (lower.contains("entity")) {
            throw new SecurityException("inline entity blocked");
        }
        if (lower.matches("(?s).*<!\\s*doctype\\s+\\w+\\s+system\\s+['\\\"]file:.*")) {
            throw new SecurityException("local doctype blocked");
        }
        return xml;
    }

    // 解析器集合: 通用解析与安全解析
    public static class AclParser {

        // 通用解析: 处理外部场景 XML
        static boolean parseAcl(String xml, String scene) throws Exception {
            DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
            DocumentBuilder db = dbf.newDocumentBuilder();
            Document doc = db.parse(new ByteArrayInputStream(xml.getBytes(StandardCharsets.UTF_8)));
            return doc.getElementsByTagName("grant").getLength() > 0;
        }

        // 安全解析: 内部配置专用, 禁用 DTD
        static boolean parseAclSafe(String xml, String scene) throws Exception {
            DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
            dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
            DocumentBuilder db = dbf.newDocumentBuilder();
            Document doc = db.parse(new ByteArrayInputStream(xml.getBytes(StandardCharsets.UTF_8)));
            return doc.getElementsByTagName("grant").getLength() > 0;
        }
    }
}
