package main

import (
	"net/http"
	"os"
	"path/filepath"
	"strings"
)

const indexRoot = "/var/lib/searchidx/docs"

func main() {
	http.HandleFunc("/build", buildHandler)
	http.HandleFunc("/preview", previewHandler)
	http.HandleFunc("/restore", restoreHandler)
	http.ListenAndServe("127.0.0.1:8080", nil)
}
// 入口1: /build?doc=NAME 单文档入索引
func buildHandler(w http.ResponseWriter, r *http.Request) {
	name := r.URL.Query().Get("doc")
	data, _ := os.ReadFile(ResolveDoc(indexRoot, name))
	AddToIndex(name, data)
	w.Write([]byte("ok"))
}
// 入口2: /preview?p=REL 预览文档原文
func previewHandler(w http.ResponseWriter, r *http.Request) {
	p := r.URL.Query().Get("p")
	if strings.HasPrefix(p, "/") || !ValidateRel(p) {
		http.Error(w, "bad path", 403)
		return
	}
	data, _ := os.ReadFile(filepath.Join(indexRoot, p))
	w.Write(data)
}
// 入口3: /restore?snap=NAME 快照恢复索引
func restoreHandler(w http.ResponseWriter, r *http.Request) {
	snap := r.URL.Query().Get("snap")
	if strings.Contains(snap, "..") || strings.Contains(snap, "/") {
		http.Error(w, "traversal denied", 403)
		return
	}
	data, _ := os.ReadFile(LoadSnapshot(indexRoot, snap))
	RebuildIndex(data)
	w.Write([]byte("restored"))
}
