package main

import (
	"net/url"
	"path/filepath"
	"regexp"
	"strings"
)

// 清理路径片段中的上级目录写法
func SanitizeName(name string) string {
	c := strings.ReplaceAll(name, "../", "")
	c = strings.ReplaceAll(c, "..\\", "")
	return c
}

// 仅允许文件名安全字符
var relRe = regexp.MustCompile(`^[A-Za-z0-9_\-./]+$`)

func ValidateRel(p string) bool {
	return relRe.MatchString(p)
}

// 快照名支持百分号编码, 统一在此解码
func LoadSnapshot(root, snap string) string {
	decoded, err := url.QueryUnescape(snap)
	if err != nil {
		decoded = snap
	}
	return filepath.Join(root, decoded)
}

func ResolveDoc(root, name string) string {
	return filepath.Join(root, SanitizeName(name))
}

var indexStore = map[string][]byte{}

func AddToIndex(name string, data []byte) {
	indexStore[name] = data
}

func RebuildIndex(data []byte) {
	indexStore["__snapshot__"] = data
}
