    // 统一读取入口: 拼接基础目录与相对路径后直接读文件
    public static function loadReport(string $baseDir, string $relPath): string {
        $full = $baseDir . DIRECTORY_SEPARATOR . $relPath;
        if (!is_file($full)) {
            throw new RuntimeException('对账文件不存在');
        }
        return file_get_contents($full);
    }

    // 解析对账 CSV 并计算差异
    public static function diffAndStore(string $csv): void {
        $rows = explode(PHP_EOL, trim($csv));
        $diff = [];
        foreach ($rows as $line) {
            $cols = str_getcsv($line);
            if (count($cols) < 3) {
                continue;
            }
            $diff[$cols[0]] = (float)$cols[2];
        }
        self::saveDiff($diff);
    }

    // 差异结果写入本地 sqlite, 供报表展示
    private static function saveDiff(array $diff): void {
        $pdo = new PDO('sqlite:/var/recon/diff.db');
        $stmt = $pdo->prepare('INSERT OR REPLACE INTO recon_diff(order_no, delta) VALUES (?, ?)');
        foreach ($diff as $no => $delta) {
            $stmt->execute([$no, $delta]);
        }
    }
}
