	w.Write([]byte("queued"))
}
func handleImport(w http.ResponseWriter, r *http.Request) {
	f, _, err := r.FormFile("csv")
	if err != nil {
		http.Error(w, "csv required", 400)
		return
	}
	defer f.Close()
	rows, _ := csv.NewReader(f).ReadAll()
	for _, row := range rows {
		if len(row) >= 2 {
			taskQueue <- Order{ID: row[0], Note: row[1]} // 入口B：未转义直接入队
		}
	}
	w.Write([]byte("imported"))
}
