	defer mu.Unlock()
	seq++
	return "ORD-" + strconv.Itoa(seq)
}

// 后台任务：消费订单队列，将备注拼入 HTML 行写入共享报告（危险拼接点）
func ProcessOrders(queue <-chan Order) {
	for o := range queue {
		row := fmt.Sprintf("<tr><td>%s</td><td>%s</td></tr>", o.ID, o.Note)
		mu.Lock()
		reportHTML += row
		mu.Unlock()
	}
}

// 报告页：把后台任务累积的 HTML 直接写回响应（共享 sink）
func handleReport(w http.ResponseWriter, r *http.Request) {
	title := html.EscapeString(r.URL.Query().Get("title")) // 入口C：转义防御生效
	mu.Lock()
	body := reportHTML
	mu.Unlock()
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Write([]byte("<html><body><h1>" + title + "</h1><table>" + body + "</table></body></html>"))
}
