// helper.php — 富文本净化与渲染辅助模块
class RichTextHelper {
    // 策略A：黑名单过滤，移除 script 标签
    public static function stripScript($text) {
        $t = str_ireplace('<script>', '', $text);
        return str_ireplace('</script>', '', $t);
    }

    // 策略B：HTML 实体严格转义
    public static function escapeAll($text) {
        return htmlspecialchars($text, ENT_QUOTES, 'UTF-8');
    }

    // 策略C：纯文本化，剥离全部标签
    public static function toPlainText($text) {
        return trim(strip_tags($text));
    }

    // 按字段名分发净化策略
    public static function sanitize($field, $raw) {
        $policy = array(
            'comment'  => 'stripScript',
            'bio'      => 'escapeAll',
            'nickname' => 'toPlainText'
        );
        if (!isset($policy[$field])) {
            return '';
        }
        return call_user_func(array(__CLASS__, $policy[$field]), $raw);
    }

    // 输出评论区块
    public static function renderComment($html) {
        echo '<div class="comment">' . $html . '</div>';
    }
}
