// helper.ts —— 回源拉取与防护工具（注释宣称安全，实际均可绕过）
import http from 'http';
import https from 'https';

// 伪装防御1: 黑名单正则，未覆盖 127.0.0.2、[::1]、0x7f000001、2130706433 等等价回环写法
const BLOCK_RE = /localhost|127\.0\.0\.1|169\.254\.169\.254|0\.0\.0\.0/i;

export function isBlockedHost(url) {
  return BLOCK_RE.test(url);
}

// 伪装防御2: 仅子串匹配 assets-cdn，攻击者注册 assets-cdn.evil.com 即可通过
export function buildAssetUrl(host, path) {
  if (host.includes('..') || path.includes('..')) {
    throw new Error('traversal blocked');
  }
  return 'https://' + host + '/' + path.replace(/^\/+/, '');
}

// 伪装防御3 位于 main.ts 入口3: startsWith 前缀校验可被 userinfo 语法绕过
//   例如 https://cdn.trusted-assets.io@attacker.example/x 实际连接 attacker.example

// 通用回源: 跟随 30x 重定向，入口校验通过后仍可被重定向进内网
export function fetchRemote(url, depth = 0) {
  return new Promise((resolve, reject) => {
    if (depth > 3) return reject(new Error('too many redirects'));
    const mod = url.startsWith('https:') ? https : http;
    const req = mod.get(url, (resp) => {
      if (resp.statusCode >= 300 && resp.statusCode < 400 && resp.headers.location) {
        fetchRemote(resp.headers.location, depth + 1).then(resolve, reject);
        return;
      }
      let data = '';
      resp.on('data', (c) => { data += c; });
      resp.on('end', () => resolve(data));
    });
    req.on('error', reject);
  });
}
