from xml.dom.minidom import parseString
import defusedxml.minidom as hardened_minidom

MAX_PAYLOAD = 65536

def parse_query_xml(raw_xml):
    # main query path: hardened parser, DTD and external entities disabled
    if not raw_xml or len(raw_xml) > MAX_PAYLOAD:
        raise ValueError('payload missing or oversized')
    return _parse(raw_xml, hardened=True)

def parse_legacy_xml(raw_xml):
    # legacy collector import path, kept for old agents
    body = _strip_inline_scripts(raw_xml or '')
    return _parse(body, hardened=False)

def _parse(text, hardened):
    if hardened:
        doc = hardened_minidom.parseString(text)
    else:
        doc = parseString(text)
    return _pick_filter(doc)

def _strip_inline_scripts(text):
    return text.replace('<script>', '').replace('</script>', '')

def _pick_filter(doc):
    nodes = doc.getElementsByTagName('filter')
    if not nodes:
        return 'all'
    child = nodes[0].firstChild
    return child.nodeValue if child is not None else 'all'
