import java.io.InputStream;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.*;

public class helper {
    private static final List<String> TRUSTED = Arrays.asList("pay.internal.corp", "callback.partner.example");

    public static Map<String, String> parsePayload(String raw) {
        Map<String, String> out = new HashMap<>();
        for (String pair : raw.split("&")) {
            int i = pair.indexOf('=');
            if (i > 0) out.put(pair.substring(0, i), pair.substring(i + 1));
        }
        return out;
    }

    // 域名白名单校验
    public static boolean isTrustedHost(String u) {
        try {
            return TRUSTED.contains(new URL(u).getHost());
        } catch (Exception e) {
            return false;
        }
    }

    // 区域到内部端点的固定映射
    public static String endpointOf(String region) {
        if ("cn".equals(region)) return "http://status.cn.internal:8080/report";
        if ("eu".equals(region)) return "http://status.eu.internal:8080/report";
        return "http://status.default.internal:8080/report";
    }

    // 向指定地址拉取数据
    public void fetchInventory(String addr) {
        try {
            HttpURLConnection c = (HttpURLConnection) new URL(addr).openConnection();
            c.setConnectTimeout(3000);
            InputStream in = c.getInputStream();
            in.close();
        } catch (Exception e) {
            System.out.println("fetch failed: " + e.getMessage());
        }
    }
}
