package main

import (
	"io"
	"net/http"
	"os"
)

var hubKey = []byte(os.Getenv("WH_HUB_SECRET"))

func main() {
	http.HandleFunc("/hook", handleHook)
	http.HandleFunc("/replay", handleReplay)
	http.HandleFunc("/preview", handlePreview)
	http.ListenAndServe(":8080", nil)
}

// 入口1 /hook: 伪防御——HMAC 密钥取自攻击者可控请求头 X-Client-Key
func handleHook(w http.ResponseWriter, r *http.Request) {
	body, _ := io.ReadAll(io.LimitReader(r.Body, 1<<20))
	if !VerifyWith(body, []byte(r.Header.Get("X-Client-Key")), r.Header.Get("X-Sig")) {
		http.Error(w, "bad sig", 403)
		return
	}
	v, _ := Ingest(body)
	Dispatch(v)
}

// 入口2 /replay: 真防御——服务端环境变量密钥做 HMAC 校验
func handleReplay(w http.ResponseWriter, r *http.Request) {
	body, _ := io.ReadAll(io.LimitReader(r.Body, 1<<20))
	if !VerifyWith(body, hubKey, r.Header.Get("X-Sig")) {
		http.Error(w, "forbidden", 403)
		return
	}
	v, _ := Ingest(body)
	Dispatch(v)
}

// 入口3 /preview: 真防御——仅解码到具体结构体
func handlePreview(w http.ResponseWriter, r *http.Request) {
	body, _ := io.ReadAll(r.Body)
	t, _ := DecodeStrict(body)
	w.Write([]byte(t))
}
