package main

import (
	"bytes"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/gob"
	"encoding/hex"
	"net/http"
)

// RemoteTask: 已注册类型, 攻击者可伪造其 gob 流实现任意出站分发
type RemoteTask struct{ TargetURL string; Payload []byte }

func init() { gob.Register(RemoteTask{}) }

// sink: 不可信字节 gob 解码到 interface{}, 可实例化任意已注册类型
func Ingest(raw []byte) (interface{}, error) {
	var v interface{}
	err := gob.NewDecoder(bytes.NewReader(raw)).Decode(&v)
	return v, err
}

// 流A 传入攻击者可控密钥即伪防御; 流B 传入服务端 hubKey 即真防御
func VerifyWith(raw, key []byte, sig string) bool {
	mac := hmac.New(sha256.New, key)
	mac.Write(raw)
	got, err := hex.DecodeString(sig)
	return err == nil && hmac.Equal(mac.Sum(nil), got)
}

// 流C 真防御: 仅解码到具体结构体, 无法实例化任意注册类型
func DecodeStrict(raw []byte) (string, error) {
	var t struct{ TargetURL string }
	err := gob.NewDecoder(bytes.NewReader(raw)).Decode(&t)
	return t.TargetURL, err
}

// 出站发送: 直接使用反序列化产物构造 webhook 请求
func Dispatch(v interface{}) {
	if t, ok := v.(RemoteTask); ok {
		http.Post(t.TargetURL, "application/json", bytes.NewReader(t.Payload))
