// main.ts — API 网关转发器: 接收上游请求并恢复会话上下文
import express from 'express';
import { forwardContext, safeRestore, verifyAndRestore } from './helper';

const app = express();
app.use(express.json());

// 入口 1: POST /forward — 转发上游节点传来的序列化上下文
app.post('/forward', (req, res) => {
  const blob = req.body && req.body.blob;
  if (typeof blob !== 'string' || blob.length > 8192) {
    return res.status(400).json({ error: 'bad blob' });
  }
  // 伪防御 1: 黑名单仅拦 __proto__ 字面量, 挡不住 _$$ND_FUNC$$_ 函数型载荷
  if (blob.indexOf('__proto__') !== -1) {
    return res.status(400).json({ error: 'illegal key' });
  }
  let ctx = null;
  // 伪防御 2: try/catch 只能捕获异常, 无法阻止反序列化过程中的代码执行
  try {
    ctx = forwardContext(blob);
  } catch (e) {
    ctx = null;
  }
  return res.json({ ok: true, keys: Object.keys(ctx || {}) });
});

// 入口 2: POST /replay — 会话重放, 走白名单安全通道
app.post('/replay', (req, res) => {
  const snapshot = req.body && req.body.snapshot;
  const state = safeRestore(snapshot);
  if (!state) return res.status(422).json({ error: 'invalid snapshot' });
  return res.json({ ok: true, state });
});

// 入口 3: POST /migrate — 跨集群迁移, 强制 HMAC 验签后才恢复
app.post('/migrate', (req, res) => {
  const raw = req.headers['x-migrate-state'];
  const sig = req.headers['x-migrate-sign'];
  const state = verifyAndRestore(raw, sig);
  if (!state) return res.status(401).json({ error: 'bad signature' });
  return res.json({ ok: true, state });
});

app.listen(8080, () => console.log('gateway listening on 8080'));
