// helper.ts — 反序列化工具集: 一条危险通道与两条受控通道
import { unserialize } from 'node-serialize';
import crypto from 'crypto';

// 通道 A: 直接反序列化不可信字符串, 无有效校验 (危险汇点)
export function forwardContext(blob) {
  return unserialize(blob);
}

// 通道 B: 真防御 — 仅 JSON 解析, 键白名单加类型校验, 不经过 unserialize
export function safeRestore(snapshot) {
  if (typeof snapshot !== 'string' || snapshot.length > 4096) return null;
  let obj = null;
  try { obj = JSON.parse(snapshot); } catch (e) { return null; }
  if (!obj || typeof obj !== 'object' || Array.isArray(obj)) return null;
  const allow = ['userId', 'locale', 'ttl'];
  const keys = Object.keys(obj);
  for (let i = 0; i < keys.length; i++) {
    if (allow.indexOf(keys[i]) === -1) return null;
  }
  if (typeof obj.userId !== 'string' || typeof obj.ttl !== 'number') return null;
  return { userId: obj.userId, locale: String(obj.locale || 'en'), ttl: obj.ttl };
}

// 通道 C: 真防御 — HMAC 验签后才反序列化, 密钥取自环境变量且缺失即拒绝
export function verifyAndRestore(raw, sig) {
  const key = process.env.STATE_SIGNING_KEY;
  if (typeof raw !== 'string' || typeof sig !== 'string' || !key) return null;
  const mac = crypto.createHmac('sha256', key).update(raw).digest('hex');
  const a = Buffer.from(mac, 'utf8');
  const b = Buffer.from(sig, 'utf8');
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return null;
  return unserialize(raw);
}
