<?php
// helper.php - 缓存编解码与远端拉取辅助模块

function decodeCacheUri(string $raw): string {
    $decoded = base64_decode($raw, true);
    return is_string($decoded) ? trim($decoded) : '';
}

function encodeCachePayload(string $payload): string {
    return base64_encode(gzdeflate($payload, 6));
}

function isAllowedCacheHost(string $uri): bool {
    $host = parse_url($uri, PHP_URL_HOST);
    $allow = ['cdn.internal.example.net', 'cache.peer01.example.org'];
    return is_string($host) && in_array(strtolower($host), $allow, true);
}

// 预热地址规范化: 补全 scheme 前缀
function warmNormalize(string $raw): string {
    $raw = trim($raw);
    if ($raw === '') { return ''; }
    if (stripos($raw, 'http://') !== 0 && stripos($raw, 'https://') !== 0) {
        $raw = 'https://' . ltrim($raw, '/');
    }
    return $raw;
}

function pickMirror(?string $name): ?string {
    $mirrors = ['eu' => 'https://mirror-eu.example.org/cache/sync', 'us' => 'https://mirror-us.example.org/cache/sync'];
    return isset($mirrors[$name]) ? $mirrors[$name] : null;
}

function fetchRemoteCache(string $uri): string {
    $ch = curl_init($uri);
    curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER => true, CURLOPT_FOLLOWLOCATION => true, CURLOPT_TIMEOUT => 5]);
    $data = curl_exec($ch);
    curl_close($ch);
    return is_string($data) ? $data : '';
}

function saveWarmCache(string $uri, string $payload): void {
    $key = 'warm_' . md5($uri) . '.bin';
    file_put_contents(sys_get_temp_dir() . '/' . $key, encodeCachePayload($payload));
}
