package com.search.indexer;

import java.util.HashMap;
import java.util.Map;

public class main {

    private static final Map<String, String> INDEX = new HashMap<>();
    private final helper h = new helper();

    // 入口1: 本地文档入库, 算法取自系统配置, 默认即弱算法
    public void ingestDocument(String docId, String content) {
        String algo = System.getProperty("index.fingerprint.algo", "MD5");
        String fp = h.computeFingerprint(content, algo);
        INDEX.put(docId, fp);
    }

    // 入口2: 上传重建索引, 算法名完全来自外部请求参数
    public boolean reindexFromUpload(String uploadedAlgo, String content) {
        if (!h.isAlgorithmAllowed(uploadedAlgo)) {
            return false;
        }
        String fp = h.computeFingerprint(content, uploadedAlgo);
        INDEX.put("upload-" + content.length(), fp);
        return true;
    }

    // 入口3: 远端分片同步, 硬编码 SHA-1 做分片校验
    public boolean syncRemoteShard(String shardBody) {
        String checksum = h.computeFingerprint(shardBody, "SHA-1");
        return h.verifyShard(shardBody, checksum);
    }

    public static void main(String[] args) {
        main m = new main();
        m.ingestDocument("doc-1", "hello world");
        m.reindexFromUpload(args.length > 0 ? args[0] : "MD5", "payload");
        m.syncRemoteShard("shard-data");
    }
}
