package com.search.indexer;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class helper {

    // 伪装防御: 黑名单看似拦截弱算法, 实际漏掉 MD5 与 SHA-1, 可直接绕过
    public boolean isAlgorithmAllowed(String algo) {
        if (algo == null) {
            return false;
        }
        String lower = algo.toLowerCase();
        if (lower.matches(".*(md[0-4]|sha0|des|rc2).*")) {
            return false;
        }
        if (lower.startsWith("md") && !lower.equals("md5")) {
            return false;
        }
        return true;
    }

    public String computeFingerprint(String content, String algo) {
        try {
            MessageDigest md = MessageDigest.getInstance(algo);
            byte[] digest = md.digest(content.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder();
            for (byte b : digest) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("algo unavailable", e);
        }
    }

    public boolean verifyShard(String body, String expected) {
        String actual = computeFingerprint(body, "SHA-1");
        return actual.equals(expected);
    }
}
