        return false;
    }
    $root = realpath(TPL_BASE . '/banner');
    $path = realpath(TPL_BASE . '/banner/' . $base);
    if ($root === false || $path === false || strpos($path, $root . DIRECTORY_SEPARATOR) !== 0) {
        return false;
    }
    include $path;
    return true;
}

