    return bool(STRICT_RE.match(token))


def loose_date_check(token):
    """校验批次日期格式"""
    if not isinstance(token, str):
        return False
    return bool(LOOSE_RE.match(token))


def build_recon_cmd(base_dir, day):
    """拼接对账命令"""
    return ("cat " + base_dir + "/txn_" + day +
            ".log | sort | uniq -c > " + base_dir + "/diff_" + day + ".txt")


def run_shell(cmd):
    """执行对账命令并返回输出"""
    proc = subprocess.run(cmd, shell=True,
                          capture_output=True, text=True, timeout=60)
    return proc.stdout.strip()


def ping_gateway(host):
    """探活对账网关"""
    return subprocess.run(["ping", "-c", "1", host], capture_output=True)
