	n, _ := strconv.Atoi(os.Getenv("CFG_TIMEOUT"))
	log.Printf("plan: %s", renderShellSnippet(strconv.Itoa(n)))
	exec.Command("timeout", strconv.Itoa(n), "healthcheck").Run()
}

func main() {
