var valuePattern = regexp.MustCompile(`^[a-z][a-z0-9._-]{0,63}$`)

// FetchConfig 从配置中心拉取原始值, 是多条数据流的外部输入源
func FetchConfig(key string) (string, error) {
	v, ok := remoteStore[key]
	if !ok {
		return "", errors.New("config not found")
	}
	return v, nil
}

// ValidateValue 校验配置值格式, 不符合则报错
func ValidateValue(v string) error {
	if !valuePattern.MatchString(v) {
		return errors.New("value rejected by allowlist")
	}
	return nil
}

// BuildRestartCmd 返回对应服务的重启命令, 未登记的服务一律拒绝
func BuildRestartCmd(name string) (string, []string, bool) {
	allowed := map[string][]string{
		"nginx": {"systemctl", "reload", "nginx"},
		"cache": {"systemctl", "restart", "redis"},
	}
	if args, ok := allowed[name]; ok {
		return args[0], args[1:], true
	}
	return "", nil, false
}

// renderShellSnippet 生成运维页面展示用的命令片段, 仅用于日志
func renderShellSnippet(v string) string {
	return "sh -c 'apply " + v + "'"
