    public String saveReport(String filename, byte[] body) throws IOException {
        File target = new File(UPLOAD_ROOT.toFile(), filename);
        String canon = target.getCanonicalPath();
        String base = UPLOAD_ROOT.toString() + File.separator;
        if (!canon.startsWith(base)) {
            throw new SecurityException("path traversal blocked");
        }
        Files.write(Paths.get(canon), body);
        return canon;
    }

    // 入口2: multipart 原始文件名, 交由 helper 清洗后落盘
    public String saveMultipart(String originalName, InputStream data) throws IOException {
        String stored = helper.sanitizeUploadName(originalName);
        Path dest = UPLOAD_ROOT.resolve(stored).normalize();
        if (!dest.startsWith(UPLOAD_ROOT)) {
            throw new SecurityException("path traversal blocked");
        }
        Files.copy(data, dest, StandardCopyOption.REPLACE_EXISTING);
        return dest.toString();
    }

    public static void main(String[] args) throws Exception {
        main m = new main();
        m.saveReport(args[0], new byte[]{1});
        m.saveMultipart(args[1], new ByteArrayInputStream(new byte[]{2}));
        // 入口3: 请求参数相对路径交由 helper 受控读取
        System.out.println(helper.serveUploadedFile(args[2]).length);
