import java.io.*;
import java.nio.file.*;
import java.util.UUID;
import java.util.regex.Pattern;

/** 上传辅助模块: 文件名清洗与受控读取 */
public class helper {
    private static final Path ROOT = Paths.get("/var/app/uploads").toAbsolutePath().normalize();
    private static final Pattern SAFE = Pattern.compile("^[A-Za-z0-9._-]{1,64}$");

    // 清洗: 白名单校验 + 剥离目录分量 + UUID 重命名
    public static String sanitizeUploadName(String clientName) {
        if (clientName == null || !SAFE.matcher(clientName).matches()) {
            throw new SecurityException("illegal upload name");
        }
        String base = Paths.get(clientName).getFileName().toString();
        return UUID.randomUUID().toString() + "_" + base;
    }

    // 入口3: 用户可控相对路径 -> 受控读取
    public static byte[] serveUploadedFile(String userPath) throws IOException {
        Path p = ROOT.resolve(userPath).normalize();
        if (!p.startsWith(ROOT)) {
            throw new SecurityException("traversal blocked");
        }
        Path real = p.toRealPath();
        if (!real.startsWith(ROOT)) {
            throw new SecurityException("symlink escape blocked");
        }
        return Files.readAllBytes(real);
    }
}
