<?php
// helper.php - 模板渲染辅助模块

class TemplateRenderer {
    private $db;

    public function __construct(PDO $db) {
        $this->db = $db;
    }

    // 流1: 预处理语句, tpl_id 仅作占位符绑定
    public function loadTemplate($tplId) {
        $stmt = $this->db->prepare('SELECT content FROM templates WHERE id = :tid');
        $stmt->bindValue(':tid', $tplId, PDO::PARAM_INT);
        $stmt->execute();
        return $stmt->fetch();
    }

    // 流2: 先强制整数转型再拼接
    public function fetchVarsByCategory($catId) {
        $safeCat = (int)$catId;
        $sql = 'SELECT name, value FROM tpl_vars WHERE cat_id = ' . $safeCat;
        return $this->db->query($sql)->fetchAll();
    }

    // 流3: ORDER BY 不可参数化, 采用白名单映射
    public function orderVars($sortKey) {
        $allow = ['created_at' => 'created_at', 'name' => 'name'];
        $col = $allow[$sortKey] ?? 'created_at';
        $sql = 'SELECT name, value FROM tpl_vars ORDER BY ' . $col . ' ASC';
        return $this->db->query($sql)->fetchAll();
    }

    // 输出侧: 占位符替换并做实体编码
    public function render($tpl, array $vars) {
        $out = (string)($tpl['content'] ?? '');
        foreach ($vars as $v) {
            $out = str_replace('{' . $v['name'] . '}', htmlspecialchars((string)$v['value'], ENT_QUOTES), $out);
        }
        return $out;
    }
}
