    $blob = (count($argv) < 3) ? false : base64_decode($argv[1], true);
    if ($blob === false || !verify_payload_sig($blob, $argv[2])) {
        return 'rejected: bad payload or signature';
    }
    $task = safe_unserialize($blob);
