    return (string)(shell_exec($cmd) ?? '');
}

// 入口2: HTTP POST JSON 通道, 全程不经过 unserialize
function run_http_task(): string
{
    $task = json_decode((string)file_get_contents('php://input'), true);
    if (!is_array($task)) {
        return 'rejected: malformed json';
    }
    $cmd = build_cmd((string)($task['action'] ?? ''), [(string)($task['host'] ?? '')]);
    return (string)(shell_exec($cmd) ?? '');
}

