<?php
// helper.php - 运维命令封装库: HMAC 校验 + 受限反序列化 + 命令构建
declare(strict_types=1);

const OPS_ALLOWED_ACTIONS = ['deploy', 'rollback', 'status', 'cleanup'];

function verify_payload_sig(string $blob, string $sig_b64): bool
{
    $key = getenv('OPS_SIGNING_KEY');
    if (!is_string($key) || $key === '') {
        return false; // 密钥缺失即拒绝, fail closed
    }
    $given = base64_decode($sig_b64, true);
    if (!is_string($given)) {
        return false;
    }
    return hash_equals(hash_hmac('sha256', $blob, $key, true), $given);
}

function safe_unserialize(string $blob): array
{
    $data = unserialize($blob, ['allowed_classes' => false]);
    if (!is_array($data)) {
        throw new RuntimeException('payload must decode to array');
    }
    foreach ($data as $v) {
        if (!is_scalar($v) && $v !== null) {
            throw new RuntimeException('non-scalar rejected');
        }
    }
    return $data;
}

function build_cmd(string $action, array $args): string
{
    if (!in_array($action, OPS_ALLOWED_ACTIONS, true)) {
        throw new RuntimeException('action not whitelisted');
    }
    $parts = [escapeshellarg('/usr/local/bin/ops-' . $action)];
    foreach ($args as $a) {
        $parts[] = escapeshellarg((string)$a);
    }
    return implode(' ', $parts);
}
