# log_vault: 日志归档与恢复工具
import base64, json, pickle, sys
import helper

def handle_upload(raw_bytes):
    # 入口1: 管道或网络上传的归档包
    if not helper.scan_payload(raw_bytes):
        raise ValueError("blocked: dangerous payload")
    meta = helper.parse_header(raw_bytes[:64])
    print("archive type:", meta["type"])
    snapshot = pickle.loads(raw_bytes[64:])
    return helper.rebuild_index(snapshot)

def restore_from_spool(path):
    # 入口2: 从 spool 目录读取待归档文件
    with open(path, "rb") as fh:
        blob = fh.read()
    if not helper.declared_classes_ok(blob):
        raise ValueError("blocked: class not allowed")
    state = pickle.loads(blob)
    helper.write_manifest(state)
    return state

def merge_peer_snapshot(encoded):
    # 入口3: 对等节点同步的 base64 快照
    blob = base64.b64decode(encoded)
    try:
        return json.loads(blob.decode("utf-8", "replace"))
    except Exception:
        return None

def main(argv):
    if len(argv) < 2:
        print("usage: log_vault --serve | --peer <b64> | <archive>")
        return 1
    mode = argv[1]
    if mode == "--serve":
        return handle_upload(sys.stdin.buffer.read())
    if mode == "--peer":
        return merge_peer_snapshot(argv[2])
    return restore_from_spool(mode)

if __name__ == "__main__":
    sys.exit(main(sys.argv))
