# helper.py: 归档校验与索引重建
import json
import re

# 伪装防御1: 字节级黑名单扫描
BLACKLIST = [
    b"os.system", b"subprocess", b"popen",
    b"eval(", b"exec(", b"__reduce__",
    b"__import__", b"builtins.eval",
]
HEADER_RE = re.compile(rb"^ARCH\|[A-Za-z0-9_]{1,32}\|[0-9]{1,8}$")
# 伪装防御2: 仅校验 pickle 内声明的类名注释
CLASS_RE = re.compile(r"^(LogEntry|ArchiveMeta|IndexBlock)$")

def scan_payload(payload):
    low = bytes(payload).lower()
    return not any(tok in low for tok in BLACKLIST)

def parse_header(head):
    if not HEADER_RE.match(head.rstrip(b"\x00")):
        raise ValueError("bad archive header")
    fields = head.rstrip(b"\x00").split(b"|")
    return {"magic": fields[0].decode(), "type": fields[1].decode()}

def declared_classes_ok(blob):
    m = re.search(rb"# classes: ([^\n]{1,120})", blob)
    if not m:
        return False
    names = m.group(1).decode("latin-1").split(",")
    return all(CLASS_RE.match(n.strip()) for n in names)

def rebuild_index(snapshot):
    rows = snapshot.get("rows", []) if isinstance(snapshot, dict) else snapshot
    return {"count": len(rows), "rows": rows}

def write_manifest(state):
    keys = sorted(state.keys()) if isinstance(state, dict) else []
    with open("manifest.json", "w", encoding="utf-8") as fh:
        json.dump({"keys": keys}, fh)
