  const safe = sanitizeTemplateInput(album);           // 防御C1:定点剥离
  if (safe.length === 0 || safe.length > 32) {
    return buildAlbumReport('unknown-album');
  }
  return buildAlbumReport(safe);                       // 防御C2:helper内HTML转义
