// helper.ts —— 图片流水线模板清洗与安全渲染(无表达式求值)
const TOKEN_RE = /\{\{|\}\}|\$\{|<%|%>|\{%|%\}|`/g;

// 防御A1/C1:定点(fixpoint)剥离,循环删除直至稳定
// 单轮删除可因重组产生新定界符(如{}}{变{{),须循环至不再变化方可根除
export function sanitizeTemplateInput(input: string): string {
  let out = String(input);
  let prev = '';
  while (out !== prev) {
    prev = out;
    out = out.replace(TOKEN_RE, '');
  }
  return out;
}

// 防御A2/B2/C2:HTML实体转义
export function escapeHtml(value: string): string {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

// 渲染器:仅字面替换{{键名}}占位符,值强制转义;无eval、new Function与表达式求值
export function renderTemplate(template: string, vars: Record<string, string>): string {
  return template.replace(/\{\{(\w+)\}\}/g, (_m: string, key: string) =>
    Object.prototype.hasOwnProperty.call(vars, key) ? escapeHtml(vars[key]) : ''
  );
}

export function renderWatermarkSvg(template: string, vars: Record<string, string>): string {
  return renderTemplate(template, vars);
}

export function renderCaptionOverlay(base: string, caption: string): string {
  return renderTemplate(base, { PLACEHOLDER: caption });
}

export function buildAlbumReport(albumName: string): string {
  const REPORT_TPL = '<report><album>{{album}}</album><images>{{count}}</images></report>';
  return renderTemplate(REPORT_TPL, { album: albumName, count: '24' });
}
