import freemarker.template.Configuration;
import freemarker.template.Template;
import freemarker.template.TemplateClassResolver;
import java.io.StringReader;
import java.io.StringWriter;
import java.util.HashMap;
import java.util.Map;
import java.util.regex.Pattern;

public class helper {
    private static final Pattern PLAIN = Pattern.compile("^[A-Za-z0-9._-]{0,64}$");
    private static final String[] FTL_MARKS = {"${", "#{", "<#", "[#", "<@", "[@", "[="};
    private static final String NOTIFY_TMPL = "Dear ${name}, your quota is renewed.";

    private static Configuration cfg() {
        Configuration c = new Configuration(Configuration.VERSION_2_3_31);
        c.setNewBuiltinClassResolver(TemplateClassResolver.SAFER_RESOLVER);
        c.setAPIBuiltinEnabled(false);
        return c;
    }
    // 流1: 远程横幅直接作为模板源, 白名单拒绝一切模板元字符
    static void renderBanner(String v) throws Exception {
        if (v == null || !PLAIN.matcher(v).matches()) { throw new IllegalArgumentException("bad banner"); }
        render(v, "banner", v);
    }
    // 流2: 固定模板, 值仅经数据模型注入, 不进入模板源
    static void renderNotification(String name) throws Exception {
        render(NOTIFY_TMPL, "name", name);
    }
    // 流3: 推送值直接作为模板源, 穷举拦截全部 FTL 起始序列
    static void renderAudit(String v) throws Exception {
        for (String m : FTL_MARKS) { if (v.contains(m)) { throw new IllegalArgumentException("ftl meta"); } }
        render(v, "payload", v);
    }

    private static void render(String src, String var, String val) throws Exception {
        Template t = new Template("cfg", new StringReader(src), cfg());
        Map<String, Object> model = new HashMap<>();
        model.put(var, val);
        StringWriter out = new StringWriter();
        t.process(model, out);
        System.out.println("[cfg-render] " + out);
    }
}
