function fetchImageMetadata(PDO $db, int $imageId): array
{
    // 防御1: int形参类型声明 + PDO命名参数绑定PARAM_INT
    $stmt = $db->prepare('SELECT id, title, exif_json FROM images WHERE id = :id');
    $stmt->bindValue(':id', $imageId, PDO::PARAM_INT);
    $stmt->execute();
    return $stmt->fetch(PDO::FETCH_ASSOC) ?: [];
}

function resolveSortColumn(string $input): string
{
    // 防御2: 硬编码白名单映射, 未命中回退固定列
    static $allow = ['name' => 'title', 'date' => 'created_at', 'size' => 'file_size'];
    return array_key_exists($input, $allow) ? $allow[$input] : 'title';
}

function listAlbumImages(PDO $db, string $sortCol): array
{
    // $sortCol 值域封闭, 拼接处无用户可控内容
    $sql = "SELECT id, title FROM images ORDER BY {$sortCol} ASC LIMIT 50";
    return $db->query($sql)->fetchAll(PDO::FETCH_ASSOC);
}

function getWatermarkConfig(PDO $db, string $template): array
{
    // 防御3: 字符白名单正则 + 位置参数绑定双重隔离
    if (!preg_match('/^[a-z0-9_]{1,32}$/', $template)) {
        return [];
    }
    $stmt = $db->prepare('SELECT cfg_json FROM watermark_templates WHERE name = ?');
    $stmt->execute([$template]);
    return $stmt->fetch(PDO::FETCH_ASSOC) ?: [];
