// 防御1: 锚定白名单, 首字符须为字母数字, 拒绝一切元字符与连字符开头
var tokenRe = regexp.MustCompile(`^[a-z0-9][a-z0-9-]{0,31}$`)

func ValidateToken(s string) bool {
	return tokenRe.MatchString(s)
}

// 流1: 常量二进制 + 参数独立传递, 无 shell 解释, 且先过白名单
func RunServiceStatus(svc string) ([]byte, error) {
	if !ValidateToken(svc) {
		return nil, errors.New("invalid token")
	}
	return exec.Command("/usr/bin/systemctl", "status", svc).Output()
}

// 流2: net.ParseIP 仅接受合法 IP 字面量, 元字符与空白无法通过
func ProbeHost(host string) ([]byte, error) {
	ip := net.ParseIP(host)
	if ip == nil {
		return nil, errors.New("bad address")
	}
	return exec.Command("/bin/ping", "-c", "1", ip.String()).Output()
}

// 流3: 输入仅作映射键, 实际执行路径取自编译期常量表
var jobTable = map[string]string{
	"backup":  "/usr/local/lib/ops/backup.sh",
	"cleanup": "/usr/local/lib/ops/cleanup.sh",
}

func RunJob(name string) ([]byte, error) {
	bin, ok := jobTable[name]
	if !ok {
		return nil, errors.New("unknown job")
	}
	return exec.Command(bin).Output()
}
