  const oldName = sanitizeFilename(req.query.old);
  const newName = sanitizeFilename(req.body.new);
  if (oldName === null || newName === null) return { status: 400, body: 'illegal name' };
  const page = renderPreview(pickTemplate('default'), { name: newName, size: 0 });
  return { status: 200, body: page };
};

