// helper.ts —— 净化与模板渲染工具集
export const TEMPLATES = Object.freeze({
  default: (d) => '<div class=card>' + d.name + '</div>',
  compact: (d) => '<span>' + d.name + '(' + d.size + 'B)</span>'
});

// 防御A: 解码后取基名, 严格白名单校验, 不合法即拒绝
export function sanitizeFilename(raw) {
  let name = String(raw == null ? '' : raw);
  try { name = decodeURIComponent(name); } catch (e) { return null; }
  name = name.split(/[\\/]/).pop();
  if (!/^[A-Za-z0-9._-]{1,64}$/.test(name)) return null;
  return name;
}

// 防御B: 模板键仅作查表索引, 输入永不成为模板源码
export function pickTemplate(key) {
  if (typeof key !== 'string') return TEMPLATES.default;
  if (Object.prototype.hasOwnProperty.call(TEMPLATES, key)) {
    return TEMPLATES[key];
  }
  return TEMPLATES.default;
}

// 防御C: 数据位渲染, 用户数据仅作为上下文变量传入
export function renderPreview(tplFn, data) {
  const ctx = { name: String(data.name), size: parseInt(data.size, 10) || 0 };
  return '<html><body>' + tplFn(ctx) + '</body></html>';
}

// 防御D: HTML 实体转义, 覆盖五个危险字符
export function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, (c) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
  }[c]));
}

// 防御E: split/join 字面替换, 插入值不会被引擎二次解析
export function applySafeTemplate(desc, lang) {
  const dict = lang === 'zh' ? '文件描述: {{desc}}' : 'File desc: {{desc}}';
  return dict.split('{{desc}}').join(escapeHtml(desc));
}
