import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.Map;

public class helper {
    static final Path BASE = Paths.get("/srv/app/templates").toAbsolutePath().normalize();

    // 汇点: 读取模板文件内容供渲染
    static String readTemplate(Path p) throws IOException {
        Path real = p.toRealPath();
        if (!real.startsWith(BASE)) {
            throw new IOException("template escapes base dir");
        }
        return new String(Files.readAllBytes(real), StandardCharsets.UTF_8);
    }

    // 渲染: 仅做占位符文本替换, 值中剥离定界符
    static String render(String tpl, Map<String, String> vars) {
        String out = tpl;
        for (Map.Entry<String, String> e : vars.entrySet()) {
            String val = e.getValue().replace("{{", "").replace("}}", "");
            out = out.replace("{{" + e.getKey() + "}}", val);
        }
        return out;
    }
}
