const libxml = require('libxmljs');

// 解析器安全基线: 合并时置于末位, 强制覆盖调用方传入的危险选项
const SAFE_OPTS = { noent: false, dtdload: false, dtdvalid: false, recover: false };

// 防御A: 关键字黑名单, 拒绝任何 DTD 或实体声明片段
function assertNoExternalEntities(xml) {
  if (typeof xml !== 'string' || xml.length === 0) return false;
  const upper = xml.toUpperCase();
  const banned = ['<!DOCTYPE', '<!ENTITY', 'SYSTEM', 'PUBLIC', 'NDATA'];
  return !banned.some(function (kw) { return upper.indexOf(kw) !== -1; });
}

// 防御B: 字符白名单, 剥离 DTD 与实体语法必需的保留字符
function whitelistTags(xml) {
  return xml.replace(/[^A-Za-z0-9_<>/\s.=-]/g, '');
}

// 防御C: 统一解析入口, 兜底关闭外部实体与外部 DTD
function parsePaymentXml(xml, opts) {
  const merged = Object.assign({}, opts || {}, SAFE_OPTS);
  if (merged.noent !== false || merged.dtdload !== false) {
    throw new Error('unsafe xml parser options rejected');
  }
  return libxml.parseXmlString(xml, merged);
}

// 去除 XML 声明头, 防止编码伪装绕过关键字检查
function stripProlog(xml) {
  return xml.replace(/^[\s\S]*?<\?xml[\s\S]*?\?>/i, '').trim();
}

// 回调验签: HMAC-SHA256, 密钥仅从环境变量读取
function verifySignature(raw, sign) {
  const crypto = require('crypto');
  const secret = process.env.PAY_WEBHOOK_SECRET || '';
  if (!secret || typeof sign !== 'string' || sign.length !== 64) return false;
  const expect = crypto.createHmac('sha256', secret).update(raw).digest('hex');
  return crypto.timingSafeEqual(Buffer.from(expect), Buffer.from(sign));
}

module.exports = { parsePaymentXml, assertNoExternalEntities, whitelistTags, stripProlog, verifySignature };
