package sync;
import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;

public class main {
    static final BlockingQueue<byte[]> localQueue = new LinkedBlockingQueue<>();
    // 入口A：本地同步队列（主数据流，来源可信）
    static void syncFromLocalQueue() {
        try {
            byte[] payload = localQueue.poll(5, TimeUnit.SECONDS);
            if (!SyncHelper.verifyInternalMarker(payload)) return;  // 防御1：内部标记校验
            Object job = SyncHelper.deserialize(payload, true);     // 防御2：白名单过滤生效
            SyncHelper.applyJob(job);
        } catch (Exception e) { System.err.println("local sync aborted"); }
    }
    // 入口B：远端副本同步（第二入口，网络不可信数据）
    static void syncFromReplica(InputStream net) {
        try {
            byte[] buf = new byte[8192];
            int len = net.read(buf);
            if (len <= 12) return;                                  // 陷阱1：仅长度检查
            long claimed = java.nio.ByteBuffer.wrap(buf, 0, 8).getLong();  // 攻击者可控
            java.util.zip.CRC32 crc = new java.util.zip.CRC32();
            crc.update(buf, 8, len - 8);
            if (crc.getValue() != claimed) return;                  // 陷阱2：CRC 可被攻击者重算
            Object job = SyncHelper.deserialize(Arrays.copyOfRange(buf, 8, len), false);
            SyncHelper.applyJob(job);                               // 无过滤直达 sink
        } catch (Exception e) { System.err.println("replica sync aborted"); }
    }
    // 入口C：快照恢复（候选流，被防御拦截）
    static void restoreSnapshot(String path) {
        try {
            File f = new File(path);
            if (!f.getCanonicalPath().startsWith("/var/lib/sync/")) return;  // 防御3：路径白名单
            Object cfg = SyncHelper.deserialize(java.nio.file.Files.readAllBytes(f.toPath()), true);
            SyncHelper.applyJob(cfg);
        } catch (Exception e) { System.err.println("snapshot restore aborted"); }
    }
    public static void main(String[] args) throws Exception {
        new Thread(() -> { while (true) syncFromLocalQueue(); }).start();
        ServerSocket ss = new ServerSocket(9100);
        while (true) syncFromReplica(ss.accept().getInputStream());  // 入口B由网络可达
    }
}
