package sync;
import java.io.*;
import java.util.Arrays;

public class SyncHelper {
    private static final byte[] MARKER = "INTERNAL_SYNC_V1".getBytes();
    // 防御1：内部标记校验（仅入口A调用）
    static boolean verifyInternalMarker(byte[] payload) {
        if (payload == null || payload.length < MARKER.length) return false;
        return Arrays.equals(Arrays.copyOf(payload, MARKER.length), MARKER);
    }
    // 唯一反序列化 sink：trusted 为 true 时启用序列化类白名单
    static Object deserialize(byte[] payload, boolean trusted) {
        try {
            ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(payload));
            if (trusted) {
                ois.setObjectInputFilter(ObjectInputFilter.Config.createFilter("sync.SyncJob;!*"));
            }
            return ois.readObject();  // sink：CWE-502
        } catch (Exception e) { return null; }
    }
    static void applyJob(Object job) {
        if (job instanceof Runnable) ((Runnable) job).run();  // gadget 触发点
    }
}
