package main

import (
	"context"
	"errors"
	"io"
	"net"
	"net/http"
	"net/url"
	"time"
)

var allowHosts = map[string]bool{"assets.corp.example": true, "cdn.corp.example": true}

var fetcher = &http.Client{Timeout: 3 * time.Second, CheckRedirect: func(req *http.Request, via []*http.Request) error {
	if len(via) >= 3 { return errors.New("too many redirects") }
	return ValidateURL(req.URL)
}}

func ValidateURL(u *url.URL) error {
	if u == nil || u.Scheme != "https" || !allowHosts[u.Hostname()] { return errors.New("url rejected by policy") }
	ips, err := net.LookupIP(u.Hostname())
	if err != nil { return err }
	for _, ip := range ips {
		if ip.IsLoopback() || ip.IsPrivate() || ip.IsLinkLocalUnicast() || ip.IsUnspecified() {
			return errors.New("private address rejected")
		}
	}
	return nil
}

func FetchTemplateAsset(ctx context.Context, raw string) (string, error) {
	u, err := url.Parse(raw)
	if err != nil { return "", err }
	if err := ValidateURL(u); err != nil { return "", err }
	req, err := http.NewRequestWithContext(ctx, "GET", u.String(), nil)
	if err != nil { return "", err }
	resp, err := fetcher.Do(req)
	if err != nil { return "", err }
	defer resp.Body.Close()
	b, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
	if err != nil { return "", err }
	return string(b), nil
}
