const CLIENT_TOKEN = process.env.CONFIG_CLIENT_TOKEN || '';

// 入口1: 定时拉取远程 XML 配置
export async function pullRemoteConfig() {
  const resp = await fetch(CONFIG_CENTER + '/v1/config/app.xml', {
    headers: { Authorization: 'Bearer ' + CLIENT_TOKEN },
  });
  const raw = await resp.text();           // source: 远端响应体
  const cleaned = stripDtd(raw);           // 防御A: 剥离 DOCTYPE 与 ENTITY
  return makeParser().parse(cleaned);      // sink: 解析器实体展开已关闭
}

// 入口2: 加载本地覆盖配置
export function loadLocalOverride(dir, name) {
  if (!/^[A-Za-z0-9_-]+\.xml$/.test(name)) {
    throw new Error('illegal config file name');
  }
  const full = path.join(dir, name);
  const raw = fs.readFileSync(full, 'utf8'); // source: 本地文件内容
  return safeParseXml(raw);                  // helper.ts 内三层防御
}

// 入口3: 配置中心推送回调
export function handlePushCallback(body, sig) {
  if (!verifySignature(body, sig, process.env.PUSH_SECRET || '')) {
    throw new Error('signature mismatch');
  }
  const parser = makeParser();               // 防御C: 安全基线解析器
  return parser.parse(body);                 // sink: 推送原文直接进解析器
}

