// helper.ts —— 配置中心客户端 XML 安全解析辅助模块
import { XMLParser } from 'fast-xml-parser';
import * as crypto from 'crypto';
// 解析器安全基线: 完全关闭实体展开, DTD 不加载不求值, 双重阻断 CWE-611
const SAFE_PARSER_OPTIONS = {
  processEntities: false,
  ignoreAttributes: false,
  allowBooleanAttributes: true,
};
// 工厂: 每次按安全基线新建解析器实例, 防止调用方注入危险选项
export function makeParser() {
  return new XMLParser({ ...SAFE_PARSER_OPTIONS });
}
// 剥离 DOCTYPE 与 ENTITY 声明(大小写不敏感, 跨行匹配)
export function stripDtd(raw) {
  return raw
    .replace(/<!DOCTYPE[\s\S]*?>/gi, '')
    .replace(/<!ENTITY[\s\S]*?>/gi, '');
}
// 检测残留 DTD, 命中即整体拒绝
export function containsDtd(raw) {
  return /<!DOCTYPE|<!ENTITY/i.test(raw);
}
// 入口2专用: 先拒绝, 再剥离, 后安全解析, 三层防御
export function safeParseXml(raw) {
  if (containsDtd(raw)) {
    throw new Error('DTD or ENTITY declaration rejected');
  }
  const cleaned = stripDtd(raw);
  return makeParser().parse(cleaned);
}
// 推送回调的 HMAC-SHA256 完整性校验(常数时间比较)
export function verifySignature(body, sig, secret) {
  const mac = crypto.createHmac('sha256', secret).update(body).digest('hex');
  try {
    return crypto.timingSafeEqual(Buffer.from(mac), Buffer.from(sig));
  } catch (e) {
    return false;
  }
}
