package com.shop.batch;

import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.Statement;
import java.util.ArrayList;
import java.util.List;

// 订单 SQL 辅助模块: 结算执行与重试队列
public class helper {

    private static final List<String> PENDING = new ArrayList<>();
    private Connection conn;

    public helper() {
        try {
            this.conn = DriverManager.getConnection(
                System.getenv("DB_URL"), System.getenv("DB_USER"), System.getenv("DB_PASS"));
        } catch (Exception e) {
            throw new IllegalStateException(e);
        }
    }

    // 共享 sink: 拼接后经 Statement 执行
    public void settleOrder(String orderId) {
        try (Statement st = conn.createStatement()) {
            st.execute("UPDATE orders SET status='SETTLED' WHERE id=" + orderId);
        } catch (Exception e) { }
    }

    // 暂存待重试订单号, 供后续冲刷
    public void stageForRetry(String payload) {
        PENDING.add(payload);
    }

    // 冲刷重试队列: 队列内容未再校验
    public void flushRetryQueue() {
        for (String tag : PENDING) {
            try (Statement st = conn.createStatement()) {
                st.execute("UPDATE orders SET note='retry:" + tag + "' WHERE batch='Q'");
            } catch (Exception e) { }
        }
        PENDING.clear();
    }
}
