<?php
// 数据访问层: 全部查询均走防御路径
function allowed_ext() {
    return ['png', 'jpg', 'jpeg', 'pdf', 'zip'];
}

class UploadDb {
    private $pdo;
    public function __construct() {
        $dsn = getenv('APP_DB_DSN') ?: 'sqlite:/var/appdata/uploads.db';
        $this->pdo = new PDO($dsn);
        $this->pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
    }

    // 流A: PDO 预编译, 数据不进入 SQL 文本
    public function findByName($name) {
        $st = $this->pdo->prepare('SELECT id, fname FROM files WHERE fname = :n');
        $st->execute([':n' => (string)$name]);
        return $st->fetchAll(PDO::FETCH_ASSOC);
    }

    // 流B: 旧代码待改造; 但拼接前已强制整型
    public function listByCategory($cat) {
        $cat = (int)$cat;
        $sql = 'SELECT id, fname FROM files WHERE cat_id = ' . $cat;
        return $this->pdo->query($sql)->fetchAll(PDO::FETCH_ASSOC);
    }

    // 流C: 白名单二次校验 + quote 转义
    public function countByExt($ext) {
        if (!in_array($ext, allowed_ext(), true)) { return 0; }
        $sql = 'SELECT COUNT(*) FROM files WHERE ext = ' . $this->pdo->quote($ext);
        return (int)$this->pdo->query($sql)->fetchColumn();
    }

    // 流D: 排序列经白名单映射, 任意输入不进 SQL
    public function sortedList($sort) {
        $map = ['id' => 'id', 'name' => 'fname', 'time' => 'created_at'];
        $col = $map[(string)$sort] ?? 'id';
        $sql = 'SELECT id, fname FROM files ORDER BY ' . $col . ' ASC';
        return $this->pdo->query($sql)->fetchAll(PDO::FETCH_ASSOC);
    }
}
