package com.ops.runner;

import java.util.HashMap;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** 模板内核: 单遍求值, 变量值经 quoteReplacement 字面插入, 永不二次解析 */
class helper {
    static final Pattern PLACEHOLDER = Pattern.compile("\\$\\{([a-z]+)\\}");
    static final java.util.Set<String> BINARIES = new java.util.HashSet<>(java.util.Arrays.asList("tar", "kubectl"));
    static final Map<String, String> REGISTRY = new HashMap<>();
    static {
        REGISTRY.put("backup", "tar -czf ${dest}.tgz ${src}");
        REGISTRY.put("deploy", "kubectl rollout status deploy/${app}");
        REGISTRY.put("health", "kubectl get --raw /healthz?host=${host}");
    }

    static String resolveTemplate(String key) {
        String tpl = REGISTRY.get(key);
        if (tpl == null) throw new IllegalArgumentException("key not allowed");
        return tpl;
    }
    static boolean checkTarget(String t) { return t != null && t.matches("^[a-z0-9][a-z0-9._-]{0,63}$"); }
    static String sanitizeValue(String v) { if (v == null || !v.matches("^[a-z0-9][a-z0-9.-]{0,252}$")) throw new IllegalArgumentException("bad value"); return v; }
    static boolean isTemplateSafe(String s) { return s != null && !s.matches(".*[$\\{}`<>|;&%\"'\r\n].*"); }

    static String render(String tpl, Map<String, String> vars) {
        Matcher m = PLACEHOLDER.matcher(tpl);
        StringBuffer sb = new StringBuffer();
        while (m.find()) {
            String val = vars.get(m.group(1));
            if (val == null) throw new IllegalArgumentException("missing var");
            m.appendReplacement(sb, Matcher.quoteReplacement(val));
        }
        return m.appendTail(sb).toString();
    }

    static int exec(String cmd) {
        String[] parts = cmd.trim().split("\\s+");
        if (!BINARIES.contains(parts[0])) return -3;
        for (String p : parts) if (!p.matches("^[A-Za-z0-9./_=?-]+$")) return -4;
        try { return new ProcessBuilder(parts).redirectErrorStream(true).start().waitFor(); }
        catch (Exception e) { return -1; }
    }
}
