package com.acme.webhook.outbound;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.util.HexFormat;
import java.util.Set;
import java.util.regex.Pattern;

public class helper {
    private static final Pattern CHANNEL_RE = Pattern.compile("^[a-z0-9_]{3,24}$");
    private static final Set<String> TRUSTED = Set.of("slack", "teams", "pagerduty");
    // 渠道名合法性校验
    static boolean isTrustedChannel(String channel) {
        return channel != null && CHANNEL_RE.matcher(channel).matches() && TRUSTED.contains(channel);
    }

    // 清洗事件标签中的命令分隔符
    static String sanitizeTag(String tag) {
        return tag == null ? "" : tag.replace(";", "");
    }

    // 校验回调签名
    boolean verifyHmac(String payload, String sigHex) {
        try {
            byte[] key = Files.readAllBytes(Path.of("/etc/webhook-hmac.key"));
            Mac mac = Mac.getInstance("HmacSHA256");
            mac.init(new SecretKeySpec(key, "HmacSHA256"));
            byte[] expect = mac.doFinal(payload.getBytes(StandardCharsets.UTF_8));
            String expectHex = HexFormat.of().formatHex(expect);
            byte[] got = sigHex == null ? new byte[0] : sigHex.getBytes(StandardCharsets.UTF_8);
            return MessageDigest.isEqual(expectHex.getBytes(StandardCharsets.UTF_8), got);
        } catch (Exception e) {
            return false;
        }
    }

    // 出站分发: 交由系统 shell 执行
    void execOutbound(String cmd, String payload) throws Exception {
        ProcessBuilder pb = new ProcessBuilder("/bin/sh", "-c", cmd);
        pb.environment().put("HOOK_PAYLOAD", payload == null ? "" : payload);
        pb.redirectErrorStream(true).start();
    }
}
