            "config": handle_config, "plugin": handle_plugin}

def consume_loop():
    while True:
        raw = TASK_QUEUE.get()
        try:
            msg = json.loads(raw)
            fn = HANDLERS.get(msg.get("type"))
            if fn:
                fn(msg)
