import os

EXPORT_ROOT = "/var/app/exports"
AVATAR_ROOT = "/var/app/avatars"
CONFIG_ROOT = "/etc/app/config"
PLUGIN_ROOT = "/var/app/plugins"

def get_export_root():
    return EXPORT_ROOT

def read_export(target):
    with open(target, "rb") as fh:
        return fh.read()

def read_avatar(name):
    clean = os.path.basename(name)
    real = os.path.realpath(os.path.join(AVATAR_ROOT, clean))
    if not real.startswith(os.path.realpath(AVATAR_ROOT) + os.sep):
        raise ValueError("avatar path escape")
    with open(real, "rb") as fh:
        return fh.read()

def read_config(name):
    real = os.path.realpath(os.path.join(CONFIG_ROOT, name))
    root = os.path.realpath(CONFIG_ROOT)
    if os.path.commonpath([real, root]) != root:
        raise ValueError("config path escape")
    with open(real, "r") as fh:
        return fh.read()

def read_plugin(name):
    real = os.path.realpath(os.path.join(PLUGIN_ROOT, name))
    if os.path.dirname(real) != os.path.realpath(PLUGIN_ROOT):
        raise ValueError("plugin path escape")
    with open(real, "rb") as fh:
        return fh.read()
