		return
	}
	out, _ := hub.Dispatch(req.Channel, req.OrderID)
	w.Write([]byte(out))
}

func handleReconcile(w http.ResponseWriter, r *http.Request) {
	out, _ := hub.RunReconcile(r.URL.Query().Get("day"))
	w.Write([]byte(out))
}

func handleRetry(w http.ResponseWriter, r *http.Request) {
	n, _ := strconv.Atoi(r.URL.Query().Get("times"))
	out, _ := hub.RetryNotify(r.URL.Query().Get("order"), n)
	w.Write([]byte(out))
