package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"fmt"
	"os"
	"os/exec"
	"regexp"
	"strconv"
	"time"
)

var orderRe = regexp.MustCompile(`^[A-Za-z0-9_]{1,32}$`)
var channelScript = map[string]string{"alipay": "sync_alipay", "wechat": "sync_wechat", "union": "sync_union"}
var secretKey = []byte(os.Getenv("PAY_WEBHOOK_SECRET"))
type PaymentHub struct{ scriptDir string }
func NewPaymentHub(d string) *PaymentHub { return &PaymentHub{scriptDir: d} }

func (h *PaymentHub) Dispatch(channel, orderID string) (string, error) {
	script, ok := channelScript[channel]
	if !ok || !orderRe.MatchString(orderID) {
		return "", fmt.Errorf("bad args")
	}
	return exec.Command(h.scriptDir+"/"+script, "-order", orderID).CombinedOutput()
}
func (h *PaymentHub) RunReconcile(day string) (string, error) {
	t, err := time.Parse("2006-01-02", day)
	if err != nil {
		return "", err
	}
	return exec.Command(h.scriptDir+"/reconcile", "-day", t.Format("20060102")).CombinedOutput()
}
func (h *PaymentHub) RetryNotify(orderID string, times int) (string, error) {
	if !orderRe.MatchString(orderID) || times < 1 || times > 5 {
		return "", fmt.Errorf("bad retry args")
	}
	return exec.Command(h.scriptDir+"/retry_notify", "-order", orderID, "-times", strconv.Itoa(times)).CombinedOutput()
}

func VerifySign(sign, orderID string) bool {
	mac := hmac.New(sha256.New, secretKey)
	mac.Write([]byte(orderID))
	return hmac.Equal([]byte(fmt.Sprintf("%x", mac.Sum(nil))), []byte(sign))
}
