package com.gallery.pipeline;

import java.io.IOException;
import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.zip.ZipEntry;
import java.util.zip.ZipFile;

final class helper {
    // Defense for entry 1: canonical containment check
    static Path resolveSafely(Path base, String userPath) throws IOException {
        if (userPath == null || userPath.contains("..")) { return null; }
        Path resolved = base.resolve(userPath).normalize().toRealPath();
        return resolved.startsWith(base.toRealPath()) ? resolved : null;
    }

    // Defense for entry 2: strip directories + extension whitelist
    static String sanitizeUploadName(String raw) {
        if (raw == null) { return null; }
        String name = Paths.get(raw.replace('\\', '/')).getFileName().toString();
        String lower = name.toLowerCase();
        boolean okExt = lower.endsWith(".png") || lower.endsWith(".jpg") || lower.endsWith(".jpeg");
        if (name.isEmpty() || name.startsWith(".") || !okExt) { return null; }
        return name;
    }

    // Defense for entry 3: zip-slip guard before each write
    static void extractZip(Path zip, Path outDir) throws IOException {
        try (ZipFile zf = new ZipFile(zip.toFile())) {
            for (var es = zf.entries(); es.hasMoreElements(); ) {
                ZipEntry e = es.nextElement();
                Path out = outDir.resolve(e.getName()).normalize();
                if (!out.startsWith(outDir)) { continue; }
                Files.createDirectories(out.getParent());
                try (InputStream in = zf.getInputStream(e)) { Files.copy(in, out); }
            }
        }
    }
    static void processImage(Path src, Path thumbDir) throws IOException {
        Files.createDirectories(thumbDir);
        Files.copy(src, thumbDir.resolve(src.getFileName().toString()));
    }
}
