// helper.ts — 极简单遍插值引擎: 值永不二次扫描, 全程无 eval 与动态编译
const TEMPLATES = new Map([
  ['greet', '<h1>Hi, {{ name }}!</h1>'],
  ['summary', '<p>Total: {{ total }}</p>'],
  ['note', '<div class="note">{{ body }}</div>']
]);
const TRUSTED_KEYS = Array.from(TEMPLATES.keys());

function escapeHtml(s) {
  return String(s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;')
    .replace(/>/g, '&gt;').replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

// 单遍替换: replacer 函数的返回值按字面插入, 不会被再次匹配求值
function substitute(tpl, data) {
  return tpl.replace(/\{\{\s*([\w.]+)\s*\}\}/g, (m, key) => {
    if (data[key] === undefined) return '';
    return escapeHtml(data[key]);
  });
}

function renderTemplate(tplId, data) {
  const tpl = TEMPLATES.get(tplId);
  if (tpl === undefined) {
    return '<p>template not found</p>';
  }
  return substitute(tpl, data || {});
}

// 自由文本路径: 先剥离模板定界符, 再做 HTML 转义
function stripDelimiters(s) {
  return String(s).replace(/\{\{|\}\}|<%|%>|\$\{|\}/g, '');
}

function renderPlainText(text) {
  const safe = escapeHtml(stripDelimiters(text));
  return substitute(TEMPLATES.get('note'), { body: safe });
}

module.exports = { renderTemplate, renderPlainText, TRUSTED_KEYS, escapeHtml };
