	img, err := FetchThumb(r.Context(), r.URL.Query().Get("thumb_src"))
	writeImage(w, img, err)
}

// 入口3: /legacy 的 X-Image-Ref 头作为预注册资源索引
func handleLegacy(w http.ResponseWriter, r *http.Request) {
	img, err := FetchByID(r.Context(), r.Header.Get("X-Image-Ref"))
	writeImage(w, img, err)
}

func main() {
	http.HandleFunc("/upload", handleUpload)
	http.HandleFunc("/thumb", handleThumb)
	http.HandleFunc("/legacy", handleLegacy)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
