package main
import (
	"context"
	"errors"
	"io"
	"net/http"
	"net/url"
	"regexp"
	"time"
)

var allowedHosts = map[string]bool{"cdn.trusted-assets.example": true, "images.partner-cdn.example": true}
var refRegistry = map[string]string{"hero-banner": "https://cdn.trusted-assets.example/img/hero.png", "avatar-default": "https://images.partner-cdn.example/def.png"}
var errBlocked = errors.New("rejected by image pipeline policy")
var idPattern = regexp.MustCompile(`^[a-z0-9]{8,16}$`)

// 统一出口 client: 禁止跟随重定向, 阻断白名单主机 302 跳内网的路径
var imgClient = &http.Client{Timeout: 5 * time.Second,
	CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse }}

func fetchBytes(ctx context.Context, target string) ([]byte, error) {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, target, nil)
	if err != nil { return nil, err }
	resp, err := imgClient.Do(req)
	if err != nil { return nil, err }
	defer resp.Body.Close()
	return io.ReadAll(io.LimitReader(resp.Body, 1<<20))
}

func FetchRemoteImage(ctx context.Context, rawURL string) ([]byte, error) {
	u, err := url.Parse(rawURL)
	if err != nil || u.Scheme != "https" || !allowedHosts[u.Hostname()] { return nil, errBlocked }
	return fetchBytes(ctx, rawURL)
}

func FetchThumb(ctx context.Context, imageID string) ([]byte, error) {
	if !idPattern.MatchString(imageID) { return nil, errBlocked }
	return fetchBytes(ctx, "https://cdn.trusted-assets.example/img/"+imageID+".png")
}

func FetchByID(ctx context.Context, ref string) ([]byte, error) {
	target, ok := refRegistry[ref]
	if !ok { return nil, errBlocked }
	return fetchBytes(ctx, target)
}
