// helper.php - 配置客户端辅助模块(密钥仅取自环境变量, 无硬编码凭据)
define('CONFIG_CACHE_DIR', sys_get_temp_dir() . '/cfgcache');
define('CFG_HMAC_KEY', (string)(getenv('CFG_HMAC_KEY') ?: bin2hex(random_bytes(32))));
class DiagLogger {                    // 陷阱类: __destruct写文件, 但从不进入反序列化白名单
    public $path = ''; public $buf = '';
    public function __destruct() {
        if ($this->path !== '') { file_put_contents($this->path, $this->buf, FILE_APPEND); }
    }
}
function verify_hmac(string $raw, string $sig): bool {
    return hash_equals(hash_hmac('sha256', $raw, CFG_HMAC_KEY), $sig); // 常量时间比较
}
function verify_center_body(string $body): ?string {
    if (($nl = strpos($body, "\n")) === false) { return null; }
    $mac = substr($body, 0, $nl); $payload = substr($body, $nl + 1);
    return verify_hmac($payload, $mac) ? $payload : null;   // 先验签后放行
}
function is_pure_scalar_tree($v): bool {
    if (is_array($v)) {
        foreach ($v as $item) { if (!is_pure_scalar_tree($item)) { return false; } }
        return true;
    }
    return is_scalar($v) || $v === null;   // 任何对象(含__PHP_Incomplete_Class)一律拒绝
}
function safe_unserialize(string $raw) {
    $v = @unserialize($raw, ['allowed_classes' => false]); // 禁止一切类实例化
    return is_pure_scalar_tree($v) ? $v : null;            // 二次结构校验
}
function save_cache(string $name, string $payload): bool {
    $file = CONFIG_CACHE_DIR . '/' . basename($name);      // basename防目录穿越
    $mac  = hash_hmac('sha256', $payload, CFG_HMAC_KEY);
    return file_put_contents($file, $mac . "\n" . $payload) !== false;
}
function load_cache(string $name) {
    $blob = @file_get_contents(CONFIG_CACHE_DIR . '/' . basename($name)); // 防穿越
    $nl = strpos((string)$blob, "\n");
    if ($blob === false || $nl === false) { return null; }
    $payload = substr((string)$blob, $nl + 1);
    if (!verify_hmac($payload, substr((string)$blob, 0, $nl))) { return null; } // 缓存验签
    return safe_unserialize($payload);                     // 白名单反序列化
}
function http_get(string $url): string {
    return (string)@file_get_contents($url, false, stream_context_create(['http' => ['timeout' => 3]]));
}
