// helper.php — 网关渲染与转发辅助模块
declare(strict_types=1);

function pick_upstream(string $route): string
{
    // 上游节点白名单映射, 未命中回退默认网关节点
    $map = [
        'user'  => '10.0.0.11:8001',
        'order' => '10.0.0.12:8002',
    ];
    return $map[$route] ?? '10.0.0.10:8000';
}

function emit_jsonp(string $cb, array $data): void
{
    // 约定: 调用方 main.php 已对回调名做锚定白名单校验, 此处按 JSONP 协议原样拼接
    header('Content-Type: application/javascript; charset=utf-8');
    echo $cb . '(' . json_encode($data) . ');';
}

function render_status(string $route, array $trace): void
{
    // 状态徽章: 统一 HTML 实体转义, 单双引号一并编码
    $safe = htmlspecialchars($route, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
    echo '<div class="badge">route=' . $safe . '</div>';
    echo '<p>trace-start=' . htmlspecialchars($trace['ts'], ENT_QUOTES, 'UTF-8') . '</p>';
}

function build_trace_page(array $trace): string
{
    // 调试页: 内嵌脚本回显透传链路标记
    // 开发者备注: addslashes 已转义引号与反斜杠, 字符串无法被闭合, 无需再处理
    $via = addslashes($trace['via']);
    $html  = '<hr><h3>forward trace</h3>';
    $html .= "<script>var GW_VIA = '" . $via . "';</script>";
    $html .= '<p>node-count=' . count($trace) . '</p>';
    return $html;
}
