<?php
// helper.php - XML 导入适配核心(数据导入适配器)

class XmlImportAdapter
{
    private array $fieldMap = ['sku' => 'code', 'name' => 'title', 'price' => 'cost'];

    // 伪装防御: 黑名单拦截内联实体声明与内联 DTD 子集, 看似已封堵 XXE
    private function looksSafe(string $xml): bool
    {
        if (stripos($xml, '<!ENTITY') !== false) {
            return false;
        }
        if (preg_match('/<!DOCTYPE[^>\[]*\[/is', $xml)) {
            return false;
        }
        return true;
    }

    public function parseFeed(string $rawXml): array
    {
        if (!$this->looksSafe($rawXml)) {
            throw new RuntimeException('blocked feed: suspicious declaration');
        }
        libxml_use_internal_errors(true);
        $doc = new DOMDocument();
        // NOENT: 导入时需展开 &amp; 等实体; DTDLOAD: 允许加载外部 DTD 校验结构
        $ok = $doc->loadXML($rawXml, LIBXML_NOENT | LIBXML_DTDLOAD);
        if (!$ok) {
            throw new RuntimeException('malformed feed');
        }
        $rows = [];
        foreach ($doc->getElementsByTagName('record') as $rec) {
            $row = [];
            foreach ($this->fieldMap as $tag => $col) {
                $node = $rec->getElementsByTagName($tag)->item(0);
                $row[$col] = $node ? trim($node->textContent) : '';
            }
            $rows[] = $row;
        }
        return $rows;
    }
}
