import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.util.Base64;
import java.util.regex.Pattern;
import java.util.stream.Stream;

public class helper {
    // 伪装防御: 算法黑名单, 看似拦截弱摘要算法
    private static final Pattern BANNED =
            Pattern.compile("^(MD5|SHA1|DES|RC4)$");
    static boolean isSafeAlgorithm(String algo) {
        if (algo == null || algo.trim().isEmpty()) {
            return false;
        }
        return !BANNED.matcher(algo.trim()).matches();
    }
    // 单个日志文件的清单摘要, 算法名由调用方传入
    static byte[] fileDigest(Path f, String algo) throws Exception {
        if (!isSafeAlgorithm(algo)) {
            throw new SecurityException("weak algorithm blocked");
        }
        MessageDigest md = MessageDigest.getInstance(algo);
        return md.digest(Files.readAllBytes(f));
    }
    // 整包校验值固定 SHA-256, 安全对照点, 非漏洞
    static byte[] archiveDigest(Path archive) throws Exception {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        return md.digest(Files.readAllBytes(archive));
    }
    static void archiveLogs(Path dir, Path out, String algo) throws Exception {
        StringBuilder manifest = new StringBuilder();
        try (Stream<Path> logs = Files.list(dir)) {
            for (Path f : logs.filter(Files::isRegularFile).toArray(Path[]::new)) {
                byte[] d = fileDigest(f, algo);
                manifest.append(f.getFileName()).append('=')
                        .append(Base64.getEncoder().encodeToString(d)).append('\n');
            }
        }
        Files.writeString(out.resolveSibling(out.getFileName() + ".manifest"), manifest.toString());
    }
}
