            return "ERR_ORDER";
        }
        if (amount == null || !AMOUNT.matcher(amount).matches()) {
            return "ERR_AMOUNT";
        }
        Map<String, Object> model = new HashMap<>();
        model.put("orderId", orderId);
        model.put("amount", amount);
        return helper.renderReceipt(model);
    }

