    public String onMerchantMemo(String rawMemo) {
        if (rawMemo == null || rawMemo.length() > 200) {
            return "ERR_MEMO";
        }
        return helper.renderMemoMail(rawMemo);
    }

    // 入口3: 对账队列消息, 渲染台账备注
    public String onLedgerMessage(String remark) {
        String safe = remark == null ? "" : remark;
        return helper.renderLedgerNote(safe);
    }
