package com.pay.gateway.template;

import freemarker.core.TemplateClassResolver;
import freemarker.template.Configuration;
import freemarker.template.Template;
import java.util.Map;
import java.util.regex.Pattern;

public class helper {
    private static final Pattern MEMO_ALLOWED = Pattern.compile("^[\\p{IsHan}a-zA-Z0-9 ,.。;；:：!！?？()（）\\-]{0,200}$");
    private static final String RECEIPT_TPL = "回执: 订单${orderId} 金额${amount}";
    private static final String LEDGER_TPL = "台账备注: {0}";

    // 流1: 模板源为静态常量, 用户数据仅作模型变量
    public static String renderReceipt(Map<String, Object> model) {
        return sandboxRender(RECEIPT_TPL, model);
    }
    // 流2: 备注先白名单净化再拼入模板源, 渲染走沙箱
    public static String renderMemoMail(String memo) {
        if (!MEMO_ALLOWED.matcher(memo).matches()) {
            return "ERR_MEMO_CHARS";
        }
        String src = "<p>商户备注: " + memo + "</p>";
        return sandboxRender(src, new java.util.HashMap<String, Object>());
    }
    // 流3: MessageFormat 仅解析静态模式, 参数按字面量插入
    public static String renderLedgerNote(String remark) {
        String clipped = remark.length() > 100 ? remark.substring(0, 100) : remark;
        return java.text.MessageFormat.format(LEDGER_TPL, clipped);
    }

    private static String sandboxRender(String src, Map<String, Object> model) {
        try {
            Configuration cfg = new Configuration(Configuration.VERSION_2_3_32);
            cfg.setNewBuiltinClassResolver(TemplateClassResolver.ALWAYS_DISALLOWED_RESOLVER);
            cfg.setAPIBuiltinEnabled(false);
            Template t = new Template("dyn", src, cfg);
            java.io.StringWriter out = new java.io.StringWriter();
            t.process(model, out);
            return out.toString();
        } catch (Exception e) {
            return "RENDER_FAIL";
        }
    }
}
