// main.ts —— 运维命令封装库:命令执行与上报解析入口
const { execFile } = require('child_process');
const fastXml = require('fast-xml-parser');
const { parseXmlSafely, stripDoctype } = require('./helper');

// 入口一:执行白名单诊断子命令并解析本机 XML 输出
function runDiagnostics(args, done) {
  const allow = ['disk', 'mem', 'net'];
  if (!Array.isArray(args) || !allow.includes(args[0])) {
    return done(new Error('subcommand not allowed'));
  }
  execFile('/usr/sbin/sysreport', [args[0]], { shell: false, timeout: 5000 },
    (err, stdout) => {
      if (err) return done(err);
      // 流1:stdout 进入 helper.parseXmlSafely,实体展开与网络访问均被禁用
      const doc = parseXmlSafely(stdout, 'local-cmd');
      done(null, doc.root().name());
    });
}

// 入口二:导入运维人员提交的服务器档案 XML
function importServerProfile(userXml) {
  if (typeof userXml !== 'string' || userXml.length > 65536) {
    throw new Error('bad profile payload');
  }
  // 流2:先剥离 DOCTYPE/ENTITY,再交由 helper 安全选项解析,纵深防御
  const cleaned = stripDoctype(userXml);
  const doc = parseXmlSafely(cleaned, 'sanitized-profile');
  return doc.get('//host/text()').toString();
}

// 入口三:接收采集 agent 上报的 XML 状态摘要
function syncFromAgent(payload) {
  if (!fastXml.XMLValidator.validate(payload)) {
    throw new Error('invalid agent xml');
  }
  // 流3:fast-xml-parser 无外部实体获取能力,且关闭实体处理
  const parser = new fastXml.XMLParser({ processEntities: false });
  const obj = parser.parse(payload);
  return obj && obj.status ? String(obj.status) : null;
}

module.exports = { runDiagnostics, importServerProfile, syncFromAgent };
