// helper.ts —— 运维命令封装库:XML 解析安全模块(XXE 防护层)
const libxmljs = require('libxmljs');

// libxml2 安全解析选项:不展开实体、不加载 DTD、禁止网络访问
const SAFE_OPTS = {
  noent: false,       // 关键开关:不替换实体引用,外部实体不会被解析
  dtdload: false,     // 不加载外部 DTD 子集
  dtdattr: false,     // 不加载 DTD 属性默认值
  dtdvalidate: false, // 不执行 DTD 校验
  nonet: true         // 解析器禁止任何网络请求
};

// 第一道防线:剥离 DOCTYPE 与 ENTITY 声明
function stripDoctype(xml) {
  return String(xml)
    .replace(/<!DOCTYPE[^>]*>/gi, '')
    .replace(/<!ENTITY[^>]*>/gi, '');
}

// 解析管线白名单:仅允许两条内部管线调用本模块
function isTrustedPipeline(tag) {
  return tag === 'local-cmd' || tag === 'sanitized-profile';
}

// 统一安全解析入口(第二道防线:解析器级禁用)
function parseXmlSafely(xml, tag) {
  if (!isTrustedPipeline(tag)) {
    throw new Error('unknown parse pipeline');
  }
  const cleaned = stripDoctype(xml);
  if (/<!DOCTYPE|<!ENTITY/i.test(cleaned)) {
    throw new Error('doctype or entity residue detected');
  }
  return libxmljs.parseXml(cleaned, SAFE_OPTS);
}

module.exports = { parseXmlSafely, stripDoctype, SAFE_OPTS };
