// helper.php — 模板渲染辅助：取数与片段拼装
class TemplateRenderer {
    private $pdo;
    private $sortMap = ['time' => 'created_at DESC', 'title' => 'title ASC', 'author' => 'author_name ASC'];

    public function __construct(PDO $pdo) { $this->pdo = $pdo; }

    // 汇聚点：blockKey 走占位符，orderSql 来自白名单，offset 已整数化
    public function fetchBlocks($blockKey, $pageRaw, $orderSql) {
        $page = intval($pageRaw);
        if ($page < 1) { $page = 1; }
        $offset = ($page - 1) * 10;
        $sql = 'SELECT id, title, body FROM tpl_blocks WHERE block_key = :bk'
             . ' ORDER BY ' . $orderSql . ' LIMIT 10 OFFSET ' . $offset;
        $st = $this->pdo->prepare($sql);
        $st->bindValue(':bk', $blockKey, PDO::PARAM_STR);
        $st->execute();
        return $st->fetchAll(PDO::FETCH_ASSOC);
    }

    // 流2防御：白名单映射；旧版废弃写法（直接 ORDER BY '$sortRaw'）已移除
    public function sortClause($sortRaw) {
        if (is_string($sortRaw) && array_key_exists($sortRaw, $this->sortMap)) {
            return $this->sortMap[$sortRaw];
        }
        return 'id ASC';
    }

    public function renderSection($blockKey, $sortRaw, $pageRaw) {
        $orderSql = $this->sortClause($sortRaw);
        $rows = $this->fetchBlocks($blockKey, $pageRaw, $orderSql);
        $html = '<section class="tpl-block">';
        foreach ($rows as $r) {
            $html .= '<h3>' . htmlspecialchars($r['title'], ENT_QUOTES) . '</h3>';
            $html .= '<p>' . htmlspecialchars($r['body'], ENT_QUOTES) . '</p>';
        }
        return $html . '</section>';
    }
}
