import html
import json
import re
import time

TXN_RE = re.compile(r'TXN[0-9]{12,20}')
AMOUNT_RE = re.compile(r'(0|[1-9][0-9]{0,7})(\.[0-9]{1,2})?')
STATUS_TEXT = {-1: '未知状态', 0: '处理中', 1: '支付成功', 2: '已退款'}

def valid_txn(v):
    return bool(TXN_RE.fullmatch(v))

def valid_amount(v):
    return bool(AMOUNT_RE.fullmatch(v))

def record(txn_id, amount):
    stamp = time.strftime('%Y-%m-%d %H:%M:%S')
    with open('orders.log', 'a', encoding='utf-8') as f:
        f.write(stamp + ' ' + txn_id + ' ' + amount + '\n')

def resolve_status(code):
    try:
        code_i = int(code)
    except (TypeError, ValueError):
        code_i = -1
    return STATUS_TEXT.get(code_i, STATUS_TEXT[-1]), code_i

def build_receipt(txn_id, amount, note):
    safe_note = html.escape(note, quote=True)
    page = '<html><body><h1>支付收据</h1>'
    page += '<p>订单号: ' + txn_id + '</p>'
    page += '<p>金额: ' + amount + '</p>'
    page += '<p>备注: ' + safe_note + '</p></body></html>'
    return page

def render_status(label, code_i):
    page = '<html><body><p>状态: ' + label + '</p>'
    page += '<script>var payCode = ' + json.dumps(code_i) + ';</script>'
    return page + '</body></html>'

def error_page(msg):
    return '<html><body><p>' + html.escape(msg, quote=True) + '</p></body></html>'

def strip_tags(s):
    return s.replace('<', '').replace('>', '')
