package com.corp.upload;
import java.io.File;
import java.io.IOException;
import java.nio.file.Path;
import java.util.regex.Pattern;

public class main {
    static final File UPLOAD_ROOT = new File("/var/app/uploads").getCanonicalFile();
    static final Pattern NAME_WHITELIST = Pattern.compile("^[A-Za-z0-9._-]{1,64}$");
    // 入口1: 直接上传, 文件名用户可控
    public String handleUpload(String userFilename, byte[] data) throws IOException {
        if (userFilename == null || !NAME_WHITELIST.matcher(userFilename).matches()) {
            throw new IllegalArgumentException("illegal filename");
        }
        File target = new File(UPLOAD_ROOT, userFilename);
        if (!target.getCanonicalPath().startsWith(UPLOAD_ROOT.getPath() + File.separator)) {
            throw new SecurityException("traversal rejected");
        }
        helper.persist(target, data);
        return helper.register(target.getName());
    }

    // 入口2: 导入编码相对路径, 先解码再校验
    public String handleImport(String encodedRel, byte[] data) throws IOException {
        String rel = java.net.URLDecoder.decode(encodedRel, "UTF-8");
        String cleaned = helper.weakSanitize(rel);
        Path base = UPLOAD_ROOT.toPath();
        Path resolved = base.resolve(cleaned).normalize();
        if (!resolved.startsWith(base)) {
            throw new SecurityException("escape outside upload root");
        }
        helper.persist(resolved.toFile(), data);
        return helper.register(base.relativize(resolved).toString());
    }

    // 入口3: 凭令牌删除历史文件
    public boolean handleDelete(String token) throws IOException {
        String mapped = helper.mapToken(token);
        File victim = new File(UPLOAD_ROOT, mapped);
        if (victim.getCanonicalPath().startsWith(UPLOAD_ROOT.getPath() + File.separator)) {
            return victim.delete();
        }
        return false;
    }
}
