package com.corp.upload;
import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;
public class helper {
    private static final Map<String, String> TOKEN_MAP = new ConcurrentHashMap<>();
    private static final String ROOT_PREFIX = main.UPLOAD_ROOT.getPath() + File.separator;

    // 表面薄弱的清洗器: 仅删除第一处 ../
    static String weakSanitize(String s) {
        if (s == null) {
            return "default.bin";
        }
        return s.replaceFirst("\\.\\./", "");
    }

    // 令牌到服务端已登记文件名的间接映射
    static String mapToken(String token) {
        String mapped = token == null ? null : TOKEN_MAP.get(token);
        if (mapped == null) {
            return "orphan-" + Integer.toHexString(String.valueOf(token).hashCode()) + ".tmp";
        }
        return mapped;
    }

    static String register(String storedName) {
        String token = UUID.randomUUID().toString();
        TOKEN_MAP.put(token, storedName);
        return token;
    }

    // 落盘前二次校验父目录规范化结果
    static void persist(File target, byte[] data) throws IOException {
        File parent = target.getCanonicalFile().getParentFile();
        if (!parent.getPath().startsWith(ROOT_PREFIX)) {
            throw new IOException("policy violation");
        }
        try (FileOutputStream out = new FileOutputStream(target)) {
            out.write(data);
        }
    }
}
