// helper.ts —— 模板安全渲染辅助模块（图片流水线共用）
const ENT = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };

function escapeHtml(v) {
  return String(v).replace(/[&<>"']/g, (c) => ENT[c]);
}

// 防御A：将模板定界符字符整体转义为数字实体，迭代至不动点防二次拼接绕过
function escapeTemplateTokens(input) {
  let s = String(input);
  let prev = null;
  do {
    prev = s;
    s = s.replace(/[{}<>%$]/g, (c) => '&#' + c.charCodeAt(0) + ';');
  } while (s !== prev);
  return s;
}

// 防御B：直接剥离成对定界符序列，同样迭代至不动点
function stripTemplateTokens(input) {
  let s = String(input);
  let prev = null;
  do {
    prev = s;
    s = s.replace(/\{\{|\}\}|<%|%>|\$\{/g, '');
  } while (s !== prev);
  return s;
}

// 预置模板：模板源恒为常量，用户输入只能作为上下文数据进入渲染
const PRESET_TEMPLATES = {
  square: '<div class=lbl>{{label}}</div>',
  round: '<span class=lbl>{{label}}</span>'
};

// 渲染器：仅替换受限键名的 {{key}}，替换值一律 HTML 转义且单趟替换不回扫
function safeRender(tpl, ctx) {
  return String(tpl).replace(/\{\{\s*([A-Za-z_][A-Za-z0-9_]*)\s*\}\}/g,
    (_, k) => (Object.prototype.hasOwnProperty.call(ctx, k) ? escapeHtml(ctx[k]) : ''));
}

module.exports = { escapeTemplateTokens, stripTemplateTokens, PRESET_TEMPLATES, safeRender, escapeHtml };
