<?php
// helper.php -- 反序列化编解码与执行防护
class TaskCodec {
    // 流1: 前置 HMAC, allowed_classes=false 阻断对象注入
    public static function decode_signed(string $raw, $key): ?array {
        if (!is_string($key) || $key === '' || strlen($raw) < 66) { return null; }
        $mac = substr($raw, 0, 64); $body = substr($raw, 64);
        if (!hash_equals(hash_hmac('sha256', $body, $key), $mac)) { return null; }
        $val = unserialize($body, ['allowed_classes' => false]); if (!is_array($val)) { return null; }
        foreach ($val as $v) { if (!is_scalar($v)) { return null; } }
        return $val;
    }
    // 流2: 无签名但结构白名单, 仅允许标量键值
    public static function decode_plain(string $spec): ?array {
        if (!is_string($spec) || strlen($spec) > 4096) { return null; }
        $val = unserialize($spec, ['allowed_classes' => false, 'max_depth' => 4]); if (!is_array($val)) { return null; }
        foreach ($val as $k => $v) {
            if (!in_array($k, ['name', 'host', 'arg'], true) || !is_scalar($v)) { return null; }
        }
        return $val;
    }
}
class TaskRunner {
    public static function run(array $task): string {
        $name = $task['name'] ?? '';
        if (!is_string($name)) { return "bad task\n"; }
        $bin = CMD_MAP[$name] ?? null; // 仅查固定映射, 不拼接命令串
        if ($bin === null) { return "unknown task\n"; }
        $host = $task['host'] ?? '';
        if (!is_string($host) || !preg_match('/^[A-Za-z0-9.\-]{1,64}$/', $host)) { return "bad host\n"; }
        $arg = $task['arg'] ?? ''; if (!is_scalar($arg)) { return "bad arg\n"; }
        return shell_exec($bin . ' ' . escapeshellarg((string)$arg) . ' ' . escapeshellarg($host)) ?: '';
    }
}
class QueueStore {
    // 流3: 固定路径 + HMAC + json_decode, 不经过 unserialize
    public static function read_next(string $path): ?array {
        if ($path !== '/var/run/ops/queue.bin') { return null; }
        $blob = @file_get_contents($path); $key = getenv('OPS_HMAC_KEY');
        if (!is_string($blob) || !is_string($key) || $key === '' || strlen($blob) < 66) { return null; }
        if (!hash_equals(hash_hmac('sha256', substr($blob, 64), $key), substr($blob, 0, 64))) { return null; }
        $val = json_decode(substr($blob, 64), true); return is_array($val) ? $val : null;
    }
