package com.acme.cfgclient;

import java.util.HashMap;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
final class TemplateHelper {
    private static final Pattern PLACEHOLDER = Pattern.compile("\\$\\{([^}]+)\\}");
    private static final Pattern META = Pattern.compile("[$#<>{}]");
    private static final Map<String, String> BUILTIN =
            Map.of("page.home", "/home", "app.name", "cfg-client");

    // 流1: 入参已经 main 白名单校验, 此处拼入模板源
    static String renderGreeting(String name) {
        return evaluateModel("welcome, " + name + " @${page.home}", new HashMap<>());
    }

    // 流2: 模板源为常量, 用户值走数据模型, 不参与模板解析
    static String substituteRegion(String region) {
        Map<String, String> model = new HashMap<>();
        model.put("region", region);
        return evaluateModel("region=${region}", model);
    }

    // 流3: 先中和模板元字符, 再拼入模板源
    static String renderBanner(String body) {
        return evaluateModel("<div>" + neutralize(body) + "</div>", new HashMap<>());
    }

    static String evaluateModel(String tpl, Map<String, String> model) {
        Matcher m = PLACEHOLDER.matcher(tpl);
        StringBuilder out = new StringBuilder();
        while (m.find()) {
            String val = model.containsKey(m.group(1))
                    ? model.get(m.group(1)) : BUILTIN.getOrDefault(m.group(1), "");
            m.appendReplacement(out, Matcher.quoteReplacement(val));
        }
        m.appendTail(out);
        return out.toString();
    }

    private static String neutralize(String s) {
        return META.matcher(s).replaceAll(r -> "&#" + (int) r.group().charAt(0) + ";");
    }
}
