function retryWebhookFromDb(int $orderId): void {
    $order = db_fetch_order($orderId);
    if (!$order || empty($order['notify_url'])) { return; }
    $url = $order['notify_url'];                             // 二次注入污染数据
    httpPostJson($url, ['order_id' => $orderId, 'retry' => 1]);   // 未校验直达汇聚点
