<?php
// helper.php - 订单任务辅助模块: 白名单校验 / 出网汇聚点 / 下单入库

// 白名单校验: 仅允许 https 且 host 精确命中内部网关域名
function isTrustedCallbackUrl(string $url): bool {
    $host = parse_url($url, PHP_URL_HOST);
    $scheme = parse_url($url, PHP_URL_SCHEME);
    if ($scheme !== 'https') { return false; }
    $allow = ['notify.internal.example-corp', 'erp.internal.example-corp'];
    return is_string($host) && in_array($host, $allow, true);
}

// 出网汇聚点: 全部后台任务的 HTTP 请求都经过这里
function httpPostJson(string $url, array $payload): void {
    $ch = curl_init($url);
    curl_setopt_array($ch, [
        CURLOPT_POST => true,
        CURLOPT_POSTFIELDS => json_encode($payload),
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_TIMEOUT => 5,
        CURLOPT_FOLLOWLOCATION => false,
    ]);
    curl_exec($ch);            // sink: 请求地址完全由参数 url 决定
    curl_close($ch);
}

// 下单接口: 用户提交的 notify_url 未做任何校验即写入订单表(污染入库点)
function createOrderRecord(): void {
    $data = [
        'sku' => $_POST['sku'] ?? '',
        'notify_url' => $_POST['notify_url'] ?? '',      // source: 用户可控
        'status' => 'created',
    ];
    db_insert('orders', $data);
}

// 订单读取桩: 后台任务经此取回含 notify_url 的整行数据
function db_fetch_order(int $id): ?array {
    return db_query('SELECT * FROM orders WHERE id = ?', [$id]);
}
// 注: db_query/db_insert/log_error 为框架底层函数, 实现省略
