import re
from jinja2 import Environment, BaseLoader

ALLOWED_TEMPLATES = {
    "receipt": "<h2>上传回执</h2><p>文件: {{ name }}</p><p>备注: {{ note }}</p>",
    "reject": "<h2>已拒绝</h2><p>非法文件名: {{ name }}</p>",
}

_NAME_RE = re.compile(r"^[A-Za-z0-9._-]{1,64}$")
MAX_NOTE_LEN = 200
FALLBACK_NAME = "unnamed_file"


def build_env():
    return Environment(loader=BaseLoader(), autoescape=True)


def sanitize_filename(raw):
    """白名单净化: 剥离路径后仅放行安全字符集, 模板定界符必被拒."""
    if not isinstance(raw, str):
        return None
    name = raw.replace("\\", "/").rsplit("/", 1)[-1]
    if not _NAME_RE.match(name):
        return None
    return name


def render_receipt(kind, ctx):
    """kind 仅作内置常量模板的查找键, 数据一律作为上下文变量传入."""
    if kind not in ALLOWED_TEMPLATES:
        kind = "reject"
    return build_env().from_string(ALLOWED_TEMPLATES[kind]).render(**ctx)


def render_user_html(src, ctx):
    """仅供内部固定模板使用, 禁止传入用户可控字符串."""
    return build_env().from_string(src).render(**ctx)
