// helper.php - 图片流水线辅助模块

// 防御点A: 排序列白名单, 外部输入只能映射到固定列名
function resolveSortColumn($key) {
    $whitelist = ['date' => 'created_at', 'name' => 'title', 'size' => 'filesize'];
    if (is_string($key) && array_key_exists($key, $whitelist)) {
        return $whitelist[$key];
    }
    return 'created_at';
}

// 防御点B: 从上传的临时文件提取EXIF元数据
function extractImageMeta($tmpPath) {
    $exif = @exif_read_data($tmpPath);
    return [
        'title'  => isset($exif['ImageDescription']) ? $exif['ImageDescription'] : 'untitled',
        'camera' => isset($exif['Model']) ? $exif['Model'] : 'unknown',
    ];
}

// 防御点C: 入库全部参数化, 外键强制整型
function persistImageMeta(PDO $db, array $meta, $albumId) {
    $stmt = $db->prepare(
        'INSERT INTO image_meta (album_id, title, camera) VALUES (:aid, :t, :c)'
    );
    $stmt->bindValue(':aid', (int)$albumId, PDO::PARAM_INT);
    $stmt->bindValue(':t', $meta['title'], PDO::PARAM_STR);
    $stmt->bindValue(':c', $meta['camera'], PDO::PARAM_STR);
    $stmt->execute();
    return (int)$db->lastInsertId();
}
