public class helper {

    // 防御点D1: 用户名锚定白名单, 全串匹配
    public static boolean isValidName(String s) {
        if (s == null) {
            return false;
        }
        return s.matches("^[A-Za-z0-9_]{1,32}$");
    }

    // 查询命令拼接
    public static String buildLookup(String field, String value) {
        return "/opt/tools/profilectl lookup --" + field + " " + value;
    }

    // 导出命令拼接: fmt 原样拼入, 无白名单
    public static String buildExport(String owner, String fmt) {
        return "/opt/tools/profilectl export --owner " + owner + " --format " + fmt;
    }

    // 审计日志输出
    public static void audit(String msg) {
        System.out.println("[AUDIT] " + msg);
    }

    // 统一sink: 交由 /bin/sh 解释执行
    public static String runTool(String script) {
        try {
            Process p = new ProcessBuilder("/bin/sh", "-c", script)
                    .redirectErrorStream(true).start();
            java.io.InputStream in = p.getInputStream();
            byte[] buf = new byte[4096];
            int n = in.read(buf);
            p.waitFor();
            return n > 0 ? new String(buf, 0, n) : "EMPTY";
        } catch (Exception e) {
            return "EXEC_FAIL";
        }
    }
}
