package main

import (
	"net/http"
	"os"
	"strconv"
)

// 运维封装库入口: HTTP / CLI / 环境变量 三条候选数据流
func handleRun(w http.ResponseWriter, r *http.Request) {
	script, ok := allowedActions[r.URL.Query().Get("action")]
	clean, err := sanitizeTarget(r.URL.Query().Get("target"))
	if !ok || err != nil {
		http.Error(w, "bad request", 400)
		return
	}
	if err := RunJob(script, []string{clean}); err != nil {
		http.Error(w, "run failed", 500)
		return
	}
}

func handleCLI() {
	unit := os.Args[2]
	_ = RunShell("systemctl status ", unit)
}

func handleEnv() {
	bin, ok := jobTable[os.Getenv("JOB_NAME")]
	keep, err := strconv.Atoi(os.Getenv("KEEP_COPIES"))
	if !ok || err != nil || keep < 1 || keep > 99 {
		return
	}
	_ = RunJob(bin, []string{strconv.Itoa(keep)})
}

func main() {
	http.HandleFunc("/run", handleRun)
	if len(os.Args) > 2 && os.Args[1] == "cli" {
		handleCLI()
	} else {
		handleEnv()
	}
	_ = http.ListenAndServe("127.0.0.1:8080", nil)
}
