func sanitizeTarget(s string) (string, error) {
	if !argRe.MatchString(s) {
		return "", errors.New("illegal target")
	}
	return s, nil
}

func RunJob(bin string, args []string) error {
	if !pathRe.MatchString(bin) {
		return errors.New("binary not allowed")
	}
	for _, a := range args {
		if !argRe.MatchString(a) {
			return errors.New("illegal arg")
		}
	}
	return exec.Command(bin, args...).Run()
}

func RunShell(base, arg string) error {
	if !argRe.MatchString(arg) {
		return errors.New("illegal unit")
	}
	return exec.Command("sh", "-c", base+arg).Run()
}
