```javascript
const TEMPLATES = {
  upload_ok: '<p>file {{filename}} uploaded</p>',
  preview: '<pre>{{content}}</pre>'
};
const MAP = { '<': '&lt;', '>': '&gt;', '&': '&amp;', '"': '&quot;', "'": '&#39;', '{': '&#123;', '}': '&#125;', '$': '&#36;' };

function escapeHtml(s) {
  return String(s).replace(/[<>&"'{}$]/g, function (c) { return MAP[c]; });
}

// 防御A: 白名单校验在前, 定界符剔除在后, 双重清洗
function sanitizeFilename(name) {
  const base = String(name).split(/[\\/]/).pop();
  if (!/^[A-Za-z0-9._ -]{1,64}$/.test(base)) {
    return null;
  }
  return base.replace(/\{\{|\}\}|<%|%>|\$\{/g, '');
}

// 防御B: 只保留白名单字符, 任何模板定界符都无法存活
function stripTemplateSyntax(input) {
  return String(input).replace(/[^A-Za-z0-9._ -]/g, '').slice(0, 64);
}

// 防御C: 检出模板定界符即整体拒绝
function rejectTemplatePayload(text) {
  return /\{\{|\}\}|<%|%>|\$\{/.test(text) ? null : text;
}

// 安全渲染: 仅做占位符字面替换, 不编译不求值模板表达式
function renderTemplate(name, context) {
  let tpl = TEMPLATES[name];
  if (!tpl) throw new Error('unknown template');
  Object.keys(context).forEach(function (k) {
    tpl = tpl.split('{{' + k + '}}').join(escapeHtml(context[k]));
  });
  return tpl;
}

// 模板源码按纯文本转义输出, 永不进入任何编译器
function safeRender(tpl) {
  return escapeHtml(tpl);
}

module.exports = { sanitizeFilename, stripTemplateSyntax, rejectTemplatePayload, escapeHtml, renderTemplate, safeRender };
