package app.render;

import java.io.File;
import java.io.IOException;
import java.nio.file.Path;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import java.util.regex.Pattern;

/** 模板路径解析辅助模块 */
public class helper {
    static final File BASE;
    static final Pattern SAFE_NAME = Pattern.compile("^[A-Za-z0-9_-]{1,64}$");
    static final Set<String> THEMES = new HashSet<>(Arrays.asList("light", "dark", "classic"));
    static {
        try { BASE = new File("/var/app/templates").getCanonicalFile(); }
        catch (IOException e) { throw new IllegalStateException("base missing"); }
    }

    // 流1：模板名解析
    static Path resolveTemplate(String name) throws IOException {
        if (name == null) throw new IOException("missing template");
        String cleaned = name.replace("../", "");   // 先剥离显式穿越序列
        File target = new File(BASE, cleaned).getCanonicalFile();
        if (!target.getPath().startsWith(BASE.getPath() + File.separator))
            throw new IOException("traversal blocked");
        return target.toPath();
    }

    // 流2：主题目录解析
    static Path resolveThemeDir(String theme) throws IOException {
        if (theme == null || !THEMES.contains(theme)) throw new IOException("unknown theme");
        return new File(BASE, theme).getCanonicalFile().toPath();
    }

    // 流3：片段解析
    static Path loadFragment(String page) throws IOException {
        if (page == null || !SAFE_NAME.matcher(page).matches()) throw new IOException("bad fragment");
        return new File(BASE, "fragments").toPath().resolve(page + ".html");
    }
}
