from http.server import BaseHTTPRequestHandler, HTTPServer
from urllib.parse import urlparse, parse_qs
import helper

CONFIG_CACHE = {}

def sync_namespace(namespace):
    # 入口0: 拉取配置中心远端配置并缓存(污染源, 键值均不可信)
    remote = helper.fetch_namespace(namespace)
    CONFIG_CACHE[namespace] = remote

class ConsoleHandler(BaseHTTPRequestHandler):
    def do_GET(self):
        parsed = urlparse(self.path)
        qs = parse_qs(parsed.query)
        ns = qs.get('ns', ['default'])[0]
        if parsed.path == '/dashboard':
            sync_namespace(ns)
            body = helper.build_table(CONFIG_CACHE[ns])
        elif parsed.path == '/banner':
            sync_namespace(ns)
            key = qs.get('key', ['banner.text'])[0]
            val = CONFIG_CACHE[ns].get(key, '').strip()
            body = helper.render_banner(val)
        elif parsed.path == '/status':
            sync_namespace(ns)
            key = qs.get('key', ['health.tag'])[0]
            if not re.fullmatch(r'[A-Za-z0-9_]{1,32}', key):
                key = 'health.tag'
            val = CONFIG_CACHE[ns].get(key, '')
            body = helper.render_status(val)
        else:
            body = '<h1>config console</h1>'
        self._reply(body)

    def _reply(self, body):
        self.send_response(200)
        self.send_header('Content-Type', 'text/html; charset=utf-8')
        self.end_headers()
        self.wfile.write(body.encode('utf-8'))

if __name__ == '__main__':
    HTTPServer(('127.0.0.1', 8081), ConsoleHandler).serve_forever()
