import html
import json
import re
import urllib.request
from urllib.parse import quote

CONFIG_CENTER = 'http://config-center.internal:8848/v1'

def fetch_namespace(namespace):
    # 污染源: 返回配置中心原始配置, 键与值均为远端可控字符串
    url = CONFIG_CENTER + '/ns/' + quote(namespace, safe='')
    with urllib.request.urlopen(url, timeout=3) as resp:
        payload = json.loads(resp.read().decode('utf-8'))
    return {str(k): str(v) for k, v in payload.items()}

def build_table(pairs):
    rows = []
    for k in sorted(pairs):
        ck = html.escape(k, quote=True)
        cv = html.escape(pairs[k], quote=True)
        rows.append('<tr><th>%s</th><td>%s</td></tr>' % (ck, cv))
    return '<table>%s</table>' % ''.join(rows)

def render_banner(value):
    return '<div id="banner" data-text="%s"></div>' % _entity_encode(value)

def _entity_encode(value):
    table = {'<': '&lt;', '>': '&gt;', '&': '&amp;', '"': '&quot;', "'": '&#39;'}
    return ''.join(table.get(ch, ch) for ch in str(value))

def render_status(value):
    text = str(value)
    if not re.fullmatch(r'[A-Za-z0-9_.:-]{0,64}', text):
        text = 'unknown'
    return '<p class="status">state=%s</p>' % text
