// helper.ts —— XML 解析安全基线, 供 main.ts 三个入口共用
const libxmljs = require('libxmljs');
const { XMLParser } = require('fast-xml-parser');

// 防御A1: 报文级黑名单, 命中 DOCTYPE/ENTITY/SYSTEM/PUBLIC 即拒绝
const DTD_PATTERN = /<!DOCTYPE|<!ENTITY|SYSTEM\s*["']|PUBLIC\s*["']/i;

function rejectDtd(text) {
  if (typeof text !== 'string' || text.length === 0 || text.length > 262144) {
    return true;
  }
  return DTD_PATTERN.test(text);
}

// 防御基线: 禁实体替换/禁网络/禁外部 DTD, 作为强制覆盖项
const SAFE_OPTS = { noent: false, nonet: true, dtdload: false, dtdvalidate: false };

function parsePaymentXml(text) {
  const doc = libxmljs.parseXml(text, SAFE_OPTS);
  return { orderId: doc.get('//orderId').text(), amount: doc.get('//amount').text() };
}

function parseRefundXml(text, userOpts) {
  // 陷阱化解: userOpts 在前, SAFE_OPTS 末位强制覆盖, noent 恒为 false
  const opts = Object.assign({}, userOpts, SAFE_OPTS);
  const doc = libxmljs.parseXml(text, opts);
  return { userId: doc.get('//userId').text(), status: doc.get('//status').text() };
}

// 防御C: fast-xml-parser 不加载 DTD 不解析外部实体, processEntities 仅展开内置实体
const reconParser = new XMLParser({ processEntities: true, ignoreDeclaration: true });

function parseReconRows(text) {
  const obj = reconParser.parse(text);
  return (obj.reconReport && obj.reconReport.row) || [];
}

module.exports = { rejectDtd, parsePaymentXml, parseRefundXml, parseReconRows };
