import java.io.*;
import java.net.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;

public class main {
    static final ExecutorService pool = Executors.newFixedThreadPool(4);
    static final helper tools = new helper();

    // 入口1: 集群内部队列, 数据来自已完成双向认证的节点
    void onClusterSync(byte[] payload) {
        if (!tools.isAllowedClass(payload)) return;                // 防御1: 白名单
        dispatch(tools.deserialize(payload, tools.makeFilter())); // 防御2: 严格过滤器
    }

    // 入口2: 遗留副本同步协议, UDP 端口对任意对端开放
    void onLegacyReplicaPacket(DatagramPacket pkt) {
        byte[] raw = Arrays.copyOf(pkt.getData(), pkt.getLength());
        dispatch(tools.deserialize(raw, null));                   // 无任何校验
    }

    // 入口3: 本地检查点恢复, 固定路径仅由本进程上次运行写出
    void loadCheckpoint() {
        try {
            byte[] data = Files.readAllBytes(Paths.get("/var/lib/sync/ckpt.bin"));
            dispatch(tools.deserialize(data, tools.makeFilter())); // 防御: 严格过滤器
        } catch (IOException ignored) { }
    }

    void dispatch(Object obj) {
        if (obj instanceof Runnable) pool.submit((Runnable) obj); // 受控类被实例化执行
    }

    public static void main(String[] args) throws Exception {
        main w = new main();
        DatagramSocket sock = new DatagramSocket(9100);
        byte[] buf = new byte[8192];
        while (true) {
            DatagramPacket p = new DatagramPacket(buf, buf.length);
            sock.receive(p);
            w.onLegacyReplicaPacket(p);
        }
    }
}
