import java.io.*;
import java.util.*;

public class helper {
    private static final Set<String> ALLOWED = new HashSet<>(
        Arrays.asList("SyncTask", "SyncDelta", "SyncAck"));

    // 白名单校验: 解析序列化流头部首个类名
    boolean isAllowedClass(byte[] data) {
        if (data == null || data.length < 10) return false;
        if ((data[0] & 0xFF) != 0xAC || (data[1] & 0xFF) != 0xED) return false;
        try (DataInputStream in = new DataInputStream(new ByteArrayInputStream(data))) {
            in.readInt();                          // 流魔数与版本号
            if (in.read() != 0x73 || in.read() != 0x72) return false;
            byte[] nb = new byte[in.readUnsignedShort()];
            in.readFully(nb);
            return ALLOWED.contains(new String(nb, "UTF-8"));
        } catch (IOException e) {
            return false;
        }
    }

    // 严格过滤器: 仅放行同步白名单类与基础类
    ObjectInputFilter makeFilter() {
        return ObjectInputFilter.Config.createFilter(
            "SyncTask;SyncDelta;SyncAck;java.base/*;!*");
    }

    // 共享 sink: 反序列化任意字节, filter 为 null 时不设防
    Object deserialize(byte[] data, ObjectInputFilter filter) {
        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(data))) {
            if (filter != null) ois.setObjectInputFilter(filter);
            return ois.readObject();               // sink
        } catch (IOException | ClassNotFoundException e) {
            return null;
        }
    }
}
