const QUEUE_DIR = __DIR__ . '/storage/queue/';

function handleGatewayCallback(): string
{
    if (!isset($_SERVER['REMOTE_ADDR'])
        || !in_array($_SERVER['REMOTE_ADDR'], CALLBACK_IP_ALLOWLIST, true)) {
        return 'deny: source ip';
    }
    $raw = isset($_POST['payload']) ? (string)$_POST['payload'] : '';
    $sig = isset($_POST['sig']) ? (string)$_POST['sig'] : '';
    if (!verifyCallbackSignature($raw, $sig)) {
        return 'deny: signature';
    }
    $state = safeUnserialize($raw);
    if (!is_array($state) || !isset($state['order_id'], $state['amount'])) {
        return 'deny: state shape';
    }
    return settleOrder((string)$state['order_id'], (int)$state['amount']);
}

function handleRetryQueue(string $name): string
{
    $file = QUEUE_DIR . basename($name);
    $real = realpath($file);
    $base = realpath(QUEUE_DIR) . DIRECTORY_SEPARATOR;
    if (!is_string($real) || strpos($real, $base) !== 0) {
        return 'deny: queue path';
    }
    return replayQueuedState($real);
}

$entry = isset($_GET['action']) ? (string)$_GET['action'] : 'callback';
if ($entry === 'callback') {
    echo handleGatewayCallback();
} elseif ($entry === 'retry') {
    echo handleRetryQueue(isset($_GET['file']) ? (string)$_GET['file'] : '');
} else {
