<?php
// helper.php - 回调验签与状态还原辅助模块
function verifyCallbackSignature(string $raw, string $sig): bool
{
    $secret = getenv('PAYCALL_HMAC_KEY');
    return is_string($secret) && $secret !== ''
        && hash_equals(hash_hmac('sha256', $raw, $secret), $sig);
}
function safeUnserialize(string $raw)
{
    if (strlen($raw) > 65536) {
        return false;
    }
    return unserialize($raw, ['allowed_classes' => false]); // PHP7+ 禁止对象实例化
}
function replayQueuedState(string $file): string
{
    $blob = (string)file_get_contents($file);
    $sep = strrpos($blob, '|');
    if ($sep === false) {
        return 'deny: queue format';
    }
    $body = substr($blob, 0, $sep);
    if (!verifyCallbackSignature($body, (string)substr($blob, $sep + 1))) {
        return 'deny: queue signature';
    }
    $state = json_decode($body, true);
    if (!is_array($state) || !isset($state['order_id'])) {
        return 'deny: queue shape';
    }
    return settleOrder((string)$state['order_id'], (int)($state['amount'] ?? 0));
}
function handleDebugProbe(string $stateB64): string
{
    $raw = base64_decode($stateB64, true);
    if ($raw === false || preg_match('/^[OaC]:/', $raw) === 1) {
        return 'deny: probe format';
    }
    $state = safeUnserialize($raw);
    return is_array($state) && isset($state['order_id']) ? 'probe ok' : 'deny: probe shape';
}
function settleOrder(string $orderId, int $amount): string
{
    return 'settled ' . preg_replace('/[^A-Za-z0-9_-]/', '', $orderId) . ' amount=' . $amount;
}
