package main

import (
	"html/template"
	"io"
	"net/http"
)

// 入口A /render: 流1=tpl 远程模板拉取; 流2=inline 内联模板渲染; 流3=hook 渲染后回调
func handleRender(w http.ResponseWriter, r *http.Request) {
	q := r.URL.Query()
	partial, err := LoadRemoteTemplate(q.Get("tpl"))
	if err != nil {
		http.Error(w, "template rejected", http.StatusBadRequest)
		return
	}
	if err := RenderPage(w, partial, q.Get("inline")); err != nil {
		http.Error(w, "render failed", http.StatusInternalServerError)
		return
	}
	go NotifyWebhook(q.Get("hook"), partial)
}

// 入口B /hook: 流3b 独立回调入口, 复用 NotifyWebhook 内部校验
func handleHook(w http.ResponseWriter, r *http.Request) {
	q := r.URL.Query()
	go NotifyWebhook(q.Get("hook"), q.Get("payload"))
	w.WriteHeader(http.StatusAccepted)
}

// 流2 渲染: inline 被解析为模板, fetch 动作复用 LoadRemoteTemplate 防御
func RenderPage(w io.Writer, partial, inline string) error {
	tpl, err := template.New("page").Funcs(template.FuncMap{"fetch": LoadRemoteTemplate}).Parse(inline)
	if err != nil {
		return err
	}
	return tpl.Execute(w, partial)
}

func main() {
	http.HandleFunc("/render", handleRender)
	http.HandleFunc("/hook", handleHook)
	http.ListenAndServe(":8080", nil)
}
