package main
import (
	"fmt"
	"io"
	"net/http"
	"net/url"
	"strings"
	"time"
)

// 白名单: 仅企业模板域与回调域, 精确匹配而非后缀匹配
var allowed = map[string]bool{"templates.corp.example.com": true, "hooks.corp.example.com": true}
// 统一防御: 强制 https + 精确主机白名单 + 仅 443 端口
func checkURL(raw string) error {
	u, err := url.Parse(raw)
	if err != nil || u.Scheme != "https" || !allowed[strings.ToLower(u.Hostname())] || (u.Port() != "" && u.Port() != "443") {
		return fmt.Errorf("rejected")
	}
	return nil
}
// 出口客户端: 每一跳重定向都重新过白名单, 防重定向绕过
var client = &http.Client{Timeout: 3 * time.Second, CheckRedirect: func(req *http.Request, via []*http.Request) error {
	return checkURL(req.URL.String())
}}
// 流1/流2 共用 sink: 远程模板拉取, 响应体 64KB 上限
func LoadRemoteTemplate(raw string) (string, error) {
	if err := checkURL(raw); err != nil {
		return "", err
	}
	resp, err := client.Get(raw)
	if err != nil {
		return "", err
	}
	defer resp.Body.Close()
	b, _ := io.ReadAll(io.LimitReader(resp.Body, 1<<16))
	return string(b), nil
}
// 流3/流3b sink: 回调通知, 复用同一 checkURL 防御
