        String env = helper.ENV_MAP.get(envKey);
        Map<String, String> ctx = new HashMap<>();
        ctx.put("tag", tag);
        ctx.put("env", env != null ? env : helper.DEFAULT_ENV);
        return helper.exec(helper.renderTemplate("deploy", ctx));
    }

    public static void main(String[] args) {
        runJob(args[0], args.length > 1 ? args[1] : "localhost");
