package opslib;
import java.util.HashMap;
import java.util.Map;

public class helper {
    static final Map<String, String> TEMPLATES = new HashMap<>();
    static final Map<String, String> ENV_MAP = new HashMap<>();
    static final String DEFAULT_ENV = "staging";
    static {
        TEMPLATES.put("restart", "systemctl restart ${target}");
        TEMPLATES.put("status", "systemctl status ${target}");
        TEMPLATES.put("grep", "journalctl --grep ${filter}");
        TEMPLATES.put("deploy", "deploy.sh --tag ${tag} --env ${env}");
        ENV_MAP.put("prod", "production");
        ENV_MAP.put("dev", "development");
    }
    // 值级净化: 剥离模板与 shell 元字符及一切空白
    static String sanitizeValue(String v) {
        if (v == null) return "";
        return v.replaceAll("[$ {}#%!`;|&<>()\\s]", "");
    }
    // 白名单校验: 发布标签仅允许有限字符集
    static boolean isSafeTag(String tag) {
        return tag != null && tag.matches("[a-z0-9][a-z0-9._-]{0,63}");
    }
    // 模板体只能来自常量注册表, 用户输入仅作键查找
    static String renderTemplate(String name, Map<String, String> ctx) {
        String tpl = TEMPLATES.get(name);
        if (tpl == null) throw new IllegalArgumentException("unknown template");
        String out = tpl;
        for (Map.Entry<String, String> e : ctx.entrySet()) {
            out = out.replace("${" + e.getKey() + "}", sanitizeValue(e.getValue()));
        }
        return out;
    }
    // 无 shell 执行: 按空白切分, 元字符不会被二次解释
    static boolean exec(String cmd) {
        try {
            Process p = new ProcessBuilder(cmd.trim().split("\\s+")).start();
            return p.waitFor() == 0;
        } catch (Exception ex) {
            return false;
        }
    }
}
