// 入口1: POST /fetch 表单提交图片URL与回调地址
func handleFetch(w http.ResponseWriter, r *http.Request) {
	img := r.FormValue("image_url")
	cb := r.FormValue("callback")
	u, err := url.Parse(img)
	if err != nil || (u.Scheme != "http" && u.Scheme != "https") || u.Hostname() == "" {
		http.Error(w, "rejected", http.StatusForbidden)
		return
	}
	if CheckCallback(cb) != nil {
		http.Error(w, "rejected", http.StatusForbidden)
		return
	}
	data, err := Fetch(u.String())
	if err != nil {
		http.Error(w, "fetch failed", http.StatusBadGateway)
		return
	}
	go Fetch(cb)
	w.Write(data)
}

// 入口2: GET /thumb 资源名仅拼入固定主机之后的路径, host段不可控
func handleThumb(w http.ResponseWriter, r *http.Request) {
	target := "http://assets.internal.svc/static/" + r.URL.Query().Get("name")
	data, err := Fetch(target)
	if err != nil {
		http.Error(w, "fetch failed", http.StatusBadGateway)
		return
	}
	w.Write(data)
}

func main() {
	http.HandleFunc("/fetch", handleFetch)
	http.HandleFunc("/thumb", handleThumb)
	log.Fatal(http.ListenAndServe("127.0.0.1:8080", nil))
}
