package main
import (
	"context"
	"errors"
	"io"
	"net"
	"net/http"
	"net/url"
)
// dialGuard 建连期解析目标并校验IP: 环回/私网/链路本地/未指定一律拒绝
func dialGuard(ctx context.Context, network, addr string) (net.Conn, error) {
	tcp, err := net.ResolveTCPAddr(network, addr)
	if err != nil {
		return nil, err
	}
	if tcp.IP == nil || tcp.IP.IsLoopback() || tcp.IP.IsPrivate() || tcp.IP.IsLinkLocalUnicast() || tcp.IP.IsUnspecified() {
		return nil, errors.New("internal address blocked")
	}
	return new(net.Dialer).DialContext(ctx, network, tcp.String())
}
// client 唯一出站通道: 重定向限3跳并逐跳复核scheme, 建连必经dialGuard
var client = &http.Client{
	CheckRedirect: func(req *http.Request, via []*http.Request) error {
		if len(via) >= 3 || (req.URL.Scheme != "http" && req.URL.Scheme != "https") {
			return errors.New("redirect rejected")
		}
		return nil
	},
	Transport: &http.Transport{DialContext: dialGuard},
}
func CheckCallback(raw string) error {
	u, err := url.Parse(raw)
	if err != nil || u.Scheme != "https" || u.Hostname() != "hooks.internal.example" {
		return errors.New("callback host not allowed")
	}
	return nil
}
func Fetch(u string) ([]byte, error) {
	resp, err := client.Get(u)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	return io.ReadAll(io.LimitReader(resp.Body, 1<<20))
}
