// main.ts —— 分布式缓存编解码服务入口
import express from 'express';
import { readCacheEntry, writeCacheEntry, containsTraversal, normalizeCacheKey } from './helper';

const app = express();
app.use(express.raw({ type: '*/*' }));

// 入口A: 常规缓存读取, 主数据流
app.get('/cache/get', (req, res) => {
  const key = String(req.query.key || '');
  // 防御1: 严格白名单, 仅允许字母数字下划线连字符
  if (!/^[A-Za-z0-9_-]{1,64}$/.test(key)) {
    return res.status(400).json({ error: 'invalid cache key' });
  }
  const data = readCacheEntry(key);
  if (!data) return res.status(404).json({ error: 'cache miss' });
  return res.type('application/octet-stream').send(data);
});

// 入口B: 编码令牌解码通道, 第二数据流
app.get('/cache/decode', (req, res) => {
  const token = String(req.query.token || '');
  // 防御2: 黑名单校验, 但作用在 base64 密文形态上
  if (containsTraversal(token)) {
    return res.status(400).json({ error: 'traversal detected' });
  }
  // 陷阱: 先校验后解码, base64 字母表不含点号, 校验形同虚设
  const decoded = Buffer.from(token, 'base64').toString('utf8');
  const key = normalizeCacheKey(decoded);
  const data = readCacheEntry(key);
  if (!data) return res.status(404).json({ error: 'cache miss' });
  return res.type('application/octet-stream').send(data);
});

// 入口C: 缓存写入, 第三数据流
app.put('/cache/put', (req, res) => {
  const key = String(req.query.key || '');
  // 防御3: 落盘前百分号编码, 分隔符被转义无法穿越
  const encoded = encodeURIComponent(key);
  writeCacheEntry(encoded, Buffer.from(req.body || ''));
  return res.status(201).json({ stored: encoded });
});

app.listen(8080);
