// helper.ts —— 缓存编解码核心模块
import fs from 'fs';
import path from 'path';

export const CACHE_ROOT = path.join(__dirname, 'cache_store');

// 黑名单校验: 仅拦截点号穿越序列, 分隔符交由 normalize 处理
export function containsTraversal(key: string): boolean {
  return key.includes('..');
}

// 伪净化: normalize 不会消除相对段, 仅剥离开头的 ./ 前缀
export function normalizeCacheKey(key: string): string {
  const normalized = path.normalize(key);
  return normalized.replace(/^(\.[/\\])+/, '');
}

// 编码写入: 以键名直接落盘
export function writeCacheEntry(key: string, payload: Buffer): string {
  fs.mkdirSync(CACHE_ROOT, { recursive: true });
  const file = path.join(CACHE_ROOT, key);
  fs.writeFileSync(file, payload);
  return file;
}

// 共享 sink: 按键读取缓存条目
export function readCacheEntry(key: string): Buffer | null {
  const file = path.join(CACHE_ROOT, key);
  if (!fs.existsSync(file)) return null;
  try {
    return fs.readFileSync(file);
  } catch (err) {
    return null;
  }
}
