    // 流1：模板引用被直接 include；allow_url_include 开启时可注入 http/data 包装器，亦可拼接 ../ 穿越
    include $tplName;
    $rendered = ob_get_clean();

    global $CHANNEL_TEMPLATES;
    // 流2：固定白名单映射，不存在的键回退 generic，被包含值恒为库内文件
    $safeTpl = $CHANNEL_TEMPLATES[$channel] ?? $CHANNEL_TEMPLATES['generic'];
    include __DIR__ . '/' . $safeTpl;

    // 流3：locale 严格校验 + basename + 目录限定 + 存在性检查
    if (preg_match('/^[a-z]{2}(_[A-Z]{2})?$/', $locale)) {
        $locFile = __DIR__ . '/locales/' . basename($locale) . '.php';
        if (is_file($locFile)) {
            include $locFile;
        }
    }

    return $rendered . json_encode(['data' => $payload]);
