	http.HandleFunc("/apply", handleApply)
	log.Fatal(http.ListenAndServe(":8081", nil))
}

// 入口A: 配置中心轮询, 远端值流入三条链路
func poll() {
	addr := os.Getenv("CONFIG_ADDR")
	for {
		if resp, err := http.Get(addr + "/v1/snapshot"); err == nil {
			var s Snapshot
			if json.NewDecoder(resp.Body).Decode(&s) == nil {
				_ = RunTool(s.Tool)
				_ = RunHook(s.Hook)
				_ = SyncHost(s.Host)
			}
			resp.Body.Close()
		}
		time.Sleep(30 * time.Second)
	}
}
// 入口B: 运维手工触发同三条链路
func handleApply(w http.ResponseWriter, r *http.Request) {
	_, _ = RunTool(r.URL.Query().Get("tool"))
	_ = RunHook(r.URL.Query().Get("hook"))
	_ = SyncHost(r.URL.Query().Get("host"))
	_, _ = w.Write([]byte("done"))
}
