// toolTable: 键收外部输入, 值为硬编码路径
var toolTable = map[string]string{"backup": "/usr/local/bin/backup.sh", "cleanup": "/usr/local/bin/cleanup.sh"}

// hookTable: 键收外部输入, 值为硬编码完整命令
var hookTable = map[string]string{"reload": "systemctl reload appd", "rotate": "logrotate /etc/logrotate.d/appd"}

var nameRe = regexp.MustCompile(`^[a-z0-9_]{1,24}$`)
var hostRe = regexp.MustCompile(`^[a-zA-Z0-9.][a-zA-Z0-9.:-]{0,63}$`)

// 流1: 外部名仅作查表键, 实际执行路径取自硬编码表
func RunTool(name string) (string, error) {
	path, ok := toolTable[name]
	if !ok || !nameRe.MatchString(name) {
		return "", fmt.Errorf("tool rejected")
	}
	out, err := exec.Command(path).CombinedOutput()
	return string(out), err
}

// 流2: 外部键查表得常量命令后经 sh -c 执行
func RunHook(key string) error {
	cmdStr, ok := hookTable[key]
	if !ok || !nameRe.MatchString(key) {
		return fmt.Errorf("hook rejected")
	}
	return exec.Command("sh", "-c", cmdStr).Run()
}

// 流3: 主机拆分校验后仅作独立参数, 不经 shell
func SyncHost(hostport string) error {
	h, port, err := net.SplitHostPort(hostport)
	if err != nil || port != "123" || !hostRe.MatchString(h) {
		return fmt.Errorf("host rejected")
	}
	return exec.Command("ntpdate", "-u", h).Run()
}
