package main

import (
	"encoding/json"
	"net/http"
	"strings"
)

// 防御B: 入口2 专用白名单, host 精确匹配且 path 必须以斜杠开头
func AllowedHost(host string) bool {
	return host == "files.example.com"
}

// 上传管理器入口1: /fetch 拉取用户提交的远程文件 URL
func fetchHandler(w http.ResponseWriter, r *http.Request) {
	FetchRemote(w, r.URL.Query().Get("url"))
}

// 入口2: /import 从表单 host 与 path 拼接合作站点地址
func importHandler(w http.ResponseWriter, r *http.Request) {
	host, path := r.FormValue("host"), r.FormValue("path")
	if !AllowedHost(host) || !strings.HasPrefix(path, "/") {
		http.Error(w, "host or path denied", http.StatusForbidden)
		return
	}
	FetchRemote(w, "https://"+host+path)
}

// 入口3: /webhook 解析 JSON body 的 callback 字段拉取
func webhookHandler(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Callback string `json:"callback"`
	}
	if json.NewDecoder(r.Body).Decode(&req) != nil {
		http.Error(w, "bad body", http.StatusBadRequest)
		return
	}
	FetchRemote(w, req.Callback)
}

func main() {
	http.HandleFunc("/fetch", fetchHandler)
	http.HandleFunc("/import", importHandler)
	http.HandleFunc("/webhook", webhookHandler)
	http.ListenAndServe(":8080", nil)
}
