package main

import (
	"io"
	"net"
	"net/http"
	"net/url"
	"time"
)

// 防御A: 全局客户端禁止跟随重定向, 阻断 302 跳转内网绕过
var client = &http.Client{Timeout: 5 * time.Second,
	CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse },
}

// 防御C: 逐 IP 校验, 拒绝环回/私网/链路本地/未指定地址
func isForbiddenIP(ip net.IP) bool {
	return ip.IsLoopback() || ip.IsPrivate() || ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast() || ip.IsUnspecified()
}

// 防御D: 仅允许 https 与 443 端口, 先解析 DNS 校验全部地址再请求
func FetchRemote(w http.ResponseWriter, raw string) {
	u, err := url.Parse(raw)
	if err != nil || u.Scheme != "https" || u.Hostname() == "" || (u.Port() != "" && u.Port() != "443") {
		http.Error(w, "scheme or host rejected", http.StatusForbidden)
		return
	}
	ips, err := net.LookupIP(u.Hostname())
	if err != nil {
		http.Error(w, "resolve failed", http.StatusForbidden)
		return
	}
	for _, ip := range ips {
		if isForbiddenIP(ip) {
			http.Error(w, "private address blocked", http.StatusForbidden)
			return
		}
	}
	resp, err := client.Get(u.String())
	if err != nil {
		http.Error(w, "request failed", http.StatusBadGateway)
		return
	}
	defer resp.Body.Close()
	io.Copy(w, resp.Body)
}
