package main

import (
	"io"
	"log"
	"net/http"
	"os"
)

var sender *WebhookSender

func main() {
	sender = &WebhookSender{token: os.Getenv("OUTBOUND_TOKEN")}
	mux := http.NewServeMux()
	mux.HandleFunc("/v1/route/import", handleImport)
	mux.HandleFunc("/v1/route/preview", handlePreview)
	mux.HandleFunc("/v1/route/mirror", handleMirror)
	log.Fatal(http.ListenAndServe(":8080", mux))
}
func handleImport(w http.ResponseWriter, r *http.Request) {
	body, _ := io.ReadAll(io.LimitReader(r.Body, 1<<20))
	target, err := ImportRoute(body)
	if err != nil {
		http.Error(w, "invalid route", 400)
		return
	}
	go sender.Deliver(target, []byte(`{"event":"ping"}`))
	w.WriteHeader(204)
}
func handlePreview(w http.ResponseWriter, r *http.Request) {
	body, _ := io.ReadAll(io.LimitReader(r.Body, 1<<20))
	if err := PreviewRoute(body, r.Header.Get("X-Route-Kind")); err != nil {
		http.Error(w, "preview rejected", 400)
		return
	}
	w.WriteHeader(204)
}
func handleMirror(w http.ResponseWriter, r *http.Request) {
	body, _ := io.ReadAll(io.LimitReader(r.Body, 1<<20))
	if err := MirrorPayload(sender, body); err != nil {
		http.Error(w, "mirror rejected", 400)
		return
	}
	w.WriteHeader(204)
}
