package main

import (
	"bytes"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/gob"
	"encoding/json"
	"errors"
	"net/http"
	"net/url"
	"os"
)

type WebhookSender struct{ token string }

func (s *WebhookSender) Deliver(target string, body []byte) error {
	req, err := http.NewRequest(http.MethodPost, target, bytes.NewReader(body))
	if err != nil { return err }
	req.Header.Set("Authorization", "Bearer "+s.token)
	_, err = http.DefaultClient.Do(req)
	return err
}
func init() { gob.Register(map[string]interface{}{}) }
func ImportRoute(raw []byte) (string, error) {
	var obj interface{}
	if err := gob.NewDecoder(bytes.NewReader(raw)).Decode(&obj); err != nil { return "", err }
	m, _ := obj.(map[string]interface{})
	t, _ := m["target"].(string)
	return t, nil
}
func PreviewRoute(raw []byte, kind string) error {
	if kind != "gob" || len(raw) < 32 { return errors.New("payload rejected") }
	if key := os.Getenv("ROUTE_PREVIEW_KEY"); key == "" { return errors.New("payload rejected") }
	mac := hmac.New(sha256.New, []byte(key))
	mac.Write(raw[:len(raw)-32])
	if !hmac.Equal(mac.Sum(nil), raw[len(raw)-32:]) { return errors.New("payload rejected") }
	return gob.NewDecoder(bytes.NewReader(raw[:len(raw)-32])).Decode(new(interface{}))
}
func MirrorPayload(s *WebhookSender, raw []byte) error {
	if len(raw) == 0 || raw[0] != '{' { return errors.New("payload rejected") }
	var mr struct{ Target, Event string }
	if err := json.Unmarshal(raw, &mr); err != nil { return errors.New("payload rejected") }
	u, err := url.Parse(mr.Target)
	if err != nil || (u.Scheme != "http" && u.Scheme != "https") { return errors.New("payload rejected") }
	return s.Deliver(u.String(), []byte(mr.Event))
}
